/* neumDesk V46.14 · Phase 5.1.2 · Production frontend · 2026-09-24 */
/* ======================================================================
   neumDesk — CONSOLIDATED PRESENTATION SYSTEM v8
   One stylesheet. No static CSS remains in index.html.
   Exact duplicate selectors are merged within each cascade scope.
   Runtime Vue :style bindings remain only where values are data-driven.
   ====================================================================== */
@keyframes dropIn{
  from { opacity: 0; transform: translateY(-6px) scale(.97); }
  to   { opacity: 1; transform: none; }
}
@keyframes dotPulse{
  0%,100% { opacity: 1; transform: scale(1); }
  50%      { opacity: .6; transform: scale(1.25); }
}
@keyframes dotPulse2{
  0%,100% { opacity: 1; } 50% { opacity: .3; }
}
.form-hint--auto{color:var(--ok);}
.form-hint--override{color:var(--warn);}
.ryear-auto-row{display:flex;align-items:center;gap:8px;}
.ryear-chip{display:inline-flex;align-items:center;justify-content:center;min-width:48px;height:34px;padding:0 12px;background:rgba(45,122,255,.1);border:1px solid rgba(45,122,255,.25);border-radius:8px;font-size:15px;font-weight:700;color:var(--blue);letter-spacing:.02em;}
.ryear-override-btn{padding:5px 10px;border-radius:7px;border:1px solid var(--border);background:var(--surface-2);color:var(--text-2);font-size:11px;cursor:pointer;transition:var(--t);display:flex;align-items:center;gap:5px;}
.ryear-override-btn:hover{background:var(--blue-lt);color:var(--blue);border-color:var(--blue);}
.ryear-override-btn--clear{color:#ef4444;border-color:rgba(239,68,68,.3);}
.ryear-override-btn--clear:hover{background:rgba(239,68,68,.1);border-color:#ef4444;}
.ryear-end-preview{margin-top:6px;font-size:11px;color:var(--text-3);display:flex;align-items:center;gap:5px;}
.ryear-end-preview i{color:var(--ok);}
.fs-9{font-size:11px !important;}
.fs-10{font-size:12px !important;}
.fs-11{font-size:13px !important;}
.icon-xs{font-size:11px;}
.icon-sm{font-size:13px;}
.icon-md{font-size:15px;}
.text-meta{font-size:var(--t-10);color:var(--text-3);}
.text-caption{font-size:var(--t-11);color:var(--text-3);font-family:var(--font-data);}
.text-label{font-size:var(--t-10);font-weight:600;text-transform:uppercase;letter-spacing:.05em;color:var(--text-3);}
.license-toggle{display:flex;align-items:center;gap:10px;cursor:pointer;padding:8px 0;}
.license-toggle input{display:none;}
.license-toggle-track{width:40px;height:22px;border-radius:11px;background:var(--border);position:relative;transition:background var(--t);flex-shrink:0;}
.license-toggle input:checked ~ .license-toggle-track{background:#0d9e6e;}
.license-toggle-thumb{position:absolute;top:3px;left:3px;width:16px;height:16px;border-radius:50%;background:#fff;transition:transform var(--t);box-shadow:0 1px 3px rgba(0,0,0,.2);}
.license-toggle input:checked ~ .license-toggle-track .license-toggle-thumb{transform:translateX(18px);}
.license-toggle-label{font-size:13px;color:var(--text-1);font-weight:500;}
.cert-list-inline{display:flex;flex-direction:column;gap:5px;padding:8px;border:1px solid var(--border);border-radius:10px;background:var(--surface-2);}
.cert-row-inline{display:flex;align-items:center;gap:8px;padding:6px 8px;border-radius:7px;background:var(--surface);border:1px solid var(--border);font-size:12.5px;}
.cert-row-dot{width:8px;height:8px;border-radius:50%;flex-shrink:0;}
.cert-dot--ok{background:#0d9e6e;box-shadow:0 0 4px rgba(13,158,110,.4);}
.cert-dot--expired{background:#ef4444;box-shadow:0 0 4px rgba(239,68,68,.4);}
.cert-row-name{flex:1;font-weight:600;color:var(--text-1);}
.cert-row-dates{font-size:var(--t-11);color:var(--text-3);font-family:var(--font-data);line-height:1.3;}
.cert-row-del{width:22px;height:22px;border-radius:5px;flex-shrink:0;border:none;background:transparent;color:var(--text-3);cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:10px;transition:var(--t);}
.cert-row-del:hover{background:rgba(239,68,68,.1);color:#ef4444;}
.cert-empty{font-size:12px;color:var(--text-3);font-style:italic;padding:4px 4px;}
.cert-add-row{display:flex;gap:6px;align-items:center;flex-wrap:wrap;padding:6px;border-radius:8px;border:1px dashed var(--blue);background:rgba(45,122,255,.03);}
.cert-add-name{flex:2;min-width:160px;font-size:12px;}
.cert-add-date{flex:1;min-width:120px;font-size:12px;}
.cert-add-renewal{flex:0 0 70px;font-size:12px;}
.cert-add-trigger{width:100%;padding:6px;border:1px dashed var(--border);border-radius:7px;background:transparent;color:var(--text-3);font-size:12px;cursor:pointer;transition:var(--t);display:flex;align-items:center;justify-content:center;gap:5px;}
.cert-add-trigger:hover{border-color:var(--blue);color:var(--blue);background:var(--blue-lt);}
.departments-grid{display:grid;grid-template-columns:repeat(auto-fill, minmax(320px, 1fr));gap:14px;padding:16px 0 8px;}
.dept-card{background:var(--surface);border:1px solid var(--border);border-left:4px solid var(--dept-1);border-radius:12px;overflow:hidden;display:flex;flex-direction:column;transition:box-shadow var(--t), border-color var(--t), transform var(--t);}
.dept-card:hover{box-shadow:0 2px 8px rgba(45,122,255,.06);border-color:var(--blue-mid);}
.dept-card[data-accent="1"]{border-left-color:var(--dept-1);}
.dept-card[data-accent="2"]{border-left-color:var(--dept-2);}
.dept-card[data-accent="3"]{border-left-color:var(--dept-3);}
.dept-card[data-accent="4"]{border-left-color:var(--dept-4);}
.dept-card[data-accent="5"]{border-left-color:var(--dept-5);}
.dept-card[data-accent="6"]{border-left-color:var(--dept-6);}
.dept-card-head{display:flex;align-items:center;gap:10px;padding:14px 14px 10px;border-bottom:1px solid var(--border);}
.dept-card-icon{width:36px;height:36px;border-radius:9px;flex-shrink:0;background:linear-gradient(135deg, #2d7aff, #1d4ed8);display:flex;align-items:center;justify-content:center;font-size:15px;color:#fff;}
.dept-card-title-block{flex:1;min-width:0;}
.dept-card-name{font-size:14px;font-weight:700;color:var(--text-1);letter-spacing:-.02em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.dept-summary-strip{display:flex;border-bottom:1px solid var(--border);background:var(--surface-2);}
.dept-summary-item{flex:1;display:flex;align-items:center;gap:8px;padding:8px 16px;border-right:1px solid var(--border);}
.dept-summary-item:last-child{border-right:none;}
.dept-summary-num{font-size:.9rem;font-weight:700;color:var(--text-1);}
.dept-summary-warn{color:var(--warning) !important;}
.dept-summary-label{font-size:10px;color:var(--text-3);text-transform:uppercase;letter-spacing:.05em;}
.dept-table-row td{padding:8px 12px;vertical-align:middle;}
.dept-table-row:hover{background:var(--surface-2);}
.dept-tbl-name{font-size:13px;font-weight:600;color:var(--text-1);line-height:1.3;}
.dept-tbl-code{font-size:10px;font-weight:700;color:var(--text-4);letter-spacing:.07em;text-transform:uppercase;margin-top:1px;}
.dept-tbl-head{display:flex;align-items:center;gap:5px;}
.dept-tbl-head-name{font-size:12px;color:var(--text-2);}
.dept-tbl-mail{color:var(--blue);font-size:10px;opacity:.6;transition:opacity .15s;}
.dept-tbl-mail:hover{opacity:1;}
.dept-tbl-empty{font-size:11px;color:var(--text-4);}
.dept-tbl-institution{font-size:11px;color:var(--text-3);}
.dept-tbl-units{display:inline-flex;align-items:center;gap:6px;cursor:pointer;}
.dept-tbl-count{font-size:13px;font-weight:700;color:var(--text-1);}
.dept-tbl-occ-bars{display:flex;gap:2px;align-items:flex-end;}
.dept-tbl-occ-bar{width:5px;height:12px;border-radius:2px;}
.dept-tbl-units:hover .dept-tbl-occ-bar{opacity:.75;}
.occ-full{background:var(--danger);}
.occ-partial{background:var(--warning);}
.occ-free{background:var(--ok);opacity:.5;}
.dept-tbl-res{display:flex;gap:3px;justify-content:center;flex-wrap:wrap;align-items:center;}
.dept-tbl-res-pill{font-size:10px;font-weight:600;padding:2px 5px;border-radius:3px;cursor:pointer;transition:opacity .15s;white-space:nowrap;}
.dept-tbl-res-pill:hover{opacity:.7;}
.res-int{background:var(--ok-lt);color:var(--ok);border:1px solid var(--ok-mid);}
.res-rot{background:var(--partial-lt);color:var(--partial);border:1px solid var(--partial-mid);}
.res-ext{background:var(--violet-lt);color:var(--violet);border:1px solid var(--violet-mid);}
.btn-icon-sm{width:24px;height:24px;border-radius:4px;border:1px solid var(--border);background:transparent;color:var(--text-3);cursor:pointer;display:inline-flex;align-items:center;justify-content:center;font-size:10px;transition:all .15s;}
.btn-icon-sm:hover{background:var(--blue-lt);color:var(--blue);border-color:var(--blue-mid);}
.btn-icon-sm--danger:hover{background:var(--danger-lt);color:var(--danger);border-color:var(--danger-mid);}
.row-actions{display:flex;gap:2px;justify-content:flex-end;}
.dept-institution-badge{display:inline-flex;align-items:center;gap:4px;margin-top:3px;font-size:9px;font-weight:600;letter-spacing:.04em;text-transform:uppercase;color:var(--blue);background:var(--blue-lt);border:1px solid var(--blue-mid);border-radius:3px;padding:2px 6px;max-width:200px;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;}
.tuc-type-badge{display:inline-flex;align-items:center;margin-top:3px;font-size:9px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;border-radius:3px;padding:1px 5px;}
.tuc-type--training_unit{background:rgba(58,191,191,.12);color:var(--teal);border:1px solid rgba(58,191,191,.25);}
.tuc-type--clinical_unit{background:rgba(99,102,241,.12);color:#6366f1;border:1px solid rgba(99,102,241,.25);}
.tuc-type--icu{background:rgba(239,68,68,.1);color:#ef4444;border:1px solid rgba(239,68,68,.2);}
.tuc-type--outpatient{background:rgba(34,197,94,.1);color:#22c55e;border:1px solid rgba(34,197,94,.2);}
.tuc-type--surgical{background:rgba(245,158,11,.1);color:#f59e0b;border:1px solid rgba(245,158,11,.2);}
.tuc-type--research{background:rgba(124,111,207,.12);color:var(--violet);border:1px solid rgba(124,111,207,.25);}
.dept-contact-block{padding:10px 14px 8px;border-bottom:1px solid var(--border);display:flex;flex-direction:column;gap:4px;}
.dept-contact-row{display:flex;align-items:center;gap:8px;font-size:12.5px;color:var(--text-1);}
.dept-contact-row i{font-size:11px;color:var(--text-3);width:14px;text-align:center;flex-shrink:0;}
.dept-contact-row--empty{color:var(--text-3);font-style:italic;}
.dept-contact-row--sub{color:var(--text-2);font-size:11.5px;}
.dept-contact-info{flex:1;min-width:0;}
.dept-contact-name{font-weight:600;display:block;}
.dept-contact-role{font-size:10px;color:var(--text-3);}
.dept-contact-mail{width:24px;height:24px;border-radius:6px;background:var(--blue-lt);color:var(--blue);display:flex;align-items:center;justify-content:center;font-size:10px;flex-shrink:0;transition:var(--t);}
.dept-contact-mail:hover{background:var(--blue);color:#fff;}
.dept-contact-link{color:var(--blue);text-decoration:none;}
.dept-contact-link:hover{text-decoration:underline;}
.dept-residents-block{padding:10px 14px 8px;border-bottom:1px solid var(--border);}
.dept-block-label{font-size:9.5px;font-weight:700;letter-spacing:.10em;text-transform:uppercase;color:var(--text-3);margin-bottom:8px;display:flex;align-items:center;gap:6px;}
.dept-block-count{background:var(--surface-2);border:1px solid var(--border);font-size:10px;padding:1px 6px;border-radius:10px;color:var(--text-2);font-weight:600;}
.dept-res-stats{display:grid;grid-template-columns:repeat(4, 1fr);gap:6px;}
.dept-res-stat{display:flex;flex-direction:column;align-items:center;gap:2px;padding:6px 4px;border-radius:8px;background:var(--surface-2);}
.dept-res-stat--total{background:rgba(45,122,255,.06);}
.dept-res-num{font-size:18px;font-weight:700;color:var(--text-1);line-height:1;}
.dept-res-label{font-size:9px;font-weight:600;letter-spacing:.04em;text-transform:uppercase;color:var(--text-3);}
.dept-res-label--int{color:var(--cat-internal);}
.dept-res-label--rot{color:var(--cat-rotating);}
.dept-res-label--ext{color:var(--cat-external);}
.dept-units-block{padding:10px 14px;flex:1;}
.dept-units-list{display:flex;flex-direction:column;gap:4px;}
.dept-unit-row{display:flex;align-items:center;padding:4px 8px;border-radius:6px;background:var(--surface-2);border:1px solid var(--border);font-size:11.5px;}
.dept-unit-name{flex:1;min-width:0;color:var(--text-1);font-weight:500;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.dept-unit-occ{font-size:10px;font-weight:700;padding:1px 6px;border-radius:10px;flex-shrink:0;font-family:var(--font-data);}
.dept-unit-occ--free{background:rgba(13,158,110,.1);color:var(--ok);}
.dept-unit-occ--warn{background:rgba(245,158,11,.1);color:var(--warn);}
.dept-unit-occ--full{background:rgba(239,68,68,.1);color:#ef4444;}
.dept-unit-more{font-size:11px;color:var(--text-3);padding:2px 8px;}
.dept-unit-empty{font-size:11px;color:var(--text-3);font-style:italic;padding:4px 8px;}
.dept-card-actions{display:flex;gap:5px;justify-content:flex-end;padding:8px 12px 10px;border-top:1px solid var(--border);}
.tuc-view-toggle{display:flex;gap:2px;background:var(--surface-2);border:1px solid var(--border);border-radius:8px;padding:3px;}
.tuc-view-btn{width:32px;height:28px;border-radius:6px;border:none;background:transparent;color:var(--text-3);cursor:pointer;font-size:12px;display:flex;align-items:center;justify-content:center;transition:var(--t);}
.tuc-view-btn.active{background:var(--blue);color:#fff;box-shadow:0 2px 6px rgba(45,122,255,.3);}
.tuc-view-btn:hover:not(.active){background:var(--border);color:var(--text-1);}
.tuc-horizon-row{display:flex;align-items:center;gap:4px;}
.tuc-horizon-label{font-size:11px;color:var(--text-3);font-weight:500;}
.tuc-horizon-btn{padding:4px 9px;border-radius:6px;border:1px solid var(--border);background:var(--surface-2);color:var(--text-2);font-size:11px;font-weight:600;cursor:pointer;transition:var(--t);}
.tuc-horizon-btn.active{background:var(--blue);color:#fff;border-color:var(--blue);}
.tuc-horizon-btn:hover:not(.active){border-color:var(--blue);color:var(--blue);}
.tuc-head{display:flex;align-items:flex-start;justify-content:space-between;gap:8px;margin-bottom:10px;}
.tuc-head-right{display:flex;align-items:center;gap:5px;flex-shrink:0;}
.tuc-name-row{display:flex;align-items:flex-start;gap:8px;}
.tuc-sub{font-size:11px;color:var(--text-3);margin-top:2px;}
.tuc-cap-pill{font-size:12px;font-weight:700;padding:2px 8px;border-radius:20px;font-family:var(--font-data);background:rgba(13,158,110,.1);color:var(--ok);border:1px solid rgba(13,158,110,.2);}
.tuc-cap-pill--warn{background:rgba(245,158,11,.1);color:var(--warn);border-color:rgba(245,158,11,.2);}
.tuc-cap-pill--full{background:rgba(239,68,68,.1);color:#ef4444;border-color:rgba(239,68,68,.2);}
.tuc-cap-pill--free{background:var(--ok-lt);color:var(--ok);border-color:var(--ok-mid);}
.tuc-timeline-body{margin-bottom:8px;padding:8px 12px 0;}
.tuc-tl-header{display:flex;align-items:center;margin-bottom:4px;}
.tuc-tl-slot-label{width:32px;flex-shrink:0;}
.tuc-tl-months{flex:1;display:flex;gap:2px;}
.tuc-tl-month-label{flex:1;text-align:center;font-size:9.5px;font-weight:700;color:var(--text-3);text-transform:uppercase;letter-spacing:.04em;padding:0 2px;}
.tuc-tl-month-label--current{color:var(--blue);font-weight:800;}
.tuc-tl-row{display:flex;align-items:center;gap:0;margin-bottom:3px;}
.tuc-tl-avatar{width:26px;height:26px;border-radius:50%;background:linear-gradient(135deg, var(--blue), #6366f1);color:#fff;font-size:9px;font-weight:700;display:flex;align-items:center;justify-content:center;flex-shrink:0;cursor:default;box-shadow:0 1px 4px rgba(45,122,255,.3);}
.tuc-tl-slot-num{width:26px;height:26px;border-radius:50%;background:var(--surface-2);border:1px solid var(--border);color:var(--text-3);font-size:10px;font-weight:600;display:flex;align-items:center;justify-content:center;flex-shrink:0;}
.tuc-tl-cell{flex:1;height:26px;border-radius:4px;margin:0 1px;display:flex;align-items:center;justify-content:center;font-size:9px;font-weight:700;transition:transform .1s;cursor:default;position:relative;}
.tuc-tl-cell:hover{transform:scaleY(1.08);z-index:1;}
.tuc-tl-cell--free{background:rgba(13,158,110,.1);border:1px dashed rgba(13,158,110,.3);color:var(--ok);}
.tuc-tl-cell--free.tuc-tl-cell--current{background:rgba(13,158,110,.18);border-style:solid;box-shadow:0 0 0 1px rgba(13,158,110,.3);}
.tuc-tl-cell--occupied{background:linear-gradient(135deg, rgba(45,122,255,.18), rgba(99,102,241,.14));border:1px solid rgba(45,122,255,.25);color:var(--blue);}
.tuc-tl-cell--partial{background:linear-gradient(135deg,
    rgba(13,158,110,.12) 0%, rgba(13,158,110,.12) 40%,
    rgba(45,122,255,.14) 60%, rgba(45,122,255,.14) 100%);border:1px solid rgba(245,158,11,.3);color:var(--warn);}
.tuc-tl-cell--current{outline:2px solid rgba(45,122,255,.3);outline-offset:1px;}
.tuc-tl-cell-name{font-size:8px;font-weight:800;letter-spacing:.03em;opacity:.8;}
.tuc-tl-cell-free{font-size:10px;}
.tuc-tl-legend{display:flex;gap:12px;margin-top:6px;}
.tuc-tl-leg-item{display:flex;align-items:center;gap:4px;font-size:10px;color:var(--text-3);}
.tuc-tl-leg-dot{width:10px;height:10px;border-radius:3px;}
.tuc-tl-leg-dot--occupied{background:rgba(45,122,255,.25);border:1px solid rgba(45,122,255,.4);}
.tuc-tl-leg-dot--partial{background:rgba(245,158,11,.25);border:1px solid rgba(245,158,11,.4);}
.tuc-tl-leg-dot--free{background:rgba(13,158,110,.15);border:1px dashed rgba(13,158,110,.4);}
.tuc-free-soon{margin-left:auto;flex-shrink:0;font-size:10px;font-weight:700;padding:1px 7px;border-radius:10px;background:rgba(245,158,11,.1);color:var(--warn);border:1px solid rgba(245,158,11,.25);}
.tuc--timeline-mode{}
.tuc-slots{display:flex;flex-direction:column;gap:3px;margin:6px 0 6px;}
.tuc-slot{display:flex;align-items:center;gap:6px;padding:4px 8px;border-radius:6px;font-size:11px;}
.tuc-slot--occupied{background:rgba(45,122,255,.06);border:1px solid rgba(45,122,255,.15);}
.tuc-slot--free{background:rgba(13,158,110,.05);border:1px dashed rgba(13,158,110,.25);}
.tuc-slot-dot{width:7px;height:7px;border-radius:50%;flex-shrink:0;}
.tuc-slot-dot--active{background:var(--blue);box-shadow:0 0 5px rgba(45,122,255,.5);}
.tuc-slot-dot--free{background:var(--ok);opacity:.6;}
.tuc-slot-name{font-weight:600;color:var(--text-1);flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.tuc-slot-available{color:var(--ok);font-weight:500;font-style:italic;}
.tuc-slot-dates{font-size:10px;font-family:var(--font-data);font-weight:500;color:var(--text-3);flex-shrink:0;white-space:nowrap;}
.external-contact-block{display:flex;flex-direction:column;gap:10px;}
.form-hint{font-size:10px;color:var(--text-3);font-weight:400;margin-left:4px;}
.pd-link{color:var(--blue);text-decoration:none;}
.pd-link:hover{text-decoration:underline;}
*{box-sizing:border-box;margin:0;padding:0;}
*::before{box-sizing:border-box;margin:0;padding:0;}
*::after{box-sizing:border-box;margin:0;padding:0;}
[v-cloak]{display:none !important;}
html{height:100%;overflow:hidden;}
body{font-family:var(--font-ui);font-size:15px;background:var(--canvas);background-image:radial-gradient(circle, rgba(10,22,40,.07) 1px, transparent 1px);background-size:24px 24px;color:var(--text-1);line-height:1.55;height:100%;overflow:hidden;-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale;}
button{font-family:inherit;cursor:pointer;border:none;background:none;}
input{font-family:inherit;}
select{font-family:inherit;}
textarea{font-family:inherit;}
a{color:var(--blue);text-decoration:none;}
.app-layout{display:flex;min-height:100vh;height:100vh;overflow:hidden;--navbar-h:56px;}
