.filter-bar input[type="text"]:focus{border-color:var(--blue);box-shadow:0 0 0 3px var(--blue-dim);}
.filter-bar input[type="search"]:focus{border-color:var(--blue);box-shadow:0 0 0 3px var(--blue-dim);}
.filter-bar input[type="date"]{min-width:145px;flex:0 0 auto;font-size:var(--t-12);min-height:40px;}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:6px;padding:9px 18px;border:none;border-radius:var(--r);font-family:var(--font-ui);font-size:var(--t-12);font-weight:600;cursor:pointer;transition:var(--t);white-space:nowrap;line-height:1;}
.btn:disabled{opacity:.45;cursor:not-allowed;pointer-events:none;}
.btn i{font-size:var(--t-11);}
.btn-primary{background:var(--blue);color:#fff;box-shadow:0 1px 4px rgba(45,122,255,.3);}
.btn-primary:hover{background:#1a66f0;box-shadow:var(--shadow-blue);transform:translateY(-1px);}
.btn-secondary{background:var(--surface-2);color:var(--text-2);border:1px solid var(--border);}
.btn-secondary:hover{background:var(--surface-3);color:var(--text-1);}
.btn-outline{background:transparent;color:var(--blue);border:1px solid var(--blue-mid);}
.btn-outline:hover{background:var(--blue-lt);border-color:var(--blue);}
.btn-outline-primary{background:transparent;color:var(--blue);border:1px solid var(--blue-mid);}
.btn-outline-primary:hover{background:var(--blue-lt);border-color:var(--blue);}
.btn-ghost{background:transparent;color:var(--text-2);border:1px solid transparent;}
.btn-ghost:hover{background:var(--surface-2);}
.btn-danger{background:var(--danger);color:#fff;box-shadow:0 1px 4px rgba(220,53,69,.25);}
.btn-danger:hover{background:#c82333;transform:translateY(-1px);}
.btn-warning{background:var(--warn);color:#fff;}
.btn-warning:hover{background:#b45309;transform:translateY(-1px);}
.btn-success{background:var(--ok);color:#fff;}
.btn-success:hover{background:#047857;transform:translateY(-1px);}
.btn-icon{width:28px;height:28px;padding:0;border-radius:6px;border:1px solid var(--border);background:var(--surface-2);color:var(--text-3);cursor:pointer;display:inline-flex;align-items:center;justify-content:center;font-size:11px;transition:all .15s;flex-shrink:0;}
.btn-icon:hover{background:var(--blue-lt);color:var(--blue);border-color:var(--blue-mid);}
.btn-icon--ok:hover{background:rgba(13,158,110,.1);color:#0d9e6e;border-color:rgba(13,158,110,.3);}
.btn-icon--danger:hover{background:rgba(239,68,68,.1);color:#ef4444;border-color:rgba(239,68,68,.3);}
.btn-sm{padding:6px 12px;font-size:var(--t-11);}
.btn-lg{padding:11px 24px;font-size:var(--t-13);}
.w-100{width:100%;}
.btn-pill{display:inline-flex;align-items:center;gap:5px;padding:5px 13px;border-radius:20px;font-size:var(--t-11);font-weight:600;letter-spacing:.01em;cursor:pointer;transition:var(--t);white-space:nowrap;border:1px solid transparent;font-family:var(--font-ui);min-height:32px;}
.btn-pill-edit{background:var(--surface-2);border-color:var(--border);color:var(--text-2);}
.btn-pill-edit:hover{background:var(--blue-lt);border-color:var(--blue-mid);color:var(--blue);transform:translateY(-1px);}
.btn-pill-view{background:var(--surface-2);border-color:var(--border);color:var(--text-2);}
.btn-pill-view:hover{background:var(--teal-lt);border-color:var(--teal);color:var(--teal);transform:translateY(-1px);}
.btn-pill-danger{background:var(--surface-2);border-color:var(--border);color:var(--text-3);}
.btn-pill-danger:hover{background:var(--danger-lt);border-color:rgba(220,53,69,.3);color:var(--danger);transform:translateY(-1px);}
.btn-pill-primary{background:var(--blue-lt);border-color:var(--blue-mid);color:var(--blue);}
.btn-pill-primary:hover{background:var(--blue);color:#fff;transform:translateY(-1px);}
.btn-pill-success{background:var(--ok-lt);border-color:var(--ok-mid);color:var(--ok);}
.btn-pill-success:hover{background:var(--ok);color:#fff;transform:translateY(-1px);}
.card{background:var(--surface);border:1px solid var(--border);border-radius:var(--r-xl);padding:22px;box-shadow:var(--shadow-sm);}
.card-header{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;padding-bottom:13px;border-bottom:1px solid var(--border);flex-wrap:wrap;gap:10px;}
.card-title{display:flex;align-items:center;gap:8px;font-size:var(--t-13);font-weight:700;color:var(--text-1);letter-spacing:-.015em;}
.card-title i{color:var(--blue);font-size:15px;}
.stats-grid{display:grid;grid-template-columns:repeat(auto-fit, minmax(240px, 1fr));gap:14px;margin-bottom:20px;}
@media (min-width: 1100px){.stats-grid:not(.mini){grid-template-columns:repeat(4, 1fr);}}
@keyframes statCardIn{
  from { opacity: 0; transform: translateY(16px) scale(.98); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}
.stat-card{background:var(--surface);border:1px solid var(--border);border-radius:16px;padding:22px 22px 18px;box-shadow:0 1px 3px rgba(10,22,40,.06), 0 4px 16px rgba(10,22,40,.04);position:relative;overflow:hidden;transition:transform var(--t-md), box-shadow var(--t-md);animation:statCardIn .55s cubic-bezier(.22,1,.36,1) both;cursor:pointer;}
.stat-card::before{content:"";position:absolute;top:0;left:0;right:0;height:3px;border-radius:16px 16px 0 0;}
.stat-card:nth-child(1)::before{background:linear-gradient(90deg, #4d9aff, #818cf8);}
.stat-card:nth-child(2)::before{background:linear-gradient(90deg, #34d399, #059669);}
.stat-card:nth-child(3)::before{background:linear-gradient(90deg, #22d3ee, #0891b2);}
.stat-card:nth-child(4)::before{background:linear-gradient(90deg, #fbbf24, #f97316);}
.stat-card::after{content:"";position:absolute;top:-20px;right:-20px;width:100px;height:100px;border-radius:50%;pointer-events:none;opacity:.4;}
.stat-card:nth-child(1)::after{background:radial-gradient(circle, rgba(77,154,255,.12) 0%, transparent 70%);}
.stat-card:nth-child(2)::after{background:radial-gradient(circle, rgba(52,211,153,.10) 0%, transparent 70%);}
.stat-card:nth-child(3)::after{background:radial-gradient(circle, rgba(34,211,238,.10) 0%, transparent 70%);}
.stat-card:nth-child(4)::after{background:radial-gradient(circle, rgba(251,191,36,.10) 0%, transparent 70%);}
.stat-card:nth-child(1){animation-delay:.05s;}
.stat-card:nth-child(2){animation-delay:.10s;}
.stat-card:nth-child(3){animation-delay:.15s;}
.stat-card:nth-child(4){animation-delay:.20s;}
.stat-card:hover{transform:translateY(-3px);box-shadow:0 2px 6px rgba(10,22,40,.06), 0 12px 32px rgba(10,22,40,.09);}
.stat-header{display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:14px;gap:8px;}
.stat-header h3{font-family:var(--font-data);font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.13em;color:var(--text-3);margin-top:2px;}
.stat-header i{width:36px;height:36px;border-radius:10px;display:flex;align-items:center;justify-content:center;font-size:14px;flex-shrink:0;}
.stat-card:nth-child(1) .stat-header i{background:rgba(77,154,255,.1);color:#4d9aff;}
.stat-card:nth-child(2) .stat-header i{background:rgba(52,211,153,.1);color:#34d399;}
.stat-card:nth-child(3) .stat-header i{background:rgba(34,211,238,.1);color:#22d3ee;}
.stat-card:nth-child(4) .stat-header i{background:rgba(251,191,36,.1);color:#fbbf24;}
.stat-main-value{font-family:var(--font-display);font-size:clamp(44px, 4.2vw, 64px);font-weight:400;font-style:italic;color:var(--text-1);line-height:.9;margin-bottom:16px;letter-spacing:-.03em;display:flex;align-items:baseline;gap:6px;}
.stat-breakdown{display:flex;flex-direction:column;border-top:1px solid var(--border);padding-top:12px;gap:0;}
.breakdown-item{display:flex;align-items:center;justify-content:space-between;padding:5px 0;font-size:12px;gap:6px;border-bottom:1px dashed rgba(10,22,40,.06);}
.breakdown-item:last-child{border-bottom:none;padding-bottom:0;}
.breakdown-item .label{color:var(--text-2);font-weight:400;min-width:0;}
.breakdown-item .value{font-family:var(--font-data);font-weight:600;font-size:12px;color:var(--text-1);flex-shrink:0;}
.stats-grid.mini{grid-template-columns:repeat(auto-fit, minmax(130px, 1fr)) !important;gap:10px;}
.stat-card.mini{padding:14px;text-align:center;}
.stat-card.mini .stat-value{font-family:var(--font-display);font-size:30px;font-weight:400;line-height:1;margin:8px 0 4px;}
.stat-card.mini .stat-label{font-family:var(--font-data);font-size:var(--t-10);color:var(--text-3);text-transform:uppercase;letter-spacing:.5px;}
.stat-value.large{font-family:var(--font-display);font-size:36px;font-weight:400;line-height:1;margin:8px 0 4px;text-align:center;}
.charts-grid{display:grid;grid-template-columns:repeat(auto-fit, minmax(360px, 1fr));gap:18px;margin:18px 0;}
@media (min-width: 1100px){.charts-grid{grid-template-columns:repeat(2, 1fr);}}
@keyframes shimmer{
  0%   { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}
@keyframes fadeIn{ from { opacity: 0; } to { opacity: 1; } }
@keyframes slideUp{
  from { opacity: 0; transform: translateY(16px) scale(.98); }
  to   { opacity: 1; transform: none; }
}
@keyframes toastIn{
  from { opacity: 0; transform: translateX(20px) scale(.96); }
  to   { opacity: 1; transform: none; }
}
@keyframes lc-pulse{
  0%, 100% { transform: scale(1) translate(0, 0); opacity: .8; }
  50%       { transform: scale(1.12) translate(20px, -20px); opacity: 1; }
}
@keyframes lc-rise{
  from { opacity: 0; transform: translateY(24px) scale(.98); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}
@keyframes pulse-active{
  0%, 100% { opacity: 1; transform: scale(1); }
  50%       { opacity: .6; transform: scale(1.3); }
}
@keyframes pulse-oncall{
  0%, 100% { opacity: 1; transform: scale(1); }
  50%       { opacity: .5; transform: scale(1.3); }
}
@keyframes statusPulse{
  0%, 100% { transform: scale(1); opacity: 1; }
  50%       { transform: scale(1.2); opacity: .7; }
}
@keyframes rowFadeIn{
  from { opacity: 0; transform: translateX(-6px); }
  to   { opacity: 1; transform: none; }
}
@keyframes spin{ to { transform: rotate(360deg); } }
.chart-card{background:var(--surface);border:1px solid var(--border);border-radius:var(--r-lg);padding:18px;}
.chart-card h4{font-size:var(--t-13);font-weight:700;margin-bottom:16px;display:flex;align-items:center;gap:6px;color:var(--text-2);}
.chart-card h4 i{color:var(--blue);}
.chart-bars{display:flex;flex-direction:column;gap:11px;}
.chart-bar-item{display:flex;align-items:center;gap:11px;flex-wrap:wrap;}
.bar-label{width:110px;font-size:var(--t-12);font-weight:500;color:var(--text-2);flex-shrink:0;}
.bar-container{flex:1;height:22px;background:var(--surface-2);border-radius:12px;overflow:hidden;min-width:80px;}
.bar-fill{height:100%;border-radius:12px;transition:width .3s ease;}
.bar-value{width:38px;font-family:var(--font-data);font-size:var(--t-12);font-weight:600;color:var(--text-1);text-align:right;flex-shrink:0;}
.empty-chart{padding:24px;text-align:center;color:var(--text-3);font-style:italic;background:var(--surface-2);border-radius:var(--r);}
.mini-chart{padding:12px;}
.chart-row{display:flex;align-items:center;gap:8px;padding:6px 0;flex-wrap:wrap;}
.chart-label{width:80px;font-size:var(--t-11);flex-shrink:0;}
.chart-bar{flex:1;height:16px;background:var(--surface-2);border-radius:8px;overflow:hidden;min-width:60px;}
.chart-value{width:34px;font-family:var(--font-data);font-size:var(--t-11);font-weight:600;}
.tags-cloud{display:flex;flex-wrap:wrap;gap:8px 12px;padding:16px;justify-content:center;align-items:center;}
.tags-cloud .need-tag{background:var(--blue-lt);color:var(--blue);border:1px solid var(--blue-mid);padding:4px 12px;border-radius:20px;transition:var(--t);cursor:default;}
.tags-cloud .need-tag:hover{transform:scale(1.05);background:var(--blue);color:white;}
.tags-cloud.small .need-tag{font-size:var(--t-11) !important;padding:2px 8px;}
.needs-grid{display:flex;flex-direction:column;gap:10px;}
.need-item{display:flex;align-items:center;gap:12px;padding:7px 0;border-bottom:1px solid var(--border);flex-wrap:wrap;}
.need-item:last-child{border-bottom:none;}
.need-name{width:190px;font-size:var(--t-12);font-weight:500;flex-shrink:0;}
.need-count{width:36px;font-family:var(--font-data);font-weight:600;flex-shrink:0;}
.need-bar{flex:1;height:8px;background:var(--surface-2);border-radius:4px;overflow:hidden;min-width:80px;}
.need-fill{height:100%;background:linear-gradient(90deg, var(--blue), var(--teal));border-radius:4px;transition:width .3s ease;}
.category-grid{display:grid;grid-template-columns:repeat(auto-fill, minmax(230px, 1fr));gap:14px;}
.category-card{background:var(--surface-2);border:1px solid var(--border);border-radius:var(--r);padding:14px;}
.category-card h5{font-size:var(--t-12);font-weight:700;color:var(--blue);margin-bottom:10px;padding-bottom:6px;border-bottom:1px solid var(--border);}
.category-item{display:flex;justify-content:space-between;align-items:center;padding:4px 0;font-size:var(--t-11);}
.table-responsive{overflow-x:auto;border-radius:var(--r-lg);border:1px solid var(--border);box-shadow:var(--shadow-xs);-webkit-overflow-scrolling:touch;}
.table{width:100%;border-collapse:collapse;font-size:var(--t-12);border-spacing:0;min-width:560px;}
.table-staff{table-layout:auto !important;}
.table-oncall{table-layout:auto !important;}
.table-absence{table-layout:auto !important;}
.table-rotation{table-layout:auto !important;}
.table-callouts{table-layout:auto !important;}
.table-oncall-stats{table-layout:auto !important;}
.scc-grid{display:grid;grid-template-columns:repeat(auto-fill, minmax(260px, 1fr));gap:6px;padding:10px 0 8px;}
.scc{display:flex;align-items:flex-start;gap:10px;padding:10px 10px 10px 12px;background:var(--surface);border:1px solid var(--border);border-radius:6px;cursor:pointer;transition:box-shadow var(--t), border-color var(--t);position:relative;overflow:hidden;min-height:68px;}
.scc::before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;border-radius:3px 0 0 3px;background:var(--blue);opacity:0;transition:opacity var(--t);}
.scc:hover{box-shadow:0 2px 12px rgba(45,122,255,.10);border-color:var(--blue-mid);}
.scc:hover::before{opacity:1;}
.scc--inactive{opacity:.5;}
.scc--leave::before{background:var(--warn);opacity:1;}
.scc-avatar{width:28px;height:28px;border-radius:50%;flex-shrink:0;display:flex;align-items:center;justify-content:center;color:#fff;position:relative;background:linear-gradient(135deg, #334155, #475569);margin-top:2px;}
.scc-initials{font-size:10px;font-weight:700;letter-spacing:.02em;line-height:1;user-select:none;text-transform:uppercase;}
.scc-avatar--attending_physician{background:linear-gradient(135deg, #0d9e6e, #065f46);}
.scc-avatar--medical_resident{background:linear-gradient(135deg, #2d7aff, #1d4ed8);}
.scc-avatar--fellow{background:linear-gradient(135deg, #0891b2, #0e7490);}
.scc-avatar--nurse_practitioner{background:linear-gradient(135deg, #d97706, #92400e);}
.scc-dot{position:absolute;bottom:-1px;right:-1px;width:8px;height:8px;border-radius:50%;border:2px solid var(--surface);}
.scc-dot--active{background:var(--ok);}
.scc-dot--on_leave{background:var(--warn);}
.scc-dot--inactive{background:#94a3b8;}
.scc-body{flex:1;min-width:0;display:flex;flex-direction:column;gap:2px;}
.scc-name-row{display:flex;align-items:flex-start;gap:4px;}
.scc-name{font-size:13px;font-weight:600;color:var(--text-1);line-height:1.3;letter-spacing:-.01em;flex:1;min-width:0;word-break:break-word;}
.scc-warn{color:var(--warn);font-size:9.5px;flex-shrink:0;cursor:help;opacity:.55;transition:opacity var(--t);margin-top:2px;}
.scc:hover .scc-warn{opacity:.9;}
.scc-meta-row{display:flex;align-items:center;gap:4px;flex-wrap:nowrap;overflow:hidden;}
.scc-type-badge{font-size:9px !important;padding:1px 6px !important;flex-shrink:0;}
.scc-cat-pill{font-size:8px;font-weight:700;letter-spacing:.04em;padding:1px 4px;border-radius:3px;text-transform:uppercase;flex-shrink:0;}
.scc-cat--ext{background:rgba(251,191,36,.15);color:var(--warn);}
.scc-cat--int{background:rgba(13,158,110,.12);color:var(--ok);}
.scc-dept-text{font-size:11px;color:var(--text-3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.scc-rotation-row{display:flex;align-items:center;margin-top:2px;}
.scc-meta{display:flex;align-items:center;gap:4px;}
.scc-dept-row{display:flex;align-items:center;min-height:14px;}
.scc-no-rotation{display:none;}
.scc-actions{display:flex;flex-direction:column;gap:3px;align-self:center;flex-shrink:0;opacity:0;transform:translateX(4px);transition:opacity var(--t), transform var(--t);pointer-events:none;}
.scc:hover .scc-actions{opacity:1;transform:translateX(0);pointer-events:auto;}
.scc-actions .rot-action-btn{width:26px;height:26px;font-size:10px;background:var(--surface-2);border-color:var(--border);color:var(--text-3);}
.scc-actions .rot-action-btn:hover{background:var(--blue-lt);border-color:var(--blue-mid);color:var(--blue);}
.scc-actions .rot-action-btn--danger:hover{background:rgba(239,68,68,.08);border-color:rgba(239,68,68,.25);color:#ef4444;}
.btn-pill--clear{background:rgba(239,68,68,.08) !important;color:#ef4444 !important;border-color:rgba(239,68,68,.2) !important;}
.btn-pill--clear:hover{background:rgba(239,68,68,.15) !important;}
.table thead th{background:var(--surface-2);padding:9px 14px;text-align:left;font-family:var(--font-data);font-size:var(--t-10);font-weight:700;text-transform:uppercase;letter-spacing:.10em;color:var(--text-3);border-bottom:2px solid var(--border);white-space:nowrap;position:sticky;top:0;z-index:1;cursor:pointer;user-select:none;}
.table thead th i{margin-left:4px;font-size:var(--t-10);color:var(--text-3);}
.table tbody tr:last-child{border-bottom:none;}
.table tbody tr:hover{background:var(--blue-lt);}
.table tbody tr:hover td:first-child{border-left-color:var(--blue) !important;}
.table-striped tbody tr:nth-child(even){background:rgba(244,246,250,.7);}
.table-striped tbody tr:nth-child(even):hover{background:var(--blue-lt);}
.table tbody td{padding:8px 14px;color:var(--text-1);vertical-align:middle;line-height:1.35;}
.table tbody td .font-medium{font-size:var(--t-12);font-weight:600;color:var(--text-1);letter-spacing:-.01em;display:block;}
.table .text-xs.text-gray-500{font-size:var(--t-11);color:var(--text-3);display:block;margin-top:2px;}
.table .text-xs.text-blue-600{font-family:var(--font-data);font-size:var(--t-10);font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:var(--blue);background:var(--blue-lt);border:1px solid var(--blue-mid);padding:1px 7px;border-radius:var(--r-xs);display:inline-block;margin-top:3px;}
.font-mono{font-family:var(--font-data);}
.resident-badge{display:inline-flex;align-items:center;gap:4px;padding:3px 9px;border-radius:12px;font-family:var(--font-data);font-size:var(--t-10);font-weight:600;margin-top:4px;white-space:nowrap;max-width:100%;}
.resident-badge i{font-size:var(--t-10);margin-right:2px;}
.resident-department_internal{background:var(--blue-lt);color:var(--blue);border:1px solid var(--blue-mid);}
.resident-rotating_other_dept{background:var(--ok-lt);color:#065f46;border:1px solid var(--ok-mid);}
.resident-external_resident{background:var(--purple-lt);color:#5b21b6;border:1px solid #d8b4fe;}
.resident-institution{font-size:var(--t-10);opacity:0.8;margin-left:2px;}
.table tbody tr.row-active{border-left:3px solid var(--ok);}
.table tbody tr.row-on_leave{border-left:3px solid var(--warn);}
.table tbody tr.row-scheduled{border-left:3px solid var(--info);}
.table tbody tr.row-completed{border-left:3px solid var(--teal);}
.table tbody tr.row-cancelled{border-left:3px solid var(--neutral);}
.table tbody tr.row-currently_absent{border-left:3px solid var(--warn);background:rgba(251,191,36,.04);}
.table tbody tr.row-planned_leave{border-left:3px solid var(--p-accent);background:rgba(77,154,255,.03);}
.table tbody tr.row-returned{border-left:3px solid rgba(52,211,153,.35);opacity:0.55;transition:opacity var(--t);}
.table tbody tr.row-expired{border-left:3px solid rgba(52,211,153,.35);opacity:0.55;transition:opacity var(--t);}
.table tbody tr.row-returned:hover{opacity:1;}
