.table tbody tr:nth-child(5){animation-delay:.15s;}
.table tbody tr:nth-child(6){animation-delay:.18s;}
.table tbody tr:nth-child(7){animation-delay:.21s;}
.table tbody tr:nth-child(8){animation-delay:.24s;}
