.reason-grid{grid-template-columns:1fr 1fr;}
.metrics-grid{grid-template-columns:1fr 1fr;}
.availability-grid{grid-template-columns:1fr 1fr;}
.action-buttons{grid-template-columns:1fr;}
.stats-grid{grid-template-columns:1fr;}
.trial-stats-grid{grid-template-columns:1fr 1fr;}
.supervision-stats{grid-template-columns:1fr;}
.resident-details{grid-template-columns:1fr;}
.profile-tabs{flex-direction:column;}
.profile-tab{width:100%;}
.table-actions{flex-wrap:nowrap;}
.filter-bar{flex-direction:column;}
.filter-bar .form-control{min-width:unset;max-width:100%;flex:none;width:100%;}
.filter-bar .form-select{min-width:unset;max-width:100%;flex:none;width:100%;}
.stats-toggle-btn{bottom:0;border-radius:var(--r) var(--r) 0 0;width:auto;padding:10px 20px;}
.live-stats-sidebar{width:100%;height:75vh;top:auto;bottom:0;transform:translateY(100%);border-radius:var(--r-xl) var(--r-xl) 0 0;box-shadow:0 -12px 60px rgba(0,0,0,.55);}
.live-stats-sidebar.open{transform:translateY(0);}
.rotation-week-grid{grid-template-columns:120px repeat(7, 1fr);font-size:10px;}
.rotation-dot{width:30px;height:30px;font-size:11px;}
.view-toggle .btn-pill{padding:4px 8px;font-size:11px;}}
::-webkit-scrollbar{width:5px;height:5px;}
::-webkit-scrollbar-track{background:transparent;}
::-webkit-scrollbar-thumb{background:var(--border-2);border-radius:3px;}
::-webkit-scrollbar-thumb:hover{background:var(--border-3);}
@media print{.sidebar{display:none !important;}
.top-navbar{display:none !important;}
.stats-toggle-btn{display:none !important;}
.live-stats-sidebar{display:none !important;}
.toast-container{display:none !important;}
.modal-overlay{display:none !important;}
.quick-actions-bar{display:none !important;}
.filter-bar{display:none !important;}
.btn{display:none !important;}
.tbl-btn{display:none !important;}
.pagination-controls{display:none !important;}
.btn-pill{display:none !important;}
.header-actions button:not(.print-keep){display:none !important;}
.main-content{margin-left:0 !important;height:auto;overflow:visible;}
.content-area{padding:0;overflow:visible;height:auto !important;max-height:none !important;}
.app-layout{display:block !important;}
body{background:#fff;background-image:none;color:#000;font-size:11px;}
.card{box-shadow:none;border:1px solid #ddd;page-break-inside:avoid;}
.stat-card{box-shadow:none;border:1px solid #ddd;page-break-inside:avoid;}
.table thead th{background:#f5f5f5 !important;color:#333 !important;print-color-adjust:exact;}
.table tbody tr{border-bottom:1px solid #eee;animation:none;}
.badge{border:1px solid #ccc;background:#f5f5f5 !important;color:#333 !important;}
.status-indicator{border:1px solid #ccc;background:#f5f5f5 !important;color:#333 !important;}
.rot-row{page-break-inside:avoid;}
.tbl-row{page-break-inside:avoid;}
.content-area::before{content:"Servicio de Neumología · CHUAC · A Coruña";display:block;font-size:10px;color:#666;border-bottom:1px solid #ddd;padding-bottom:6px;margin-bottom:12px;}}
.drawer-backdrop-enter-active{transition:opacity 280ms cubic-bezier(.4,0,.2,1);}
.drawer-backdrop-leave-active{transition:opacity 280ms cubic-bezier(.4,0,.2,1);}
.drawer-backdrop-enter-from{opacity:0;}
.drawer-backdrop-leave-to{opacity:0;}
.profile-drawer-backdrop{position:fixed;inset:0;background:rgba(7,17,31,.55);backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);z-index:var(--z-panel);}
.profile-drawer{position:fixed;top:0;right:0;bottom:0;width:min(820px, 100vw);display:flex;background:var(--surface-1, #fff);z-index:var(--z-modal);box-shadow:-8px 0 48px rgba(0,0,0,.22), -2px 0 8px rgba(0,0,0,.12);overflow:hidden;}
.pd-identity{width:236px;flex-shrink:0;background:#0f2d54;display:flex;flex-direction:column;overflow:hidden;border-right:0.5px solid rgba(255,255,255,.06);}
.pd-status-bar{height:2px;flex-shrink:0;background:linear-gradient(90deg, var(--teal-2,#00B3B3) 0%, rgba(0,179,179,0) 100%);}
.pd-hero{padding:22px 18px 14px;display:flex;flex-direction:column;align-items:center;gap:8px;border-bottom:0.5px solid rgba(255,255,255,.05);position:relative;flex-shrink:0;}
.pd-close{position:absolute;top:12px;right:12px;width:26px;height:26px;border-radius:50%;background:rgba(255,255,255,.06);border:0.5px solid rgba(255,255,255,.1);color:rgba(255,255,255,0.65);cursor:pointer;display:flex;align-items:center;justify-content:center;transition:all .18s;}
.pd-close:hover{background:rgba(255,255,255,.12);color:#fff;}
.pd-close svg{width:11px;height:11px;}
.pd-avatar-block{position:relative;flex-shrink:0;}
.pd-avatar{width:66px;height:66px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:1.25rem;font-weight:700;color:#fff;letter-spacing:-.02em;background:linear-gradient(135deg, #00B3B3 0%, #0e7490 100%);box-shadow:0 0 0 2.5px rgba(0,179,179,.25), 0 0 0 5px rgba(0,179,179,.07);font-family:"DM Sans", sans-serif;}
.pd-avatar i{display:none;}
.pd-avatar::before{content:attr(data-initials);font-family:"DM Sans", sans-serif;font-size:1.25rem;font-weight:700;color:#fff;letter-spacing:-.02em;}
.pd-avatar--resident{background:linear-gradient(135deg, #1e40af 0%, #0e7490 100%);box-shadow:0 0 0 2.5px rgba(30,64,175,.25), 0 0 0 5px rgba(30,64,175,.07);}
.pd-status-dot{position:absolute;bottom:3px;right:3px;width:11px;height:11px;border-radius:50%;border:2px solid #0f2d54;}
.dot--active{background:#10b981;}
.dot--on_leave{background:#f59e0b;}
.dot--inactive{background:#6b7280;}
.pd-name{font-size:.9375rem;font-weight:700;color:#fff;line-height:1.2;text-align:center;letter-spacing:-.01em;}
.pd-role{font-size:.575rem;font-family:"DM Mono", monospace;letter-spacing:.12em;text-transform:uppercase;color:rgba(255,255,255,0.75);text-align:center;}
.pd-hero-meta{display:flex;align-items:center;justify-content:center;gap:5px;flex-wrap:wrap;}
.pd-hero-chip{display:inline-flex;align-items:center;gap:4px;padding:2.5px 8px;border-radius:99px;font-size:.575rem;font-family:"DM Mono", monospace;letter-spacing:.07em;text-transform:uppercase;background:rgba(0,179,179,.1);border:0.5px solid rgba(0,179,179,.2);color:#00B3B3;}
.pd-hero-chip i{display:none;}
.pd-hero-chip--neutral{background:rgba(255,255,255,.06);border-color:rgba(255,255,255,0.30);color:rgba(255,255,255,0.75);}
.pd-hero-chip--resident{background:rgba(99,102,241,.1);border-color:rgba(99,102,241,.22);color:#818cf8;}
.pd-stats-strip{display:grid;grid-template-columns:1fr 1fr;border-bottom:0.5px solid rgba(255,255,255,.05);flex-shrink:0;}
.pd-stat{padding:10px 10px;text-align:center;border-right:0.5px solid rgba(255,255,255,.05);}
.pd-stat:last-child{border-right:none;}
.pd-stat-n{font-size:1.125rem;font-weight:700;color:#fff;line-height:1;font-family:"DM Sans", sans-serif;}
.pd-stat-n--teal{color:#00B3B3;}
.pd-stat-l{font-size:.52rem;font-family:"DM Mono", monospace;letter-spacing:.08em;text-transform:uppercase;color:rgba(255,255,255,0.55);margin-top:2px;}
.pd-body{flex:1;overflow-y:auto;}
.pd-section{padding:12px 16px;border-bottom:0.5px solid rgba(255,255,255,.05);}
.pd-section:last-child{border-bottom:none;}
.pd-section-head{display:flex;align-items:center;gap:6px;cursor:default;background:none;border:none;width:100%;padding:0;margin-bottom:7px;}
.pd-section-icon{display:none;}
.pd-section-title{font-size:8.5px;font-family:"DM Mono", monospace;letter-spacing:.14em;text-transform:uppercase;color:rgba(255,255,255,0.42);flex:1;text-align:left;}
.pd-section-chevron{display:none;}
.pd-section-body{max-height:none !important;overflow:visible !important;}
.pd-section--collapsed .pd-section-body{max-height:none !important;}
.pd-row{display:flex;align-items:center;justify-content:space-between;padding:3px 0;}
.pd-row-key{display:flex;align-items:center;gap:6px;font-size:.675rem;color:rgba(255,255,255,0.55);}
.pd-row-key svg{flex-shrink:0;opacity:.7;}
.pd-row-val{font-size:.675rem;color:#fff;font-weight:500;text-align:right;}
.pd-row-na{color:rgba(255,255,255,0.55) !important;font-weight:400 !important;}
.pd-origin-block{background:rgba(255,255,255,.03);border:0.5px solid rgba(255,255,255,.07);border-radius:7px;padding:8px 10px;}
.pd-origin-name{font-size:.72rem;font-weight:600;color:rgba(255,255,255,0.92);display:flex;align-items:center;gap:5px;margin-bottom:3px;}
.pd-origin-contact{font-size:.6rem;font-family:"DM Mono", monospace;color:rgba(255,255,255,0.55);padding-left:16px;}
.pd-dates-block{display:flex;align-items:center;justify-content:space-between;}
.pd-date-kv{display:flex;flex-direction:column;gap:1px;}
.pd-date-k{font-size:.55rem;font-family:"DM Mono", monospace;letter-spacing:.08em;text-transform:uppercase;color:rgba(255,255,255,0.55);}
.pd-date-v{font-size:.72rem;color:rgba(255,255,255,0.97);font-weight:500;}
.pd-date-arrow{color:rgba(255,255,255,0.30);font-size:.75rem;}
.pd-contact-row{display:flex;align-items:center;gap:6px;padding:3px 0;font-size:.675rem;color:rgba(255,255,255,0.75);text-decoration:none;transition:color .15s;}
.pd-contact-row svg{flex-shrink:0;opacity:.6;}
.pd-contact-row:hover{color:#fff;}
.pd-contact-row--disabled{color:rgba(255,255,255,0.42) !important;pointer-events:none;}
.pd-capability-row{display:flex;align-items:center;gap:7px;padding:3px 0;font-size:.675rem;color:rgba(255,255,255,0.85);}
.pd-cap-icon{width:16px;height:16px;border-radius:4px;display:flex;align-items:center;justify-content:center;font-size:9px;flex-shrink:0;}
.pd-cap-icon--pi{background:rgba(245,158,11,.12);color:#f59e0b;}
.pd-cap-icon--coi{background:rgba(99,102,241,.12);color:#818cf8;}
.pd-cap-icon--sup{background:rgba(0,179,179,.12);color:#00B3B3;}
.pd-cap-label{font-size:.675rem;color:rgba(255,255,255,0.85);}
.pd-role-item{display:flex;align-items:center;gap:7px;padding:3px 0;font-size:.675rem;color:rgba(255,255,255,0.85);}
.pd-edit-btn{margin:10px 14px;padding:7px 12px;border-radius:8px;background:rgba(255,255,255,.04);border:0.5px solid rgba(255,255,255,.09);color:rgba(255,255,255,0.65);font-size:.72rem;display:flex;align-items:center;gap:6px;cursor:pointer;justify-content:center;transition:all .18s;flex-shrink:0;width:calc(100% - 28px);}
.pd-edit-btn:hover{background:rgba(255,255,255,.09);color:rgba(255,255,255,0.92);}
.pd-edit-btn i{display:none;}
.pd-edit-btn svg{flex-shrink:0;}
.pd-content{flex:1;display:flex;flex-direction:column;background:var(--surface-1, #fff);min-width:0;}
.pd-tabs{display:flex;align-items:center;gap:0;border-bottom:0.5px solid var(--border-color, rgba(0,0,0,.08));padding:0 18px;background:var(--surface-2, #f8f9fa);flex-shrink:0;}
.pd-tab{display:flex;align-items:center;gap:5px;padding:11px 12px;font-size:.8rem;font-weight:500;color:var(--text-3, #6b7280);border-bottom:2px solid transparent;cursor:pointer;white-space:nowrap;background:none;border-top:none;border-left:none;border-right:none;transition:all .15s;}
.pd-tab.active{color:#00B3B3;border-bottom-color:#00B3B3;}
.pd-tab i{display:none;}
.pd-tab svg{flex-shrink:0;}
.pd-tabs-spacer{flex:1;}
.pd-tab-actions{display:flex;align-items:center;gap:5px;}
.pd-tab-action-btn{display:flex;align-items:center;gap:5px;padding:5px 9px;font-size:.7rem;color:var(--text-2, #374151);border:0.5px solid var(--border-color, rgba(0,0,0,.1));border-radius:6px;background:transparent;cursor:pointer;white-space:nowrap;transition:all .15s;}
.pd-tab-action-btn:hover{border-color:#00B3B3;color:#00B3B3;}
.pd-tab-action-btn i{display:none;}
.pd-tab-body{flex:1;overflow-y:auto;padding:14px 18px;display:flex;flex-direction:column;gap:10px;}
.pd-card{border:0.5px solid var(--border-color, rgba(0,0,0,.08));border-radius:10px;overflow:hidden;}
.pd-card-head{display:flex;align-items:center;gap:8px;padding:9px 13px;background:var(--surface-2, #f8f9fa);border-bottom:0.5px solid var(--border-color, rgba(0,0,0,.06));}
.pd-card-icon{width:20px;height:20px;flex-shrink:0;display:flex;align-items:center;justify-content:center;}
.pd-card-icon i{display:none;}
.pd-card-icon svg{flex-shrink:0;}
.pd-card-title{font-size:.78rem;font-weight:600;color:var(--text-1, #111827);flex:1;}
.pd-badge{font-size:.58rem;font-family:"DM Mono", monospace;padding:2px 6px;border-radius:99px;background:var(--surface-3, #f3f4f6);color:var(--text-3, #6b7280);border:0.5px solid var(--border-color, rgba(0,0,0,.08));}
.pd-badge--ok{background:rgba(16,185,129,.08);color:#059669;border-color:rgba(16,185,129,.2);}
.pd-badge--danger{background:rgba(239,68,68,.08);color:#dc2626;border-color:rgba(239,68,68,.2);}
.pd-badge--warn{background:rgba(245,158,11,.08);color:#d97706;border-color:rgba(245,158,11,.2);}
.pd-badge--blue{background:rgba(59,130,246,.08);color:#2563eb;border-color:rgba(59,130,246,.2);}
.pd-badge--neutral{background:var(--surface-3,#f3f4f6);color:var(--text-3,#6b7280);border-color:var(--border-color,rgba(0,0,0,.08));}
.pd-badge--teal{background:rgba(0,179,179,.08);color:#00B3B3;border-color:rgba(0,179,179,.2);}
.pd-rotation-name{font-size:.9375rem;font-weight:700;color:var(--text-1,#111827);padding:11px 13px 7px;}
.pd-grid-4{display:grid;grid-template-columns:1fr 1fr;gap:8px;padding:0 13px 11px;}
.pd-kv{display:flex;flex-direction:column;gap:1px;}
.pd-kv-k{font-size:.58rem;font-family:"DM Mono", monospace;text-transform:uppercase;letter-spacing:.07em;color:var(--text-3,#6b7280);}
.pd-kv-v{font-size:.8rem;font-weight:500;color:var(--text-1,#111827);}
.pd-kv-v--accent{color:#00B3B3;}
.pd-clear-row{display:flex;align-items:center;gap:8px;padding:13px;font-size:.78rem;color:var(--text-3,#6b7280);border:0.5px solid var(--border-color,rgba(0,0,0,.08));border-radius:10px;background:var(--surface-2,#f8f9fa);}
.pd-clear-row svg{flex-shrink:0;}
.pd-clear-row i{display:none;}
.pd-schedule-grid{display:grid;grid-template-columns:1fr 1fr;gap:0;}
.pd-schedule-col{padding:10px 13px;border-right:0.5px solid var(--border-color,rgba(0,0,0,.06));}
.pd-schedule-col:last-child{border-right:none;}
.pd-schedule-label{font-size:.6rem;font-family:"DM Mono", monospace;letter-spacing:.08em;text-transform:uppercase;color:var(--text-3,#6b7280);margin-bottom:6px;display:flex;align-items:center;gap:4px;}
.pd-schedule-label i{display:none;}
.pd-shift-row{display:flex;align-items:center;gap:5px;padding:3px 0;flex-wrap:wrap;}
.pd-shift-date{font-size:.72rem;font-weight:500;color:var(--text-1,#111827);}
.pd-shift-time{font-size:.65rem;font-family:"DM Mono", monospace;color:var(--text-3,#6b7280);}
.pd-more{font-size:.65rem;color:var(--text-3,#6b7280);font-family:"DM Mono", monospace;padding:3px 0;}
.pd-nil{padding:10px 13px;font-size:.78rem;color:var(--text-3,#6b7280);display:flex;align-items:center;gap:6px;}
.pd-nil i{display:none;}
.pd-history-row{display:flex;align-items:center;gap:8px;padding:6px 13px;border-bottom:0.5px solid var(--border-color,rgba(0,0,0,.06));}
.pd-history-row:last-child{border-bottom:none;}
.pd-history-dot{width:6px;height:6px;border-radius:50%;background:#10b981;flex-shrink:0;}
.pd-history-body{flex:1;}
.pd-history-unit{font-size:.78rem;font-weight:500;color:var(--text-1,#111827);}
.pd-history-dates{font-size:.62rem;font-family:"DM Mono", monospace;color:var(--text-3,#6b7280);}
.pd-history-badge{font-size:.57rem;font-family:"DM Mono", monospace;padding:1.5px 6px;border-radius:99px;background:rgba(16,185,129,.08);color:#059669;border:0.5px solid rgba(16,185,129,.18);}
.pd-research-row{padding:8px 13px;border-bottom:0.5px solid var(--border-color,rgba(0,0,0,.06));}
.pd-research-row:last-child{border-bottom:none;}
.pd-research-title{font-size:.8rem;font-weight:600;color:var(--text-1,#111827);margin-bottom:2px;}
.pd-research-meta{font-size:.65rem;font-family:"DM Mono", monospace;color:var(--text-3,#6b7280);}
.resident-category-badge{display:inline-flex;align-items:center;gap:4px;padding:2px 7px;border-radius:99px;font-size:.62rem;font-family:"DM Mono", monospace;letter-spacing:.06em;text-transform:uppercase;background:rgba(99,102,241,.08);color:#6366f1;border:0.5px solid rgba(99,102,241,.2);}
.resident-category-badge i{display:none;}
.drawer-slide-enter-active{transition:transform .28s cubic-bezier(.4,0,.2,1);}
.drawer-slide-leave-active{transition:transform .28s cubic-bezier(.4,0,.2,1);}
.drawer-slide-enter-from{transform:translateX(100%);opacity:0;}
.drawer-slide-leave-to{transform:translateX(100%);opacity:0;}
@media (max-width: 768px){.profile-drawer{width:100vw;flex-direction:column;}
.pd-identity{width:100%;max-height:280px;flex-direction:row;flex-wrap:wrap;}
.pd-hero{flex-direction:row;align-items:center;gap:12px;text-align:left;flex:1;}
.pd-hero-meta{justify-content:flex-start;}
.pd-stats-strip{grid-template-columns:repeat(2,1fr);width:100%;}
.pd-body{display:none;}
.pd-schedule-grid{grid-template-columns:1fr;}
.pd-grid-4{grid-template-columns:1fr 1fr;}}
@keyframes orb-pulse{
  0%, 100% { opacity: 1; transform: scale(1); }
  50%       { opacity: .6; transform: scale(1.12); }
}
@keyframes orb-pulse-green{
  0%, 100% { opacity: 1; transform: scale(1); }
  50%       { opacity: .5; transform: scale(1.12); }
}
@keyframes pulse-blue{ 0%,100% { opacity:1; transform:scale(1); } 50% { opacity:.5; transform:scale(1.3); } }
.staff-avatar-chip.chip--active{background:linear-gradient(135deg, #0d9e6e, #065f46);}
.staff-avatar-chip.chip--on_leave{background:linear-gradient(135deg, #d97706, #92400e);}
.staff-avatar-chip.chip--inactive{background:linear-gradient(135deg, #64748b, #334155);}
.rot-legend{display:flex;align-items:center;gap:18px;flex-wrap:wrap;padding:10px 18px;border-bottom:1px solid var(--border);background:var(--surface-2);}
.rot-legend-item{display:flex;align-items:center;gap:5px;font-family:var(--font-data);font-size:10px;font-weight:600;text-transform:uppercase;letter-spacing:.06em;color:var(--text-3);}
.rot-legend-item--note{margin-left:auto;font-weight:400;text-transform:none;letter-spacing:0;font-size:11px;color:var(--text-4);}
.rot-legend-dot{width:14px;height:14px;border-radius:50%;}
.rot-legend-dot--active{background:var(--blue);box-shadow:0 0 6px var(--blue-glow);}
.rot-legend-dot--scheduled{background:transparent;border:2px solid var(--blue-mid);}
.rot-legend-dot--done{background:var(--ok-lt);border:1.5px solid var(--ok-mid);}
.rot-compact{display:flex;flex-direction:column;}
.rot-row{display:flex;align-items:center;gap:0;padding:8px 18px;border-bottom:1px solid var(--border);transition:background var(--t);min-height:44px;}
.rot-row:last-child{border-bottom:none;}
.rot-row:hover{background:rgba(45,122,255,.03);}
.rot-who{display:flex;align-items:center;gap:10px;width:200px;flex-shrink:0;min-width:0;}
.rot-who-info{min-width:0;}
.rot-track{flex:1;display:flex;align-items:center;gap:5px;padding:0 12px;flex-wrap:nowrap;overflow:hidden;min-width:0;}
.rot-connector{color:var(--text-4);font-size:18px;line-height:1;margin:0 2px;flex-shrink:0;user-select:none;}
.rot-orb{position:relative;display:inline-flex;align-items:center;justify-content:center;min-width:36px;height:24px;padding:0 8px;border-radius:12px;cursor:pointer;font-size:11px;transition:transform .16s ease, box-shadow .16s ease;flex-shrink:0;user-select:none;white-space:nowrap;}
.rot-orb:hover{transform:translateY(-2px);z-index:calc(var(--z-sticky) + 10);}
.rot-orb:active{transform:translateY(0) scale(.97);}
.rot-orb-label{font-family:var(--font-data);font-size:11px;font-weight:700;letter-spacing:.04em;white-space:nowrap;line-height:1;}
.rot-orb--done{background:var(--surface-2);border:1.5px solid var(--border-2);color:var(--text-3);}
.rot-orb--done:hover{background:var(--ok-lt);border-color:var(--ok-mid);color:#065f46;box-shadow:0 4px 12px rgba(13,158,110,.15);}
.rot-orb--scheduled{background:transparent;border:2px solid var(--blue-mid);color:var(--blue);}
.rot-orb--scheduled:hover{background:var(--blue-lt);box-shadow:0 4px 12px rgba(45,122,255,.15);}
.rot-orb--add{background:transparent;border:2px dashed var(--border-2);color:var(--text-4);width:32px;min-width:32px;padding:0;font-size:11px;}
.rot-orb--add:hover{border-color:var(--blue);color:var(--blue);background:var(--blue-lt);}
