.tuc{background:var(--surface);border:1px solid var(--border);border-radius:8px;display:flex;flex-direction:column;gap:0;overflow:hidden;transition:box-shadow var(--t), transform var(--t);border-left:3px solid var(--border);}
.tuc:hover{box-shadow:var(--shadow-md);transform:translateY(-1px);}
