.tuc-sup-badge{margin-left:auto;font-family:var(--font-data);font-size:9px;font-weight:800;text-transform:uppercase;letter-spacing:.1em;color:var(--blue);background:var(--blue-lt);border:1px solid var(--blue-mid);padding:2px 7px;border-radius:20px;}
.tuc-shared-legend{grid-column:1 / -1;display:flex;gap:14px;align-items:center;padding:2px 4px 10px;border-bottom:1px solid var(--border);margin-bottom:2px;}
