.tuc-btn{display:inline-flex;align-items:center;gap:4px;padding:3px 8px;border-radius:var(--r-sm);font-size:11px;font-weight:600;cursor:pointer;transition:var(--t);border:1px solid transparent;font-family:var(--font-ui);}
