.stat-breakdown{display:flex;gap:16px;margin-top:8px;}
.breakdown-item{display:flex;flex-direction:column;gap:2px;}
.breakdown-item .label{font-size:10px;text-transform:uppercase;letter-spacing:.06em;color:var(--text-3);font-weight:700;}
.breakdown-item .value{font-family:var(--font-data);font-size:16px;font-weight:700;color:var(--text-1);}
.inno-card{padding:0;}
.inno-card-bar{position:absolute;top:0;left:0;right:0;bottom:auto;width:auto;height:3px;background:var(--stage-color, #7a90b0);border-radius:var(--r-lg) var(--r-lg) 0 0;}
.inno-card:hover{box-shadow:0 8px 32px -4px color-mix(in srgb, var(--stage-color, #7a90b0) 20%, transparent),
              0 2px 8px rgba(0,0,0,.08);}
.inno-stage-node{width:26px;height:26px;font-size:9px;}
.inno-stage-node--current{width:30px;height:30px;box-shadow:0 0 0 4px color-mix(in srgb, var(--stage-color) 20%, transparent);}
.inno-stage-label{font-size:11px;padding:3px 10px;background:color-mix(in srgb, var(--stage-color) 12%, transparent);border:1px solid color-mix(in srgb, var(--stage-color) 30%, transparent);border-radius:20px;}
.inno-cat-badge{font-size:10px;letter-spacing:.06em;}
.inno-member-avatar{box-shadow:0 1px 3px rgba(0,0,0,.15);}
.inno-member-avatar--lead{box-shadow:0 0 0 2px var(--blue-mid), 0 1px 3px rgba(0,0,0,.15);}
.inno-need-chip{transition:all .15s ease;}
.rline-kw-chip{transition:all .15s ease;}
.inno-kw-chip{transition:all .15s ease;}
.inno-need-chip:hover{transform:translateY(-1px);box-shadow:0 2px 6px rgba(0,0,0,.1);}
.inno-funding--seeking{background:#fef9c3;color:#854d0e;border:1px solid #fde68a;}
.inno-funding--applied{background:#eff6ff;color:#1d4ed8;border:1px solid #bfdbfe;}
.inno-funding--funded{background:#f0fdf4;color:#166534;border:1px solid #bbf7d0;}
.pipeline-stage-tile{transition:all .2s ease;cursor:pointer;position:relative;}
.pipeline-stage-tile::after{content:attr(data-count);}
.pipeline-stage-tile:hover{background:var(--surface-2);}
.rsm-container{max-width:820px;width:94vw;max-height:85vh;display:flex;flex-direction:column;padding:0;overflow:hidden;}
.rsm-header{display:flex;align-items:flex-start;gap:14px;padding:20px 24px;border-bottom:1px solid var(--border);background:linear-gradient(135deg, rgba(220,53,69,.04) 0%, var(--surface) 100%);flex-shrink:0;}
.rsm-header-icon{width:40px;height:40px;border-radius:10px;flex-shrink:0;background:var(--danger-lt);border:1px solid rgba(220,53,69,.2);color:var(--danger);display:flex;align-items:center;justify-content:center;font-size:16px;margin-top:2px;}
.rsm-header-text{flex:1;min-width:0;}
.rsm-title{font-size:16px;font-weight:700;color:var(--text-1);margin:0 0 4px;}
.rsm-subtitle{font-size:13px;color:var(--text-2);margin:0;line-height:1.5;}
.rsm-body{flex:1;overflow-y:auto;padding:20px 24px;display:flex;flex-direction:column;gap:16px;}
.rsm-section{border:1px solid var(--border);border-radius:var(--r-md);overflow:hidden;}
.rsm-section-header{display:flex;align-items:center;gap:8px;padding:10px 14px;background:var(--surface-2);border-bottom:1px solid var(--border);font-size:12px;font-weight:700;color:var(--text-1);text-transform:uppercase;letter-spacing:.05em;}
.rsm-section-header i{color:var(--blue);font-size:12px;}
.rsm-count{margin-left:auto;background:var(--blue-lt);color:var(--blue);border:1px solid var(--blue-mid);border-radius:20px;padding:1px 8px;font-size:11px;font-weight:800;}
.rsm-table{display:flex;flex-direction:column;}
.rsm-row{display:grid;grid-template-columns:1.4fr .6fr .8fr .6fr 1.4fr;gap:10px;align-items:center;padding:10px 14px;border-bottom:1px solid var(--border);font-size:12.5px;}
.rsm-row:last-child{border-bottom:none;}
.rsm-row--head{background:var(--surface-2);font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:var(--text-3);padding:7px 14px;}
.rsm-cell-date{display:flex;align-items:center;gap:6px;color:var(--text-1);font-weight:500;font-family:var(--font-data);}
.rsm-cell-date i{color:var(--blue);font-size:10px;}
.rsm-cell-meta{color:var(--text-2);}
.rsm-cell-note{color:var(--text-3);font-style:italic;font-size:11px;display:flex;align-items:center;gap:4px;}
.rsm-role-badge{display:inline-block;padding:2px 8px;border-radius:20px;font-size:9px;font-weight:800;text-transform:uppercase;letter-spacing:.05em;}
.rsm-role--primary{background:var(--blue-lt);color:var(--blue);border:1px solid var(--blue-mid);}
.rsm-role--backup{background:#f0fdf4;color:#166534;border:1px solid #bbf7d0;}
.rsm-role--neutral{background:var(--surface-3);color:var(--text-2);border:1px solid var(--border);}
.rsm-select{width:100%;padding:6px 8px;font-size:12px;background:var(--surface);border:1px solid var(--border);border-radius:var(--r-sm);color:var(--text-1);cursor:pointer;outline:none;transition:border-color var(--t);}
.rsm-select:focus{border-color:var(--blue);box-shadow:0 0 0 3px rgba(77,154,255,.12);}
.rsm-notice{background:var(--surface-2);border:1px solid var(--border);border-radius:var(--r-md);padding:12px 16px;font-size:12px;color:var(--text-2);line-height:1.6;display:flex;align-items:flex-start;gap:8px;}
.rsm-notice i{color:var(--blue);margin-top:1px;flex-shrink:0;}
.rsm-footer{border-top:1px solid var(--border);padding:14px 24px;flex-shrink:0;}
.rot-orb--backup-oc{background:linear-gradient(135deg, #059669, #047857);border-color:rgba(5,150,105,.4);color:#fff;}
.rot-orb--backup-oc .rot-orb-label{color:#fff;}
@media (min-width: 1600px){:root{--sidebar-w:clamp(280px, 17vw, 340px);--content-pad-x:32px;--content-pad-y:28px;}
.sidebar-menu-link{font-size:14.5px;padding:10px 17px;min-height:43px;gap:13px;}
.sidebar-menu-link i{font-size:15px;width:19px;}
.sidebar-section-title{font-size:10.5px;padding:16px 17px 7px;}
.content-area > *{max-width:1680px;}
.stats-grid:not(.mini){grid-template-columns:repeat(5, 1fr);}
.stat-card{padding:22px 24px;}
.stat-value{font-size:clamp(28px, 2.4vw, 42px);}
.table tbody td{font-size:13.5px;}
.table thead th{font-size:12px;}
.research-lines-grid{grid-template-columns:repeat(3, 1fr);}
.innovation-projects-grid{grid-template-columns:repeat(3, 1fr);}
.training-units-grid{grid-template-columns:repeat(3, 1fr);}
.departments-grid{grid-template-columns:repeat(4, 1fr);}
.modal-wide{max-width:min(960px, calc(100vw - 48px));}
.modal-container:not(.modal-sm):not(.modal-wide):not(.rsm-container):not(.tdm-container){max-width:min(700px, calc(100vw - 48px));}}
@media (min-width: 1920px){:root{--sidebar-w:clamp(300px, 15.5vw, 360px);--content-pad-x:40px;--content-pad-y:32px;}
.sidebar-menu-link{font-size:15px;padding:11px 18px;min-height:45px;}
.sidebar-menu-link i{font-size:15.5px;width:20px;}
.sidebar-section-title{font-size:11px;letter-spacing:.16em;padding:17px 18px 8px;}
.sidebar-logo .logo-text-main{font-size:15px;}
.content-area > *{max-width:1920px;}
body{font-size:14px;}
.table tbody td{font-size:14px;}
.form-label{font-size:13px;}
.form-control{font-size:14px;height:42px;}
.form-select{font-size:14px;height:42px;}
.stats-grid:not(.mini){grid-template-columns:repeat(6, 1fr);}
.departments-grid{grid-template-columns:repeat(5, 1fr);}
.research-lines-grid{grid-template-columns:repeat(4, 1fr);}
.table tbody tr td{padding:14px 14px;}
.rot-compact .rot-row{flex-wrap:nowrap;}}
@media (min-width: 2560px){:root{--sidebar-w:380px;}
.sidebar-menu-link{font-size:16px;padding:12px 20px;min-height:48px;}
.sidebar-section-title{font-size:11.5px;}
.content-area > *{max-width:2400px;}}
@media (min-width: 1100px) and (max-width: 1280px){.rot-orbs{flex-wrap:wrap;gap:6px;}
.rot-orb{flex-shrink:0;}}
@keyframes fadeSlideDown{
  from { opacity: 0; transform: translateY(-6px); }
  to   { opacity: 1; transform: translateY(0); }
}
.rsm-reassign-target{padding:12px 0 4px;border-top:1px solid var(--border);margin-top:8px;}
.rsm-reassign-target .form-label{font-size:var(--t-12);color:var(--text-2);margin-bottom:6px;}
.rsm-note{font-size:var(--t-11);color:var(--text-3);font-style:italic;}
.rsm-cell-wide{font-size:var(--t-11);color:var(--text-3);}
:root{--chuac:#0a7cff;--sergas:#00a96e;--ext-hosp:#9b59b6;}
.hospital-network-dot{width:7px;height:7px;border-radius:50%;display:inline-block;flex-shrink:0;}
.hnd--chuac{width:7px;height:7px;border-radius:50%;display:inline-block;flex-shrink:0;background:var(--chuac);}
.hnd--sergas{width:7px;height:7px;border-radius:50%;display:inline-block;flex-shrink:0;background:var(--sergas);}
.hnd--external{width:7px;height:7px;border-radius:50%;display:inline-block;flex-shrink:0;background:var(--ext-hosp);}
.hospital-cell{display:flex;align-items:center;gap:5px;font-size:var(--t-12);color:var(--text-1);}
.hospital-name-text{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:120px;}
.pd-pill--hospital{background:color-mix(in srgb, var(--canvas) 85%, var(--blue));color:var(--text-2);border:1px solid var(--border);display:inline-flex;align-items:center;gap:5px;}
.hospital-network-strip{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:4px;}
.hns-option{display:flex;align-items:center;gap:6px;padding:6px 14px 6px 10px;border-radius:7px;border:1.5px solid var(--border);cursor:pointer;font-size:var(--t-12);font-weight:500;color:var(--text-2);transition:border-color var(--t), background var(--t);user-select:none;}
.hns-option input[type="radio"]{display:none;}
.hns-option:hover{border-color:var(--blue);background:color-mix(in srgb, var(--canvas) 92%, var(--blue));}
.hns-option.active{border-color:var(--blue);background:color-mix(in srgb, var(--canvas) 86%, var(--blue));color:var(--text-1);}
.hns-dot{width:9px;height:9px;border-radius:50%;display:inline-block;flex-shrink:0;}
.hns-dot--chuac{background:var(--chuac);}
.hns-dot--sergas{background:var(--sergas);}
.hns-dot--external{background:var(--ext-hosp);}
.inline-add-hospital{margin-top:10px;padding:12px 14px;background:var(--surface);border-radius:8px;border:1px solid var(--border);animation:fadeSlideDown 160ms cubic-bezier(.4,0,.2,1);}
.iah-label{font-size:11px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;opacity:.5;margin-bottom:8px;}
.db-greeting-title{font-family:var(--font-display);font-size:clamp(22px, 2.8vw, 36px);font-weight:400;line-height:1.2;color:var(--text-1);letter-spacing:-.01em;}
.db-greeting-title span{font-style:italic;color:var(--blue);}
.db-greeting-subtitle{font-family:var(--font-display);font-size:var(--t-13);font-style:italic;color:var(--text-3);margin-top:2px;}
.db-situation-sentence{font-size:var(--t-12);color:var(--text-2);margin-top:8px;line-height:1.5;padding:10px 14px;background:var(--blue-lt);border-left:3px solid var(--blue);border-radius:0 var(--r-sm) var(--r-sm) 0;display:flex;align-items:flex-start;gap:8px;}
.db-situation-sentence i{color:var(--blue);margin-top:2px;flex-shrink:0;}
.view-display-title{font-family:var(--font-display);font-size:var(--t-18);font-weight:400;color:var(--text-1);letter-spacing:-.01em;}
.dept-res-bar{display:flex;height:5px;border-radius:3px;overflow:hidden;margin-top:8px;gap:1px;}
.dept-res-bar-seg{height:100%;border-radius:2px;min-width:4px;transition:flex var(--t);}
.dept-res-bar-seg--int{background:var(--cat-internal);}
.dept-res-bar-seg--rot{background:var(--cat-rotating);}
.dept-res-bar-seg--ext{background:var(--cat-external);}
.dept-res-bar-seg--empty{background:var(--border);flex:1;}
.dept-unit-row{cursor:pointer;transition:background var(--t), padding-left var(--t);}
.dept-unit-row:hover{background:var(--blue-lt);padding-left:8px;border-radius:var(--r-sm);}
.dept-unit-row:hover .dept-unit-name{color:var(--blue);}
.dept-res-stat{cursor:pointer;transition:transform var(--t), box-shadow var(--t);border-radius:var(--r-sm);padding:4px 6px;}
.dept-res-stat:hover{transform:translateY(-1px);box-shadow:var(--shadow-sm);background:var(--surface);}
.tuc-cap-pill--partial{background:var(--partial-lt);color:var(--partial);border:1px solid var(--partial-mid);}
.tuc-tl-months{overflow-x:auto;scrollbar-width:thin;scrollbar-color:var(--border-2) transparent;scroll-behavior:smooth;position:relative;}
.tuc-tl-months::-webkit-scrollbar{height:3px;}
.tuc-tl-months::-webkit-scrollbar-thumb{background:var(--border-2);border-radius:2px;}
.tuc-timeline-body{position:relative;}
.tuc-timeline-body::after{content:"";position:absolute;top:0;right:0;width:32px;height:100%;background:linear-gradient(90deg, transparent, var(--surface) 85%);pointer-events:none;border-radius:0 var(--r) var(--r) 0;}
.tuc-tl-row{line-height:1.3;}
.ext-contact-chip{display:inline-flex;align-items:center;gap:5px;font-size:var(--t-11);color:var(--cat-external);background:var(--violet-lt);border:1px solid rgba(124,58,237,.2);border-radius:var(--r-sm);padding:2px 7px;text-decoration:none;transition:background var(--t);}
.ext-contact-chip:hover{background:rgba(124,58,237,.12);}
.ext-contact-chip i{font-size:10px;}
.nav-context-chip{display:inline-flex;align-items:center;gap:4px;font-size:var(--t-11);font-weight:500;color:var(--blue);background:var(--blue-lt);border:1px solid var(--blue-mid);border-radius:var(--r-sm);padding:3px 9px;cursor:pointer;transition:background var(--t), border-color var(--t);text-decoration:none;}
.nav-context-chip:hover{background:var(--blue-mid);border-color:var(--blue);}
.nav-context-chip i{font-size:10px;}
.skeleton-view{padding:4px;}
.skeleton-card-row{display:flex;gap:16px;margin-bottom:16px;}
.skeleton-card-row .skeleton-card{flex:1;}
.skeleton-grid{display:grid;grid-template-columns:repeat(auto-fill, minmax(320px, 1fr));gap:16px;}
.scc-ext-row{display:flex;align-items:center;gap:5px;font-size:var(--t-11);color:var(--cat-external);margin-top:3px;}
.scc-ext-row a{color:inherit;}
.rot-month-ruler{display:flex;height:20px;align-items:center;padding-left:168px;gap:4px;margin-bottom:-4px;}
.rot-month-tick{flex:0 0 auto;font-size:10px;font-family:var(--font-data);color:var(--text-4);letter-spacing:.02em;min-width:36px;text-align:center;}
.rot-month-tick.is-now{color:var(--blue);font-weight:600;}
.profile-rot-item{display:flex;flex-direction:column;gap:4px;padding:10px 12px;border-radius:var(--r);border:1px solid var(--border);margin-bottom:8px;transition:border-color var(--t), box-shadow var(--t);cursor:pointer;}
.profile-rot-item:hover{border-color:var(--blue-mid);box-shadow:var(--shadow-sm);}
.profile-rot-item--active{border-color:var(--ok-mid);background:var(--ok-lt);}
.profile-rot-unit{font-weight:600;font-size:var(--t-12);color:var(--text-1);}
.profile-rot-dates{font-size:var(--t-11);color:var(--text-3);font-family:var(--font-data);}
.profile-rot-status{display:flex;align-items:center;gap:8px;margin-top:2px;}
.rot-unit-preview{margin-top:8px;padding:10px;background:var(--surface-2);border-radius:var(--r);border:1px solid var(--border);}
.rot-unit-preview-title{font-size:var(--t-11);font-weight:600;color:var(--text-2);text-transform:uppercase;letter-spacing:.06em;margin-bottom:8px;}
.conflict-badge{display:flex;align-items:flex-start;gap:8px;padding:8px 12px;border-radius:var(--r);font-size:var(--t-11);line-height:1.4;}
.conflict-badge--warn{background:var(--warn-lt);color:#92400e;border:1px solid var(--warn-mid);}
.conflict-badge--ok{background:var(--ok-lt);color:#065f46;border:1px solid var(--ok-mid);}
.conflict-badge--err{background:var(--danger-lt);color:#991b1b;border:1px solid var(--danger-mid);}
.conflict-badge i{flex-shrink:0;margin-top:1px;}
.tuc-horizon-row{flex-wrap:wrap;display:flex;align-items:center;gap:4px;}
.db-situation-row{display:flex;flex-direction:column;gap:6px;margin-top:10px;}
.situation-item{display:flex;align-items:center;gap:8px;font-size:var(--t-12);color:var(--text-2);padding:7px 12px;border-radius:var(--r);background:var(--surface);border:1px solid var(--border);transition:border-color var(--t);cursor:pointer;}
.situation-item:hover{border-color:var(--blue-mid);}
.situation-item i{color:var(--blue);width:16px;text-align:center;flex-shrink:0;}
.situation-item strong{color:var(--text-1);}
.situation-item .sit-action{margin-left:auto;font-size:var(--t-11);color:var(--blue);font-weight:500;}
@media (max-width: 768px){.mobile-nav-training{display:flex !important;}
.mobile-nav-research{display:none !important;}}
@media (max-width: 900px){.tuc-timeline-body .tuc-tl-months{max-width:calc(100vw - 140px);}}
@keyframes popover-in{
  from { opacity: 0; transform: translateY(-4px); }
  to   { opacity: 1; transform: translateY(0); }
}
@keyframes resolve-pulse{
  0%, 100% { opacity: 1; transform: scale(1); }
  50%       { opacity: .5; transform: scale(1.15); }
}
.table tbody tr td{line-height:1.35;}
.rot-detail-date-range{display:flex;align-items:center;gap:6px;font-family:var(--font-data);font-size:var(--t-12);color:var(--text-2);background:var(--surface-2);border:1px solid var(--border);border-radius:var(--r-sm);padding:4px 10px;}
.rot-detail-date-range .sep{color:var(--text-4);}
.tl-popover-backdrop{position:fixed;inset:0;z-index:calc(var(--z-toast) - 1);}
.tl-popover{position:fixed;z-index:var(--z-toast);background:var(--surface);border:1px solid var(--border);border-radius:8px;box-shadow:0 8px 24px rgba(0,0,0,.13), 0 2px 6px rgba(0,0,0,.08);min-width:220px;max-width:300px;overflow:hidden;animation:popover-in .12s ease;}
.tl-popover-header{display:flex;align-items:center;gap:5px;padding:8px 10px 7px;background:var(--surface-2);border-bottom:1px solid var(--border);font-size:11px;}
.tl-popover-unit{font-weight:700;color:var(--text-1);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100px;}
.tl-popover-sep{color:var(--text-4);}
.tl-popover-slot{font-weight:600;color:var(--text-2);flex-shrink:0;}
.tl-popover-month{font-weight:700;color:var(--blue);flex-shrink:0;text-transform:uppercase;letter-spacing:.04em;}
.tl-popover-close{margin-left:auto;flex-shrink:0;background:none;border:none;cursor:pointer;color:var(--text-4);font-size:9px;padding:2px 4px;border-radius:3px;transition:var(--t);}
.tl-popover-close:hover{background:var(--border);color:var(--text-1);}
.tl-popover-body{padding:6px 10px 8px;display:flex;flex-direction:column;gap:5px;}
.tl-popover-entry{display:flex;align-items:center;gap:7px;font-size:12px;line-height:1.4;}
.tl-popover-dot{width:8px;height:8px;border-radius:50%;flex-shrink:0;}
.tl-popover-dot--occupied{background:var(--blue);}
.tl-popover-dot--partial{background:var(--warn);}
.tl-popover-dot--free{background:var(--ok);}
.tl-popover-name{font-weight:600;color:var(--text-1);flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.tl-popover-name--free{color:var(--ok);font-weight:500;font-style:italic;}
.tl-popover-dates{font-size:10.5px;color:var(--text-3);flex-shrink:0;font-family:var(--font-data);}
.tl-popover-partial-badge{font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.04em;padding:1px 5px;border-radius:3px;background:rgba(245,158,11,.12);color:var(--warn);border:1px solid rgba(245,158,11,.25);flex-shrink:0;}
.arm-actions{display:flex;flex-direction:column;gap:8px;}
.arm-action{display:flex;align-items:center;gap:14px;padding:12px 14px;border-radius:8px;border:1px solid var(--border);background:var(--surface-2);cursor:pointer;transition:border-color var(--t), background var(--t);}
.arm-action:hover{border-color:var(--blue-mid);background:var(--blue-lt);}
.arm-action--active{border-color:var(--blue);background:var(--blue-lt);box-shadow:0 0 0 2px rgba(45,122,255,.15);}
.arm-action-icon{width:36px;height:36px;border-radius:8px;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-size:14px;}
.arm-action-icon--ok{background:var(--ok-lt);color:var(--ok);}
.arm-action-icon--warn{background:var(--warn-lt);color:var(--warn);}
.arm-action-icon--neutral{background:var(--surface);color:var(--text-3);border:1px solid var(--border);}
.arm-action-title{font-size:13px;font-weight:600;color:var(--text-1);}
.arm-action-desc{font-size:11px;color:var(--text-3);margin-top:1px;}
.arm-archive-notice{display:flex;gap:10px;align-items:flex-start;padding:12px 14px;border-radius:8px;background:var(--neutral-lt, rgba(100,116,139,.08));border:1px solid var(--border);font-size:12px;color:var(--text-2);line-height:1.5;}
.arm-archive-notice i{color:var(--text-3);flex-shrink:0;margin-top:2px;}
.btn-pill-resolve{background:rgba(245,158,11,.1);color:var(--warn);border:1px solid rgba(245,158,11,.25);font-weight:600;}
.btn-pill-resolve:hover{background:rgba(245,158,11,.2);border-color:var(--warn);}
.row-completed .btn-pill-resolve{animation:resolve-pulse 2.5s ease-in-out infinite;}
.btn-pill-purge{background:transparent;color:var(--text-4);border:1px solid transparent;opacity:0.5;transition:all var(--t);}
.btn-pill-purge:hover{background:var(--danger-lt);color:var(--danger);border-color:var(--danger-mid);opacity:1;}
tr:not(:hover) .btn-pill-purge{opacity:0;pointer-events:none;}
.research-hub{position:relative;display:flex;flex-direction:column;gap:0;flex:1;min-height:0;overflow:hidden;}
.rhub-header{display:flex;align-items:center;justify-content:space-between;padding:16px 0 0;gap:16px;flex-wrap:wrap;}
.rhub-header-left{display:flex;align-items:center;gap:12px;min-width:0;flex:1;}
.rhub-eyebrow{font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.14em;color:var(--blue);opacity:.85;margin-bottom:3px;}
.rhub-title{font-family:var(--font-ui);font-size:20px;font-style:normal;font-weight:700;color:var(--text-1);letter-spacing:-.03em;line-height:1;margin:0;}
.rhub-context-pill{display:inline-flex;align-items:center;gap:6px;padding:4px 10px 4px 8px;border-radius:20px;background:var(--blue-lt);border:1px solid var(--blue-mid);color:var(--blue);font-size:11px;font-weight:600;white-space:nowrap;}
.rhub-ctx-clear{background:none;border:none;cursor:pointer;color:var(--blue);font-size:9px;padding:0 0 0 2px;opacity:.7;}
.rhub-ctx-clear:hover{opacity:1;}
.rhub-header-right{display:flex;gap:8px;flex-shrink:0;}
.rhub-tabs{display:flex;align-items:center;gap:2px;border-bottom:2px solid var(--border);margin-bottom:0;padding-bottom:0;flex-shrink:0;}
.rhub-tab{display:flex;align-items:center;gap:7px;padding:10px 18px;border:none;background:none;font-size:13px;font-weight:500;color:var(--text-3);cursor:pointer;border-bottom:2px solid transparent;margin-bottom:-2px;transition:color var(--t), border-color var(--t);white-space:nowrap;}
.rhub-tab:hover{color:var(--text-1);}
.rhub-tab-count{background:var(--surface-2);color:var(--text-3);font-size:10px;font-weight:700;padding:1px 6px;border-radius:10px;border:1px solid var(--border);}
.rhub-tab--active .rhub-tab-count{background:rgba(0,179,179,.1);color:#009999;border-color:rgba(0,179,179,.25);}
.rhub-tab--active{color:#009999;border-bottom-color:#009999;font-weight:600;}
.rhub-panel{padding:16px 0;}
.rhub-filter-bar{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px;}
.rhub-filter-bar .form-select{max-width:200px;}
.rhub-filter-bar .form-control{max-width:none;flex:1;min-width:160px;}
.rhub-empty{display:flex;flex-direction:column;align-items:center;gap:8px;padding:48px 24px;color:var(--text-3);text-align:center;grid-column:1 / -1;}
.rhub-empty i{font-size:28px;opacity:.35;}
.rhub-empty p{font-size:13px;margin:0;}
.rhub-lines-grid{display:grid;grid-template-columns:repeat(auto-fill, minmax(300px, 1fr));gap:12px;}
.rhl-card{background:var(--surface);border:1px solid var(--border);border-radius:10px;padding:16px 16px 13px;cursor:pointer;position:relative;overflow:hidden;transition:box-shadow var(--t), border-color var(--t), transform var(--t);display:flex;flex-direction:column;gap:10px;}
.rhl-card:hover{box-shadow:0 4px 16px rgba(0,153,153,.12);border-color:rgba(0,153,153,.3);transform:translateY(-1px);}
.rhl-card--inactive{opacity:.6;}
.rhl-accent{position:absolute;top:0;left:0;right:0;height:4px;}
.rhl-card:nth-child(6n/**/+1) .rhl-accent{background:linear-gradient(90deg, var(--dept-1), #6366f1);}
.rhl-card:nth-child(6n/**/+2) .rhl-accent{background:linear-gradient(90deg, var(--dept-2), #0891b2);}
.rhl-card:nth-child(6n/**/+3) .rhl-accent{background:linear-gradient(90deg, var(--dept-3), #0ea5e9);}
.rhl-card:nth-child(6n/**/+4) .rhl-accent{background:linear-gradient(90deg, var(--dept-4), #f97316);}
.rhl-card:nth-child(6n/**/+5) .rhl-accent{background:linear-gradient(90deg, var(--dept-5), #8b5cf6);}
.rhl-card:nth-child(6n/**/+0) .rhl-accent{background:linear-gradient(90deg, var(--dept-6), #ec4899);}
.rhl-top{display:flex;align-items:center;gap:6px;}
.rhl-number{font-family:var(--font-data);font-size:10px;font-weight:700;color:var(--blue);background:var(--blue-lt);border:1px solid var(--blue-mid);padding:1px 7px;border-radius:20px;}
.rhl-inactive-pill{font-size:9px;font-weight:600;color:var(--text-4);background:var(--surface-2);border:1px solid var(--border);padding:1px 6px;border-radius:20px;}
.rhl-actions{margin-left:auto;display:flex;gap:2px;opacity:0;transition:opacity var(--t);}
.rhl-card:hover .rhl-actions{opacity:1;}
.rhl-btn{width:24px;height:24px;border-radius:4px;border:none;background:var(--surface-2);color:var(--text-3);display:flex;align-items:center;justify-content:center;font-size:10px;cursor:pointer;transition:var(--t);}
.rhl-btn:hover{background:var(--blue-lt);color:var(--blue);}
.rhl-btn--danger:hover{background:var(--danger-lt);color:var(--danger);}
.rhl-name{font-family:var(--font-ui, "DM Sans", sans-serif);font-size:13.5px;font-style:normal;font-weight:500;color:var(--text-1);line-height:1.35;margin:0;letter-spacing:0;white-space:normal;}
.rhl-desc{font-size:12.5px;color:var(--text-2);line-height:1.55;margin:0;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;}
.rhl-stats{display:flex;align-items:center;gap:0;background:var(--surface-2);border:1px solid var(--border);border-radius:7px;overflow:hidden;margin-top:2px;}
.rhl-stat{flex:1;padding:8px 12px;cursor:pointer;transition:background var(--t);display:flex;flex-direction:column;gap:2px;}
.rhl-stat:hover{background:var(--blue-lt);}
.rhl-stat-num{font-family:var(--font-display, Georgia, serif);font-size:18px;font-weight:400;font-style:italic;color:var(--text-1);line-height:1;}
.rhl-stat-label{font-size:10px;color:var(--text-3);text-transform:uppercase;letter-spacing:.06em;font-weight:600;}
.rhl-stat-live{font-size:9px;font-weight:700;color:var(--ok);}
.rhl-stat-divider{width:1px;background:var(--border);align-self:stretch;}
.rhl-coordinator{margin-top:2px;}
.rhl-coord-row{display:flex;align-items:center;gap:7px;}
.rhl-coord-avatar{width:24px;height:24px;border-radius:50%;flex-shrink:0;background:linear-gradient(135deg, var(--blue), #6366f1);color:#fff;font-size:9px;font-weight:700;display:flex;align-items:center;justify-content:center;}
.rhl-coord-name{font-size:12px;font-weight:600;color:var(--text-2);flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.rhl-coord-btn{background:none;border:none;cursor:pointer;color:var(--text-4);font-size:10px;padding:2px;opacity:0;transition:opacity var(--t);}
.rhl-card:hover .rhl-coord-btn{opacity:1;}
.rhl-coord-btn:hover{color:var(--blue);}
.rhl-coord-empty{display:flex;align-items:center;gap:6px;font-size:11px;color:var(--text-4);font-style:italic;}
.rhl-keywords{display:flex;flex-wrap:wrap;gap:4px;margin-top:2px;}
.rhl-kw{font-size:9px;font-weight:600;padding:1px 6px;border-radius:3px;background:var(--surface-2);border:1px solid var(--border);color:var(--text-3);text-transform:uppercase;letter-spacing:.04em;}
.rhub-trials-list{display:flex;flex-direction:column;gap:4px;}
.rht-row{display:flex;align-items:center;gap:12px;padding:10px 12px;border-radius:6px;background:var(--surface);border:1px solid var(--border);cursor:pointer;transition:border-color var(--t), background var(--t);}
.rht-row:hover{border-color:var(--blue-mid);background:var(--blue-lt);}
.rht-phase-badge{width:28px;height:28px;border-radius:6px;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-size:9px;font-weight:800;color:#fff;letter-spacing:-.02em;}
.rht-main{flex:1;min-width:0;}
.rht-title{font-size:13px;font-weight:500;color:var(--text-1);white-space:normal;word-break:break-word;}
.rht-meta{font-size:11px;color:var(--text-3);display:flex;gap:4px;flex-wrap:nowrap;overflow:hidden;margin-top:1px;}
.rht-protocol{font-family:var(--font-data);font-size:10px;color:var(--text-4);}
.rht-sep{color:var(--border-2);}
.rht-enrollment{flex-shrink:0;min-width:60px;}
.rht-enroll-nums{font-family:var(--font-data);font-size:11px;font-weight:700;color:var(--text-2);text-align:right;}
.rht-enroll-bar{height:3px;background:var(--border);border-radius:2px;overflow:hidden;margin-top:2px;}
.rht-enroll-bar div{height:100%;border-radius:2px;transition:width .3s;}
.rht-dates{font-size:10px;color:var(--text-4);flex-shrink:0;white-space:nowrap;font-family:var(--font-data);}
.rht-status{flex-shrink:0;}
.rht-actions{display:flex;gap:3px;opacity:0;transition:opacity var(--t);flex-shrink:0;}
.rht-row:hover .rht-actions{opacity:1;}
.rha-subtabs{display:flex;gap:4px;margin-bottom:16px;border-bottom:1px solid var(--border);padding-bottom:0;}
.rha-subtab{padding:8px 14px;border:none;background:none;font-size:12px;font-weight:500;color:var(--text-3);cursor:pointer;border-bottom:2px solid transparent;margin-bottom:-1px;transition:color var(--t), border-color var(--t);display:flex;align-items:center;gap:6px;}
.rha-subtab:hover{color:var(--text-1);}
.rha-subtab.active{color:var(--blue);border-bottom-color:var(--blue);font-weight:600;}
.rha-kpi-strip{display:flex;gap:10px;margin-bottom:16px;}
.rha-kpi{flex:1;background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:14px 16px;}
.rha-kpi-val{font-family:var(--font-display, Georgia, serif);font-size:34px;font-weight:400;font-style:italic;color:var(--text-1);line-height:1;}
.rha-kpi-label{font-size:11px;font-weight:600;color:var(--text-2);text-transform:uppercase;letter-spacing:.06em;margin-top:4px;}
.rha-kpi-sub{font-size:11px;color:var(--ok);font-weight:600;margin-top:2px;}
.rha-charts-row{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:10px;}
.rha-chart-card{background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:16px;}
.rha-chart-card--wide{grid-column:1 / -1;}
.rha-chart-title{font-size:12px;font-weight:700;color:var(--text-2);text-transform:uppercase;letter-spacing:.06em;margin-bottom:12px;display:flex;align-items:center;gap:6px;}
.rha-chart-badge{margin-left:auto;font-size:10px;font-weight:600;background:var(--blue-lt);color:var(--blue);border:1px solid var(--blue-mid);padding:1px 7px;border-radius:10px;letter-spacing:0;text-transform:none;}
.rha-lines-overview{background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:16px;margin-bottom:10px;}
.rha-lines-table{display:flex;flex-direction:column;gap:0;}
.rha-lt-header{display:grid;grid-template-columns:50px 1fr 140px 60px 60px 80px;gap:12px;padding:6px 8px;font-size:10px;font-weight:700;color:var(--text-4);text-transform:uppercase;letter-spacing:.06em;border-bottom:1px solid var(--border);margin-bottom:4px;}
.rha-lt-row{display:grid;grid-template-columns:50px 1fr 140px 60px 60px 80px;gap:12px;padding:8px 8px;border-radius:6px;font-size:12px;align-items:center;transition:background var(--t);}
.rha-lt-row:hover{background:var(--blue-lt);}
.rha-lt-name{font-weight:500;color:var(--text-1);white-space:normal;word-break:break-word;}
.rha-lt-coord{color:var(--text-3);font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.rha-perf-grid{display:grid;grid-template-columns:repeat(auto-fill, minmax(300px, 1fr));gap:10px;}
.rha-perf-card{background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:14px 16px;cursor:pointer;transition:border-color var(--t), box-shadow var(--t);}
.rha-perf-card:hover{border-color:var(--blue-mid);box-shadow:0 2px 12px rgba(37,99,235,.08);}
.rha-perf-header{display:flex;align-items:baseline;gap:8px;margin-bottom:12px;}
.rha-perf-number{font-family:var(--font-display, Georgia, serif);font-size:13px;font-weight:400;font-style:italic;color:var(--blue);background:var(--blue-lt);border:1px solid var(--blue-mid);padding:1px 6px;border-radius:10px;flex-shrink:0;}
.rha-perf-name{font-size:13px;font-weight:500;color:var(--text-1);flex:1;min-width:0;white-space:normal;word-break:break-word;}
.rha-perf-coord{font-size:11px;color:var(--text-3);flex-shrink:0;}
.rha-perf-stats{display:grid;grid-template-columns:repeat(6, 1fr);gap:4px;margin-bottom:10px;}
.rha-ps{background:var(--surface-2);border-radius:5px;padding:6px 4px;text-align:center;}
.rha-ps--ok{background:var(--ok-lt);}
.rha-ps--blue{background:var(--blue-lt);}
.rha-ps--purple{background:rgba(139,92,246,.08);}
.rha-ps-val{font-family:var(--font-display, Georgia, serif);font-size:18px;font-weight:400;font-style:italic;color:var(--text-1);line-height:1;}
.rha-ps--ok .rha-ps-val{color:var(--ok);}
.rha-ps--blue .rha-ps-val{color:var(--blue);}
.rha-ps--purple .rha-ps-val{color:#7c3aed;}
.rha-ps-label{font-size:8px;font-weight:600;color:var(--text-4);text-transform:uppercase;letter-spacing:.05em;margin-top:2px;}
.rha-perf-bar{height:4px;background:var(--border);border-radius:2px;overflow:hidden;}
.rha-perf-bar-fill{height:100%;background:linear-gradient(90deg, var(--blue), #6366f1);border-radius:2px;transition:width .4s ease;}
.rldp-backdrop{position:fixed;inset:0;background:rgba(7,17,31,.25);z-index:var(--z-panel);backdrop-filter:blur(2px);}
.rldp{position:fixed;top:0;right:0;height:100vh;width:min(400px, 92vw);background:var(--surface);border-left:1px solid var(--border);box-shadow:-8px 0 32px rgba(7,17,31,.12);z-index:calc(var(--z-panel) + 1);display:flex;flex-direction:column;transform:translateX(100%);transition:transform .28s cubic-bezier(.22,.61,.36,1);overflow:hidden;}
.rldp--open{transform:translateX(0);}
.rldp-header{display:flex;align-items:flex-start;justify-content:space-between;padding:20px 20px 16px;border-bottom:1px solid var(--border);flex-shrink:0;}
.rldp-number{font-family:var(--font-display, Georgia, serif);font-size:13px;font-weight:400;font-style:italic;color:var(--blue);background:var(--blue-lt);border:1px solid var(--blue-mid);padding:2px 8px;border-radius:20px;display:inline-block;margin-bottom:6px;}
.rldp-title{font-family:var(--font-ui, "DM Sans", sans-serif);font-size:16px;font-style:normal;font-weight:500;color:var(--text-1);margin:0;line-height:1.3;}
.rldp-close{background:none;border:none;cursor:pointer;color:var(--text-4);font-size:14px;padding:4px;flex-shrink:0;transition:color var(--t);}
.rldp-close:hover{color:var(--text-1);}
.rldp-body{flex:1;overflow-y:auto;padding:16px 20px;display:flex;flex-direction:column;gap:16px;}
.rldp-description{font-size:13px;color:var(--text-2);line-height:1.6;margin:0;}
.rldp-section-label{font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.1em;color:var(--text-4);margin-bottom:6px;}
.rldp-coord{display:flex;align-items:center;gap:8px;}
.rldp-coord-avatar{width:30px;height:30px;border-radius:50%;background:linear-gradient(135deg, var(--blue), #6366f1);color:#fff;font-size:10px;font-weight:700;display:flex;align-items:center;justify-content:center;flex-shrink:0;}
.rldp-empty{font-size:12px;color:var(--text-4);font-style:italic;}
.rldp-stats-row{display:grid;grid-template-columns:1fr 1fr;gap:8px;}
.rldp-stat-block{background:var(--surface-2);border:1px solid var(--border);border-radius:8px;padding:12px 14px;cursor:pointer;transition:border-color var(--t), background var(--t);}
.rldp-stat-block:hover{border-color:var(--blue-mid);background:var(--blue-lt);}
.rldp-stat-num{font-family:var(--font-display, Georgia, serif);font-size:30px;font-weight:400;font-style:italic;color:var(--text-1);line-height:1;}
.rldp-stat-label{font-size:10px;font-weight:600;color:var(--text-3);text-transform:uppercase;letter-spacing:.06em;margin-top:3px;}
.rldp-stat-active{font-size:10px;font-weight:700;color:var(--ok);margin-top:2px;}
.rldp-stat-link{font-size:10px;color:var(--blue);margin-top:4px;opacity:0;transition:opacity var(--t);}
.rldp-stat-block:hover .rldp-stat-link{opacity:1;}
.rldp-text{font-size:12px;color:var(--text-2);line-height:1.5;margin:0;}
.rldp-keywords{display:flex;flex-wrap:wrap;gap:4px;}
.rldp-footer{padding:12px 20px;border-top:1px solid var(--border);display:flex;gap:8px;flex-shrink:0;}
.dbr-strip{display:flex;align-items:center;gap:10px;padding:8px 14px;margin-bottom:16px;background:var(--surface);border:1px solid var(--border);border-radius:10px;flex-wrap:wrap;}
.dbr-strip--clear{color:var(--ok);font-size:12px;font-weight:600;gap:7px;background:var(--ok-lt);border-color:var(--ok-mid);}
.dbr-label{font-size:10px;font-weight:800;text-transform:uppercase;letter-spacing:.1em;color:var(--text-4);display:flex;align-items:center;gap:5px;flex-shrink:0;}
.dbr-label i{color:var(--warn);}
.dbr-items{display:flex;gap:6px;flex:1;flex-wrap:wrap;}
.dbr-item{display:inline-flex;align-items:center;gap:7px;padding:5px 11px;border-radius:20px;font-size:12px;font-weight:500;cursor:pointer;transition:all var(--t);border:1px solid transparent;flex-shrink:0;}
.dbr-item--danger{background:var(--danger-lt);color:var(--danger);border-color:var(--danger-mid);}
.dbr-item--warn{background:var(--warn-lt);color:var(--warn);border-color:var(--warn-mid);}
.dbr-item--info{background:var(--blue-lt);color:var(--blue);border-color:var(--blue-mid);}
.dbr-item--ok{background:var(--ok-lt);color:var(--ok);border-color:var(--ok-mid);}
