.dbr-icon{font-size:11px;flex-shrink:0;}
.dbr-text{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:260px;}
.dbr-arrow{font-size:9px;opacity:.6;flex-shrink:0;}
.rgw-strip{background:var(--warn-lt);border:1px solid var(--warn-mid);border-radius:10px;padding:12px 14px;margin-bottom:14px;}
.rgw-header{display:flex;align-items:center;gap:8px;margin-bottom:10px;}
.rgw-icon{color:var(--warn);font-size:13px;flex-shrink:0;}
.rgw-title{font-size:12px;font-weight:700;color:var(--warn);flex:1;}
.rgw-sub{font-size:10px;color:var(--text-3);flex-shrink:0;}
.rgw-list{display:flex;flex-wrap:wrap;gap:6px;}
.rgw-item{display:inline-flex;align-items:center;gap:7px;background:var(--surface);border:1px solid var(--warn-mid);border-radius:8px;padding:6px 10px;cursor:pointer;transition:all var(--t);}
.rgw-item:hover{border-color:var(--warn);box-shadow:0 2px 8px rgba(217,119,6,.15);transform:translateY(-1px);}
.rgw-avatar{width:24px;height:24px;border-radius:50%;flex-shrink:0;background:linear-gradient(135deg, var(--warn), #d97706);color:#fff;font-size:9px;font-weight:700;display:flex;align-items:center;justify-content:center;}
.rgw-info{display:flex;flex-direction:column;gap:1px;}
.rgw-name{font-size:11px;font-weight:700;color:var(--text-1);}
.rgw-year{font-family:var(--font-data);font-size:9px;color:var(--text-4);font-weight:600;text-transform:uppercase;}
.rgw-gaps{display:flex;gap:3px;flex-wrap:wrap;}
.rgw-gap-pill{font-size:9px;font-weight:700;padding:1px 6px;border-radius:10px;background:rgba(217,119,6,.12);color:var(--warn);border:1px solid rgba(217,119,6,.25);}
.rgw-add-icon{font-size:10px;color:var(--blue);opacity:.6;margin-left:2px;}
.rgw-item:hover .rgw-add-icon{opacity:1;}
.oc-overnight-hint{display:flex;align-items:center;gap:6px;margin-top:6px;padding:6px 10px;background:rgba(99,102,241,.08);border:1px solid rgba(99,102,241,.2);border-radius:7px;font-size:11px;font-weight:500;color:#4f46e5;}
.oc-overnight-hint i{font-size:10px;}
.oc-overnight-hint strong{font-weight:700;}
.db-kpi-bar{display:grid;grid-template-columns:repeat(4, 1fr);gap:12px;margin-bottom:20px;}
.db-kpi:hover{border-color:var(--blue-mid);box-shadow:var(--shadow-sm);transform:translateY(-1px);}
.db-kpi-icon{width:40px;height:40px;border-radius:10px;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-size:16px;}
.db-kpi-icon--teal{background:rgba(0,153,153,.08);}
.db-kpi-icon--navy{background:rgba(15,45,84,.07);}
.db-kpi-icon--amber{background:rgba(239,159,39,.1);}
.db-kpi-icon--indigo{background:rgba(83,74,183,.08);}
.db-kpi-icon--blue{background:rgba(0,153,153,.08);}
.db-kpi-icon--green{background:rgba(0,153,153,.08);}
.db-kpi-icon--purple{background:rgba(83,74,183,.08);}
.db-kpi{background:var(--surface);border:1px solid var(--border);border-radius:var(--r-lg);padding:18px 20px;display:flex;align-items:flex-start;gap:14px;cursor:pointer;transition:all var(--t);box-shadow:var(--shadow-xs);position:relative;overflow:hidden;}
.db-kpi::before{content:"";position:absolute;top:0;left:0;right:0;height:3px;border-radius:12px 12px 0 0;}
.db-kpi--teal::before{background:#009999;}
.db-kpi--navy::before{background:#0f2d54;}
.db-kpi--amber::before{background:#ef9f27;}
.db-kpi--indigo::before{background:#534ab7;}
.db-kpi-body{flex:1;min-width:0;}
.db-kpi-val{font-family:var(--font-data);font-size:28px;font-weight:800;color:var(--text-1);line-height:1;margin-bottom:3px;}
.db-kpi-label{font-size:13px;font-weight:600;color:var(--text-2);margin-top:0;letter-spacing:-.01em;}
.db-kpi-sub{font-size:12px;color:var(--text-3);margin-top:5px;display:flex;align-items:center;flex-wrap:wrap;gap:4px;}
.db-kpi-dot{width:6px;height:6px;border-radius:50%;display:inline-block;flex-shrink:0;}
.db-kpi-dot--ok{background:var(--ok);}
.db-kpi-dot--warn{background:var(--warn);}
.db-kpi-dot--blue{background:var(--blue);}
.db-kpi-dot--purple{background:#7c3aed;}
.db-content-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;}
.db-content-card{padding:13px 16px;}
.db-content-card--full{grid-column:1 / -1;}
.db-cc-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:10px;}
.db-cc-title{font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--text-2);display:flex;align-items:center;gap:6px;}
.db-cc-link{font-size:10px;color:var(--blue);background:none;border:none;cursor:pointer;display:flex;align-items:center;gap:4px;transition:opacity var(--t);padding:0;}
.db-cc-link:hover{opacity:.7;}
.db-cc-loading{padding:20px;text-align:center;color:var(--text-4);font-size:13px;}
.db-cc-empty{display:flex;align-items:center;gap:8px;font-size:12px;color:var(--text-3);padding:12px 0;}
.db-gap-grid{display:flex;flex-wrap:wrap;gap:6px;}
.db-gap-item{display:inline-flex;align-items:center;gap:7px;background:var(--surface-2);border:1px solid var(--warn-mid);border-radius:8px;padding:5px 10px;cursor:pointer;transition:all var(--t);}
.db-gap-item:hover{border-color:var(--warn);transform:translateY(-1px);box-shadow:0 2px 8px rgba(217,119,6,.12);}
.db-gap-avatar{width:22px;height:22px;border-radius:50%;flex-shrink:0;background:linear-gradient(135deg, var(--warn), #d97706);color:#fff;font-size:8px;font-weight:700;display:flex;align-items:center;justify-content:center;}
.db-gap-info{display:flex;flex-direction:column;}
.db-gap-name{font-size:11px;font-weight:700;color:var(--text-1);}
.db-gap-year{font-family:var(--font-data);font-size:9px;color:var(--text-4);font-weight:600;}
.db-gap-pills{display:flex;gap:3px;}
.db-gap-pill{font-size:9px;font-weight:700;padding:1px 5px;border-radius:8px;background:rgba(217,119,6,.1);color:var(--warn);border:1px solid rgba(217,119,6,.2);}
.db-gap-add{font-size:10px;color:var(--blue);opacity:.6;}
.db-gap-item:hover .db-gap-add{opacity:1;}
@media (max-width: 900px){.db-kpi-bar{grid-template-columns:repeat(2, 1fr);}
.db-content-grid{grid-template-columns:1fr;}
.db-content-card--full{grid-column:1;}}
.mv-view{display:flex;flex-direction:column;gap:0;}
.mv-nav{display:flex;align-items:center;gap:10px;padding:10px 16px;border-bottom:1px solid var(--border);background:var(--surface-2);flex-shrink:0;}
.mv-nav-btn{width:30px;height:30px;border-radius:7px;border:1px solid var(--border);background:var(--surface);color:var(--text-3);cursor:pointer;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-size:11px;transition:all var(--t);}
.mv-nav-btn:hover{background:var(--blue-lt);border-color:var(--blue-mid);color:var(--blue);}
.mv-nav-center{flex:1;display:flex;align-items:center;justify-content:center;gap:8px;}
.mv-nav-label{font-size:13px;font-weight:700;color:var(--text-1);letter-spacing:-.01em;}
.mv-nav-today{padding:3px 10px;border-radius:20px;font-size:11px;font-weight:600;border:1px solid var(--blue-mid);background:var(--blue-lt);color:var(--blue);cursor:pointer;transition:all var(--t);}
.mv-nav-today:hover{background:var(--blue);color:#fff;}
.mv-nav-horizon{display:flex;gap:3px;flex-shrink:0;}
.mv-hz-btn{padding:4px 10px;border-radius:6px;font-size:11px;font-weight:600;border:1px solid var(--border);background:var(--surface);color:var(--text-3);cursor:pointer;transition:all var(--t);}
.mv-hz-btn.active{background:var(--blue);border-color:var(--blue);color:#fff;}
.mv-hz-btn:hover:not(.active){border-color:var(--blue-mid);color:var(--blue);}
.mv-grid{display:grid;border-left:1px solid var(--border);overflow-x:auto;width:100%;}
.mv-name-spacer{grid-column:1;height:20px;border-right:1px solid var(--border);border-bottom:1px solid var(--border);background:var(--surface-2);}
.mv-year-cell{height:20px;border-right:1px solid transparent;border-bottom:1px solid var(--border);background:var(--surface-2);display:flex;align-items:center;padding:0 6px;}
.mv-year-label{font-family:var(--font-data);font-size:9px;font-weight:800;color:var(--blue);text-transform:uppercase;letter-spacing:.1em;}
.mv-name-header{padding:8px 12px;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.07em;background:var(--ink);color:rgba(255,255,255,0.75);border-right:1px solid rgba(255,255,255,.1);border-bottom:1px solid var(--border);display:flex;align-items:center;}
.mv-month-header{padding:8px 0;text-align:center;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;background:var(--ink);color:rgba(255,255,255,0.85);border-right:1px solid rgba(255,255,255,.08);border-bottom:1px solid var(--border);}
.mv-month-header--current{color:#fff;background:var(--ink-2);box-shadow:inset 0 -2px 0 var(--blue);}
.mv-name-cell{display:flex;align-items:center;gap:9px;padding:9px 12px;border-right:1px solid var(--border);border-bottom:1px solid var(--border);background:var(--surface);position:sticky;left:0;z-index:calc(var(--z-base) + 1);min-width:0;}
.mv-name-cell:hover{background:var(--blue-lt);}
.mv-resident-icon{width:28px;height:28px;border-radius:8px;flex-shrink:0;background:var(--blue-lt);border:1px solid var(--blue-mid);display:flex;align-items:center;justify-content:center;color:var(--blue);font-size:11px;}
.mv-resident-text{min-width:0;}
.mv-resident-name{font-size:12px;font-weight:600;color:var(--text-1);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.mv-resident-year{font-family:var(--font-data);font-size:10px;font-weight:700;color:var(--text-4);text-transform:uppercase;letter-spacing:.04em;margin-top:1px;}
.mv-months-area{grid-column:2 / -1;position:relative;display:grid;border-bottom:1px solid var(--border);min-height:48px;}
.mv-month-bg{border-right:1px solid var(--border);background:var(--surface);height:100%;}
.mv-month-bg:last-child{border-right:none;}
.mv-month-bg--current{background:rgba(37,99,235,.025);}
.mv-rot-bar{position:absolute;top:7px;height:26px;border-radius:5px;display:flex;align-items:center;padding:0 7px;gap:4px;cursor:pointer;overflow:hidden;transition:filter var(--t), transform var(--t), box-shadow var(--t);z-index:1;min-width:4px;}
.mv-rot-bar:hover{filter:brightness(1.08);transform:translateY(-1px);box-shadow:var(--shadow-sm);z-index:calc(var(--z-base) + 1);}
.mv-rot-bar--clipped-right{border-radius:5px 0 0 5px;padding-right:4px;}
.mv-rot-bar--clipped-left.mv-rot-bar--clipped-right{border-radius:0;}
.mv-rot-bar--active{background:rgba(10,143,110,.2);border:1px solid rgba(10,143,110,.45);border-left:3px solid #0a8f6e;color:#065f46;}
.mv-rot-bar--scheduled{background:var(--blue-lt);border:1px solid var(--blue-mid);border-left:3px solid var(--blue);color:var(--blue);}
.mv-rot-bar--completed{background:var(--surface-3);border:1px solid var(--border-2);border-left:3px solid var(--border-3);color:var(--text-3);}
.mv-rot-bar--clipped-left{border-radius:0 5px 5px 0;padding-left:4px;border-left-width:1px;}
.mv-rot-cap{width:5px;height:5px;border-radius:50%;background:currentColor;opacity:.6;flex-shrink:0;}
.mv-rot-cap--start{margin-right:1px;}
.mv-rot-cap--end{margin-left:auto;}
.mv-rot-label{font-size:10px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;flex:1;min-width:0;letter-spacing:-.01em;}
.mv-empty-state{grid-column:1 / -1;padding:48px;text-align:center;color:var(--text-4);font-size:13px;display:flex;align-items:center;justify-content:center;gap:8px;}
@media (max-width: 768px){.mv-grid{min-width:0;}
.mv-resident-name{font-size:11px;}
.mv-nav-horizon{display:none;}
.mv-rot-label{font-size:9px;}}
@keyframes rp-pulse{
  0%,100% { opacity: 1; transform: scale(1); }
  50%      { opacity: .5; transform: scale(1.2); }
}
@keyframes nrd-in{
  from { transform: translateX(48px); opacity: 0; }
  to   { transform: none; opacity: 1; }
}
.rhub-panel--mc{padding:0;display:flex;flex-direction:column;gap:0;flex:1;min-height:0;overflow:hidden;}
.rp-kpi-strip{display:flex;align-items:center;gap:0;padding:14px 20px;background:var(--surface);border-bottom:1px solid var(--border);flex-wrap:wrap;}
.rp-kpi{display:flex;flex-direction:column;gap:2px;padding:0 20px 0 0;min-width:100px;}
.rp-kpi:first-child{padding-left:0;}
.rp-kpi-val{font-family:var(--font-display, Georgia, serif);font-size:30px;font-weight:400;font-style:italic;color:var(--text-1);line-height:1;letter-spacing:-.02em;}
.rp-kpi-label{font-size:10px;font-weight:500;font-family:monospace;text-transform:uppercase;letter-spacing:.1em;color:var(--text-4);}
.rp-kpi-sub{font-size:10px;color:var(--text-4);margin-top:1px;}
.rp-kpi-div{width:1px;height:36px;background:var(--border);flex-shrink:0;margin:0 20px 0 0;}
.rp-kpi-search{margin-left:auto;min-width:200px;}
.rp-mc{display:grid;grid-template-columns:260px 1fr;flex:1;min-height:0;border-top:none;height:100%;}
.rp-nav{border-right:0.5px solid rgba(255,255,255,.08);overflow-y:auto;background:#0f2d54;display:flex;flex-direction:column;padding:10px 8px;gap:2px;}
.rp-nav-item{display:flex;align-items:flex-start;gap:10px;padding:10px 10px;border-radius:6px;cursor:pointer;transition:all var(--t);border-left:3px solid transparent;background:transparent;}
.rp-nav-item:hover{background:rgba(255,255,255,.06);border-left-color:rgba(255,255,255,.15);}
.rp-nav-item--active{background:rgba(0,179,179,.12) !important;border-left-color:#00B3B3 !important;}
.rp-nav-item--active .rp-nav-badge{color:#00B3B3 !important;}
.rp-nav-item--inactive{opacity:.4;}
.rp-nav-badge{font-family:var(--font-display, Georgia, serif);font-size:18px;font-weight:400;font-style:italic;color:#00B3B3;flex-shrink:0;width:36px;text-align:left;line-height:1;transition:all var(--t);padding-top:2px;letter-spacing:-.03em;}
.rp-nav-name{font-size:12px;font-weight:400;color:rgba(255,255,255,.82);white-space:normal;word-break:break-word;line-height:1.35;overflow:visible;}
.rp-nav-meta{font-size:10px;color:rgba(255,255,255,.35);margin-top:2px;display:flex;align-items:center;gap:5px;}
.rp-nav-dot{width:3px;height:3px;border-radius:50%;background:var(--border-2);flex-shrink:0;}
.rp-nav-live{display:block;width:7px;height:7px;border-radius:50%;background:var(--ok);box-shadow:0 0 0 2px rgba(5,150,105,.25);animation:rp-pulse 2s infinite;}
.rp-nav-empty{display:flex;flex-direction:column;align-items:center;gap:8px;padding:40px 20px;color:var(--text-4);font-size:12px;}
.rp-detail{display:flex;flex-direction:column;overflow:hidden;background:var(--surface);}
.rp-detail--empty{display:flex;align-items:center;justify-content:center;background:var(--surface-2);}
.rp-detail-empty-inner{text-align:center;padding:40px;}
.rp-detail-empty-icon{width:56px;height:56px;border-radius:14px;margin:0 auto 16px;background:var(--blue-lt);border:1px solid var(--blue-mid);display:flex;align-items:center;justify-content:center;font-size:22px;color:var(--blue);}
.rp-detail-empty-title{font-size:16px;font-weight:700;color:var(--text-1);margin-bottom:6px;}
.rp-detail-empty-sub{font-size:13px;color:var(--text-3);max-width:260px;margin:0 auto;line-height:1.5;}
.rp-study-bar{height:4px;background:rgba(255,255,255,.12);border-radius:2px;overflow:hidden;margin-top:4px;}
.rp-kpi-val--ok{color:#009999;}
.rp-nav-status{flex-shrink:0;display:flex;align-items:center;}
.rp-nav-info{flex:1;min-width:0;}
.rp-detail-head{display:flex;align-items:flex-start;justify-content:space-between;padding:18px 24px 20px;gap:12px;flex-shrink:0;min-height:100px;background:#0f2d54;}
.rp-detail-head-left{flex:1;min-width:0;}
.rp-detail-num{font-family:var(--font-display, Georgia, serif);font-size:52px;font-weight:400;font-style:italic;color:#00B3B3;line-height:.9;display:block;margin-bottom:8px;letter-spacing:-.04em;}
.rp-detail-num--accent{color:#00B3B3;font-size:52px;text-shadow:0 0 40px rgba(0,179,179,.3);}
.rp-detail-title{font-family:var(--font-ui, "DM Sans", sans-serif);font-size:14px;font-weight:500;color:rgba(255,255,255,.92);letter-spacing:0;line-height:1.4;margin:0;}
.rp-detail-head-actions{display:flex;gap:6px;flex-shrink:0;}
.rp-detail-btn{width:30px;height:30px;border-radius:7px;border:none;background:rgba(255,255,255,.15);color:#fff;cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:11px;transition:all var(--t);}
.rp-detail-btn:hover{background:rgba(255,255,255,.28);}
.rp-detail-btn--danger:hover{background:rgba(239,68,68,.3);}
.rp-detail-body{flex:1;overflow-y:auto;padding:20px 24px;display:flex;flex-direction:column;gap:20px;}
.rp-detail-stats{display:flex;gap:0;background:var(--surface-2);border:1px solid var(--border);border-radius:10px;overflow:hidden;}
.rp-ds-block{flex:1;padding:14px 18px;cursor:pointer;transition:background var(--t);border-right:1px solid var(--border);}
.rp-ds-block:last-child{border-right:none;}
.rp-ds-block:hover{background:var(--blue-lt);}
.rp-ds-val{font-family:var(--font-display, Georgia, serif);font-size:32px;font-weight:400;font-style:italic;color:var(--text-1);line-height:1;letter-spacing:-.02em;}
.rp-ds-label{font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.07em;color:var(--text-3);margin-top:4px;}
.rp-ds-sub{font-size:10px;color:var(--text-4);margin-top:2px;font-weight:600;}
.rp-detail-section{display:flex;flex-direction:column;gap:8px;}
.rp-detail-section-label{font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.09em;color:var(--text-4);display:flex;align-items:center;gap:6px;}
.rp-detail-section-label::after{content:"";flex:1;height:1px;background:var(--border);}
.rp-detail-desc{font-size:13px;color:var(--text-2);line-height:1.6;margin:0;}
.rp-detail-coord{display:flex;align-items:center;gap:12px;padding:10px 14px;background:var(--surface-2);border:1px solid var(--border);border-radius:8px;}
.rp-detail-coord-avatar{width:36px;height:36px;border-radius:50%;flex-shrink:0;color:#fff;font-size:12px;font-weight:700;display:flex;align-items:center;justify-content:center;}
.rp-detail-coord-name{font-size:13px;font-weight:600;color:var(--text-1);}
.rp-detail-coord-role{font-size:10px;color:var(--text-4);text-transform:uppercase;letter-spacing:.06em;font-weight:600;}
.rp-detail-no-coord{font-size:12px;color:var(--text-4);font-style:italic;display:flex;align-items:center;}
.rp-trial-list{display:flex;flex-direction:column;gap:6px;}
.rp-trial-row{display:flex;align-items:center;gap:12px;padding:10px 14px;background:var(--surface-2);border:1px solid var(--border);border-radius:8px;transition:border-color var(--t);}
.rp-trial-row:hover{border-color:var(--blue-mid);}
.rp-trial-info{flex:1;min-width:0;}
.rp-trial-title{font-size:12.5px;font-weight:500;color:var(--text-1);white-space:normal;word-break:break-word;line-height:1.4;verflow:ellipsis;}
.rp-trial-meta{font-size:10px;color:var(--text-4);margin-top:1px;font-family:var(--font-data);}
.rp-trial-right{display:flex;flex-direction:column;align-items:flex-end;gap:4px;flex-shrink:0;min-width:80px;}
.rp-trial-status{font-size:9px;font-weight:700;padding:2px 7px;border-radius:10px;}
.rp-trial-status--recruiting{background:var(--ok-lt);color:var(--ok);}
.rp-trial-status--active{background:var(--blue-lt);color:var(--blue);}
.rp-trial-status--done{background:var(--surface-3);color:var(--text-3);}
.rp-trial-bar{width:80px;height:3px;background:var(--border);border-radius:2px;overflow:hidden;}
.rp-trial-bar-fill{height:100%;border-radius:2px;transition:width .4s;}
.rp-trial-enroll{font-size:9px;font-family:var(--font-data);color:var(--text-4);margin-top:2px;}
.rp-view-all{font-size:11px;color:var(--blue);background:none;border:none;cursor:pointer;display:flex;align-items:center;gap:5px;padding:4px 0;transition:opacity var(--t);font-weight:600;}
.rp-view-all:hover{opacity:.7;}
.rp-detail-footer{display:flex;gap:8px;align-items:center;padding:12px 24px;border-top:1px solid var(--border);background:var(--surface-2);flex-shrink:0;}
.uop-trigger-btn{display:inline-flex;align-items:center;gap:7px;padding:7px 14px;border-radius:8px;border:1px solid var(--border-2);background:var(--surface-2);color:var(--text-2);font-size:13px;font-weight:600;cursor:pointer;transition:all var(--t);}
.uop-trigger-btn:hover{background:var(--blue-lt);border-color:var(--blue-mid);color:var(--blue);}
.uop-backdrop{position:fixed;inset:0;background:rgba(7,17,31,.45);z-index:var(--z-panel);backdrop-filter:blur(3px);display:flex;align-items:stretch;justify-content:flex-end;}
.uop-panel{width:min(760px, 96vw);height:100vh;background:var(--surface);border-left:1px solid var(--border);box-shadow:var(--shadow-xl);display:flex;flex-direction:column;overflow:hidden;transform:translateX(100%);transition:transform .3s cubic-bezier(.22,.61,.36,1);}
.uop-panel--open{transform:translateX(0);}
.uop-header{display:flex;align-items:center;justify-content:space-between;padding:20px 24px 16px;border-bottom:1px solid var(--border);flex-shrink:0;}
.uop-header-left{display:flex;align-items:center;gap:14px;}
.uop-header-icon{width:40px;height:40px;border-radius:10px;background:linear-gradient(135deg, var(--blue), #6366f1);display:flex;align-items:center;justify-content:center;color:#fff;font-size:16px;flex-shrink:0;}
.uop-title{font-size:18px;font-weight:700;color:var(--text-1);letter-spacing:-.02em;}
.uop-subtitle{font-size:12px;color:var(--text-3);margin-top:2px;}
.uop-close{width:32px;height:32px;border-radius:8px;border:1px solid var(--border);background:var(--surface-2);color:var(--text-3);cursor:pointer;display:flex;align-items:center;justify-content:center;transition:all var(--t);font-size:13px;}
.uop-close:hover{background:var(--danger-lt);color:var(--danger);border-color:var(--danger-mid);}
.uop-body{flex:1;overflow-y:auto;padding:16px 24px 32px;display:flex;flex-direction:column;gap:24px;}
.uop-swimlane-title{display:flex;align-items:center;gap:8px;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.07em;color:var(--text-2);margin-bottom:10px;}
.uop-swimlane-title--muted{color:var(--text-4);}
.uop-swimlane-dot{width:8px;height:8px;border-radius:50%;flex-shrink:0;}
.uop-swimlane-dot--free{background:var(--ok);box-shadow:0 0 5px rgba(5,150,105,.4);}
