.app-loading-splash{position:fixed;inset:0;z-index:var(--z-modal);background:var(--surface);display:flex;align-items:center;justify-content:center;}
.als-inner{display:flex;flex-direction:column;align-items:center;gap:20px;}
.als-logo{width:120px;height:auto;}
.als-bar-wrap{width:180px;height:3px;background:var(--border);border-radius:2px;overflow:hidden;}
.als-bar{height:100%;width:40%;background:linear-gradient(90deg, #48cae4, #4d9aff, #a5b4fc);border-radius:2px;animation:als-slide 1.4s ease-in-out infinite;}
.als-label{font-size:12px;font-weight:500;color:var(--text-3);letter-spacing:.05em;}
.splash-fade-leave-active{transition:opacity .35s ease;}
.splash-fade-leave-to{opacity:0;}
.login-error--warn{background:rgba(245,158,11,.1);border-color:rgba(245,158,11,.3);color:var(--warning);}
.login-error--warn .fa-clock{color:var(--warning);}
.rds-field--ext{background:var(--violet-lt);border-radius:4px;padding:4px 8px;margin:2px 0;}
.rds-field--ext .rds-field-key{color:var(--violet);}
.rds-mail-link{margin-left:6px;color:var(--blue);font-size:11px;opacity:.7;transition:opacity .15s;}
.rds-mail-link:hover{opacity:1;}
.rot-status-derived{display:inline-flex;align-items:center;gap:7px;padding:7px 14px;border-radius:6px;font-size:13px;font-weight:600;border:1px solid;width:100%;box-sizing:border-box;}
.rot-status-active{background:var(--ok-lt);color:var(--ok);border-color:var(--ok-mid);}
.rot-status-scheduled{background:var(--blue-lt);color:var(--blue);border-color:var(--blue-mid);}
.rot-status-completed{background:var(--surface-2);color:var(--text-3);border-color:var(--border);}
.rot-status-hint{font-size:11px;color:var(--text-3);margin-top:5px;display:flex;align-items:flex-start;gap:5px;line-height:1.5;}
.rot-status-hint i{flex-shrink:0;color:var(--blue);}
.rot-status-hint strong{color:var(--text-2);}
.status-indicator{display:inline-flex;align-items:center;gap:4px;padding:3px 9px;border-radius:20px;font-size:var(--t-10);font-weight:700;letter-spacing:.02em;white-space:nowrap;border:1px solid transparent;}
.status-indicator::before{content:"";width:5px;height:5px;border-radius:50%;background:currentColor;opacity:.8;}
.status-active{background:var(--ok-lt);color:#065f46;border-color:var(--ok-mid);}
.status-scheduled{background:var(--info-lt);color:#1e40af;border-color:var(--blue-mid);}
.status-completed{background:var(--surface-3);color:var(--neutral);border-color:var(--border);}
.status-extended{background:var(--warn-lt);color:#92400e;border-color:var(--warn-mid);}
.status-terminated_early{background:var(--danger-lt);color:#991b1b;border-color:var(--danger-mid);}
