.sidebar-dept-dot{width:6px;height:6px;border-radius:50%;background:var(--color-teal, #00B3B3);flex-shrink:0;}
.sidebar-dept-name{font-size:.75rem;font-weight:600;color:#fff;letter-spacing:.01em;line-height:1.2;}
.sidebar-dept-sub{font-size:.6rem;color:rgba(255,255,255,0.65);letter-spacing:.04em;text-transform:uppercase;margin-top:.15rem;}
.comms-tabs{display:flex;gap:3px;background:var(--surface-2);border-radius:var(--r);padding:3px;margin-bottom:16px;flex-wrap:wrap;}
.comms-tab{flex:1;padding:8px 12px;background:none;border:none;border-radius:var(--r-sm);font-size:var(--t-12);font-weight:600;color:var(--text-2);cursor:pointer;display:flex;align-items:center;justify-content:center;gap:6px;transition:var(--t);font-family:var(--font-ui);min-width:110px;min-height:40px;}
.comms-content{padding:0;}
.sm-modal{display:flex;max-width:min(820px, calc(100vw - 32px));width:100%;max-height:90vh;border-radius:16px;overflow:hidden;box-shadow:0 32px 80px rgba(0,0,0,.25), 0 4px 16px rgba(0,0,0,.1);border:0.5px solid rgba(255,255,255,.06);margin:auto;animation:slideUp .22s cubic-bezier(.22,1,.36,1);}
.sm-left{width:216px;flex-shrink:0;background:#0f2d54;display:flex;flex-direction:column;position:relative;overflow:hidden;}
.sm-left::before{content:"";position:absolute;top:0;left:0;right:0;height:2px;background:linear-gradient(90deg, #00B3B3, rgba(0,179,179,0));}
.sm-left::after{content:"";position:absolute;top:0;right:0;bottom:0;width:1px;background:linear-gradient(180deg, transparent, rgba(0,179,179,.2) 40%, transparent);}
.sm-preview{padding:26px 18px 18px;display:flex;flex-direction:column;align-items:center;gap:8px;border-bottom:0.5px solid rgba(255,255,255,.06);flex-shrink:0;}
.sm-preview-avatar{width:60px;height:60px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:1.125rem;font-weight:700;color:#fff;letter-spacing:-.02em;transition:all .3s;position:relative;}
.sm-preview-avatar--attending{background:linear-gradient(135deg, #00B3B3, #4A9EE8);box-shadow:0 0 0 2.5px rgba(0,179,179,.2), 0 0 0 5px rgba(0,179,179,.06);}
.sm-preview-avatar--resident{background:linear-gradient(135deg, #1e40af, #0e7490);box-shadow:0 0 0 2.5px rgba(30,64,175,.2), 0 0 0 5px rgba(30,64,175,.06);}
.sm-preview-avatar--empty{background:rgba(255,255,255,.05);border:1.5px dashed rgba(255,255,255,.12);box-shadow:none;}
.sm-preview-name{font-size:.8125rem;font-weight:700;color:#fff;text-align:center;line-height:1.25;letter-spacing:-.01em;transition:all .2s;}
.sm-preview-name--empty{color:rgba(255,255,255,0.42);font-weight:400;font-style:italic;}
.sm-preview-role{font-size:.55rem;font-family:var(--font-mono, monospace);letter-spacing:.12em;text-transform:uppercase;color:rgba(255,255,255,0.65);text-align:center;}
.sm-preview-chips{display:flex;flex-wrap:wrap;justify-content:center;gap:4px;}
.sm-preview-chip{font-size:.54rem;font-family:var(--font-mono, monospace);letter-spacing:.07em;text-transform:uppercase;padding:2px 7px;border-radius:99px;background:rgba(0,179,179,.1);border:0.5px solid rgba(0,179,179,.2);color:#00B3B3;}
.sm-preview-chip--resident{background:rgba(99,102,241,.1);border-color:rgba(99,102,241,.22);color:#818cf8;}
.sm-preview-chip--external{background:rgba(245,158,11,.1);border-color:rgba(245,158,11,.22);color:#f59e0b;}
.sm-step-nav{flex:1;padding:14px 12px;display:flex;flex-direction:column;}
.sm-step-item{display:flex;align-items:flex-start;gap:9px;padding:7px 8px;border-radius:7px;cursor:pointer;transition:all .15s;}
.sm-step-item:hover{background:rgba(255,255,255,.04);}
.sm-step-item.active{background:rgba(0,179,179,.08);}
.sm-step-num{width:20px;height:20px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:.6rem;font-weight:700;flex-shrink:0;border:1px solid rgba(255,255,255,.12);color:rgba(255,255,255,0.65);margin-top:1px;transition:all .2s;}
.sm-step-item.active .sm-step-num{background:rgba(0,179,179,.15);border-color:rgba(0,179,179,.4);color:#00B3B3;}
.sm-step-item.done .sm-step-num{background:#10b981;border-color:#10b981;color:#fff;}
.sm-step-info{flex:1;min-width:0;}
.sm-step-label{font-size:.72rem;font-weight:500;color:rgba(255,255,255,0.65);letter-spacing:-.005em;line-height:1.2;}
.sm-step-item.active .sm-step-label{color:#fff;font-weight:600;}
.sm-step-item.done .sm-step-label{color:rgba(255,255,255,0.65);}
.sm-step-hint{font-size:.56rem;font-family:var(--font-mono, monospace);color:rgba(255,255,255,0.30);letter-spacing:.03em;margin-top:2px;}
.sm-step-item.active .sm-step-hint{color:rgba(0,179,179,.45);}
.sm-step-connector{width:1px;height:10px;background:rgba(255,255,255,.07);margin:0 0 0 18px;flex-shrink:0;}
.sm-step-connector.done{background:rgba(16,185,129,.35);}
.sm-req-note{margin:0 12px 12px;font-size:.54rem;font-family:var(--font-mono, monospace);color:rgba(255,255,255,0.42);letter-spacing:.04em;display:flex;align-items:center;gap:5px;}
.sm-req-dot{width:5px;height:5px;border-radius:50%;background:#00B3B3;flex-shrink:0;}
.sm-right{flex:1;min-width:0;background:var(--surface, #fdfcfb);display:flex;flex-direction:column;}
.sm-form-header{padding:16px 22px 0;display:flex;align-items:center;justify-content:space-between;flex-shrink:0;}
.sm-form-title{font-size:.8125rem;font-weight:700;color:var(--text-1, #111827);letter-spacing:-.01em;display:flex;align-items:center;gap:7px;}
.sm-form-title svg{color:#00B3B3;flex-shrink:0;}
.sm-form-close{width:26px;height:26px;border-radius:50%;background:var(--surface-2, #f8f9fa);border:0.5px solid var(--border, rgba(0,0,0,.08));color:var(--text-3, #6b7280);display:flex;align-items:center;justify-content:center;cursor:pointer;transition:all .15s;}
.sm-form-close:hover{background:var(--surface-3, #f3f4f6);color:var(--text-1, #111827);}
.sm-form-body{flex:1;overflow-y:auto;padding:18px 22px;display:flex;flex-direction:column;gap:14px;}
.sm-form-body::-webkit-scrollbar{width:4px;}
.sm-form-body::-webkit-scrollbar-thumb{background:var(--border, rgba(0,0,0,.1));border-radius:2px;}
.sm-row{display:grid;grid-template-columns:1fr 1fr;gap:12px;}
.sm-field{display:flex;flex-direction:column;gap:4px;}
.sm-field.full{grid-column:1 / -1;}
.sm-label{font-size:.7rem;font-weight:600;color:var(--text-2, #374151);letter-spacing:-.003em;display:flex;align-items:center;gap:4px;}
.sm-label .req{color:#00B3B3;font-weight:700;}
.sm-label .hint{font-weight:400;color:var(--text-3, #6b7280);font-size:.63rem;margin-left:1px;}
.sm-input{height:34px;border:1px solid var(--border-2, rgba(0,0,0,.1));border-radius:8px;background:var(--surface-2, #f8f9fa);padding:0 11px;font-size:.8rem;color:var(--text-1, #111827);outline:none;width:100%;transition:all .15s;font-family:var(--font-ui, inherit);}
.sm-input:focus{border-color:#00B3B3;box-shadow:0 0 0 3px rgba(0,179,179,.1);background:var(--surface, #fdfcfb);}
.sm-input.filled{background:var(--surface, #fdfcfb);border-color:var(--border-2, rgba(0,0,0,.1));}
.sm-select{height:34px;border:1px solid var(--border-2, rgba(0,0,0,.1));border-radius:8px;background:var(--surface-2, #f8f9fa);padding:0 11px;font-size:.8rem;color:var(--text-1, #111827);outline:none;width:100%;transition:all .15s;font-family:var(--font-ui, inherit);cursor:pointer;}
.sm-select:focus{border-color:#00B3B3;box-shadow:0 0 0 3px rgba(0,179,179,.1);background:var(--surface, #fdfcfb);}
.sm-divider{display:flex;align-items:center;gap:9px;font-size:.58rem;font-family:var(--font-mono, monospace);letter-spacing:.1em;text-transform:uppercase;color:var(--text-3, #6b7280);margin:2px 0;}
.sm-divider::before{content:"";flex:1;height:0.5px;background:var(--border, rgba(0,0,0,.08));}
.sm-divider::after{content:"";flex:1;height:0.5px;background:var(--border, rgba(0,0,0,.08));}
.sm-network{display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px;}
.sm-network-opt{padding:6px 8px;border-radius:7px;border:1px solid var(--border, rgba(0,0,0,.08));background:var(--surface-2, #f8f9fa);text-align:center;cursor:pointer;font-size:.75rem;font-weight:500;color:var(--text-3, #6b7280);transition:all .15s;display:flex;flex-direction:column;align-items:center;gap:1px;}
.sm-network-opt small{font-size:.58rem;font-weight:400;color:var(--text-3, #6b7280);}
.sm-network-opt:hover{border-color:rgba(0,179,179,.3);color:var(--text-1, #111827);}
.sm-network-opt.active{border-color:#00B3B3;background:rgba(0,179,179,.06);color:#00B3B3;}
.sm-network-opt.active small{color:rgba(0,179,179,.6);}
.sm-cat-grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;}
.sm-cat-card{padding:11px 8px;border:1px solid var(--border, rgba(0,0,0,.08));border-radius:10px;cursor:pointer;text-align:center;transition:all .18s;display:flex;flex-direction:column;align-items:center;gap:5px;position:relative;overflow:hidden;}
.sm-cat-card::before{content:"";position:absolute;top:0;left:0;right:0;height:2px;background:transparent;transition:background .18s;}
.sm-cat-card:hover{border-color:rgba(0,179,179,.3);background:rgba(0,179,179,.03);}
.sm-cat-card:hover::before{background:rgba(0,179,179,.3);}
.sm-cat-card.active{border-color:#00B3B3;background:rgba(0,179,179,.06);}
.sm-cat-card.active::before{background:#00B3B3;}
.sm-cat-icon{width:30px;height:30px;border-radius:8px;display:flex;align-items:center;justify-content:center;transition:background .18s;}
.sm-cat-card.active .sm-cat-icon{background:rgba(0,179,179,.12);}
.sm-cat-card:not(.active) .sm-cat-icon{background:var(--surface-2, #f8f9fa);}
.sm-cat-name{font-size:.7rem;font-weight:600;color:var(--text-1, #111827);transition:color .18s;}
.sm-cat-card.active .sm-cat-name{color:#00B3B3;}
.sm-cat-desc{font-size:.58rem;color:var(--text-3, #6b7280);line-height:1.4;font-family:var(--font-mono, monospace);letter-spacing:.02em;}
.sm-origin-block{background:var(--surface-2, #f8f9fa);border:1px solid var(--border, rgba(0,0,0,.08));border-radius:10px;padding:14px;display:flex;flex-direction:column;gap:10px;}
.sm-capabilities{background:var(--surface-2, #f8f9fa);border:1px solid var(--border, rgba(0,0,0,.08));border-radius:10px;padding:14px;display:flex;flex-direction:column;gap:8px;}
.sm-cap-item{display:flex;align-items:center;gap:8px;font-size:.8rem;color:var(--text-2, #374151);cursor:pointer;}
.sm-cap-item input[type=checkbox]{accent-color:#00B3B3;width:14px;height:14px;flex-shrink:0;cursor:pointer;}
.sm-residency-row{display:grid;grid-template-columns:1fr auto 1fr;gap:8px;align-items:center;}
.sm-residency-arrow{color:var(--text-3, #6b7280);font-size:.8rem;text-align:center;}
.sm-ryear-chip{display:inline-flex;align-items:center;padding:5px 12px;border-radius:6px;background:rgba(0,179,179,.08);border:1px solid rgba(0,179,179,.2);font-size:.8rem;font-weight:700;color:#00B3B3;}
.sm-form-footer{padding:12px 22px;border-top:0.5px solid var(--border, rgba(0,0,0,.08));display:flex;align-items:center;justify-content:space-between;background:var(--surface-2, #f8f9fa);flex-shrink:0;}
.sm-footer-progress{font-size:.63rem;font-family:var(--font-mono, monospace);letter-spacing:.04em;color:var(--text-3, #6b7280);}
.sm-footer-actions{display:flex;gap:7px;align-items:center;}
.sm-btn-back{padding:6px 14px;border-radius:7px;border:0.5px solid var(--border, rgba(0,0,0,.1));background:transparent;font-size:.78rem;color:var(--text-2, #374151);cursor:pointer;transition:all .15s;}
.sm-btn-back:hover{background:var(--surface-3, #f3f4f6);}
.sm-btn-next{padding:7px 18px;border-radius:7px;background:#00B3B3;border:none;font-size:.78rem;font-weight:600;color:#fff;cursor:pointer;display:flex;align-items:center;gap:6px;transition:all .15s;}
.sm-btn-next:hover{background:#009999;}
.sm-btn-next:disabled{opacity:.45;cursor:not-allowed;}
.sm-btn-save{padding:7px 18px;border-radius:7px;background:#00B3B3;border:none;font-size:.78rem;font-weight:600;color:#fff;cursor:pointer;display:flex;align-items:center;gap:6px;transition:all .15s;}
.sm-btn-save:hover{background:#009999;}
.sm-btn-save:disabled{opacity:.45;cursor:not-allowed;}
.sm-edit-tabs{display:flex;gap:2px;border-bottom:0.5px solid var(--border, rgba(0,0,0,.08));padding:8px 22px 0;flex-shrink:0;background:var(--surface-2, #f8f9fa);}
.sm-edit-tab{display:flex;align-items:center;gap:5px;padding:7px 12px;font-size:.78rem;font-weight:500;color:var(--text-3, #6b7280);border-bottom:2px solid transparent;cursor:pointer;background:none;border-top:none;border-left:none;border-right:none;white-space:nowrap;transition:all .15s;}
.sm-edit-tab.active{color:#00B3B3;border-bottom-color:#00B3B3;}
.sm-inline-add{background:var(--surface-2, #f8f9fa);border:1px solid var(--border, rgba(0,0,0,.08));border-radius:10px;padding:14px;margin-top:8px;}
.sm-inline-add-label{font-size:.62rem;font-family:var(--font-mono, monospace);letter-spacing:.08em;text-transform:uppercase;color:var(--text-3, #6b7280);margin-bottom:10px;}
.sm-degree-block{display:flex;flex-direction:column;gap:10px;background:var(--surface-2,#f8f9fa);border:1px solid var(--border,rgba(0,0,0,.08));border-radius:10px;padding:14px;}
.sm-degree-baseline{display:flex;align-items:center;gap:10px;}
.sm-degree-badge-md{font-size:.65rem;font-family:var(--font-mono,monospace);font-weight:700;padding:4px 10px;border-radius:6px;background:rgba(0,179,179,.1);border:1px solid rgba(0,179,179,.2);color:#00B3B3;letter-spacing:.06em;flex-shrink:0;}
.sm-degree-badge-phd{font-size:.65rem;font-family:var(--font-mono,monospace);font-weight:700;padding:3px 8px;border-radius:5px;background:rgba(99,102,241,.1);border:0.5px solid rgba(99,102,241,.2);color:#818cf8;letter-spacing:.06em;flex-shrink:0;}
.sm-degree-baseline-name{font-size:.8rem;font-weight:600;color:var(--text-1,#111827);}
.sm-degree-baseline-hint{font-size:.65rem;color:var(--text-3,#6b7280);font-family:var(--font-mono,monospace);}
.sm-degree-phd-check{display:flex;align-items:center;gap:10px;cursor:pointer;padding:8px 10px;border-radius:8px;border:1px solid var(--border,rgba(0,0,0,.08));background:var(--surface,#fdfcfb);transition:all .15s;}
.sm-degree-phd-check:hover{border-color:rgba(99,102,241,.3);background:rgba(99,102,241,.03);}
.sm-degree-phd-info{display:flex;align-items:center;gap:8px;}
.sm-roles-section{display:flex;flex-direction:column;gap:4px;}
.sm-roles-section-label{font-size:.58rem;font-family:var(--font-mono,monospace);letter-spacing:.12em;text-transform:uppercase;color:var(--text-3,#6b7280);padding:6px 0 4px;display:flex;align-items:center;gap:8px;}
.sm-roles-section-label::after{content:"";flex:1;height:0.5px;background:var(--border,rgba(0,0,0,.08));}
.sm-role-row{display:flex;align-items:center;justify-content:space-between;padding:10px 12px;border-radius:8px;border:1px solid var(--border,rgba(0,0,0,.08));background:var(--surface,#fdfcfb);transition:all .15s;cursor:pointer;}
.sm-role-row:hover{border-color:rgba(0,179,179,.25);}
.sm-role-row.active{border-color:rgba(0,179,179,.3);background:rgba(0,179,179,.04);}
.sm-role-row.muted{opacity:.5;cursor:not-allowed;}
.sm-role-left{display:flex;align-items:center;gap:9px;min-width:0;}
.sm-role-name{font-size:.78rem;font-weight:500;color:var(--text-1,#111827);}
.sm-role-hint{font-size:.65rem;color:var(--text-3,#6b7280);font-family:var(--font-mono,monospace);margin-top:1px;}
.sm-toggle{width:32px;height:18px;border-radius:9px;background:var(--border-2,rgba(0,0,0,.15));position:relative;flex-shrink:0;transition:background .2s;cursor:pointer;}
.sm-toggle.on{background:#00B3B3;}
.sm-toggle.disabled{opacity:.4;cursor:not-allowed;}
.sm-toggle-thumb{width:14px;height:14px;border-radius:50%;background:#fff;position:absolute;top:2px;left:2px;transition:transform .2s;box-shadow:0 1px 3px rgba(0,0,0,.2);}
.sm-toggle.on .sm-toggle-thumb{transform:translateX(14px);}
.sm-role-sub{margin:0 0 4px 22px;background:rgba(0,179,179,.03);border:1px solid rgba(0,179,179,.15);border-radius:8px;padding:10px 12px;display:flex;flex-direction:column;gap:4px;}
.sm-role-sub-label{font-size:.58rem;font-family:var(--font-mono,monospace);letter-spacing:.1em;text-transform:uppercase;color:var(--text-3,#6b7280);margin-bottom:5px;}
.sm-role-line-item{display:flex;align-items:center;gap:8px;padding:5px 8px;border-radius:6px;cursor:pointer;font-size:.78rem;color:var(--text-2,#374151);transition:all .12s;}
.sm-role-line-item:hover{background:rgba(0,179,179,.06);}
.sm-role-line-item.selected{background:rgba(0,179,179,.1);color:#00B3B3;font-weight:500;}
.sm-role-line-n{font-family:var(--font-mono,monospace);font-size:.65rem;color:var(--text-3,#6b7280);width:22px;flex-shrink:0;}
.sm-role-line-item.selected .sm-role-line-n{color:rgba(0,179,179,.7);}
.sm-role-line-name{flex:1;}
.sm-role-cap-row{display:flex;gap:6px;flex-wrap:wrap;}
.sm-role-cap-opt{display:flex;align-items:center;gap:6px;padding:6px 10px;border-radius:7px;border:1px solid var(--border,rgba(0,0,0,.08));font-size:.75rem;color:var(--text-2,#374151);cursor:pointer;transition:all .15s;background:var(--surface,#fdfcfb);flex:1;}
.sm-role-cap-opt:hover{border-color:rgba(0,179,179,.3);}
.sm-role-cap-opt.active{border-color:rgba(0,179,179,.3);background:rgba(0,179,179,.06);color:#00B3B3;}
.sm-btn-next--ready{animation:btnReadyPulse 2s ease-in-out infinite;box-shadow:0 0 0 0 rgba(0,179,179,.4);}
.sm-reason-grid{display:grid;grid-template-columns:repeat(3, 1fr);gap:7px;}
.sm-multi-check-grid{display:flex;flex-wrap:wrap;gap:5px;}
.sm-check-pill{display:flex;align-items:center;gap:5px;padding:4px 10px;border-radius:99px;cursor:pointer;font-size:.72rem;font-weight:500;border:0.5px solid var(--border,rgba(0,0,0,.08));background:var(--surface,#fdfcfb);color:var(--text-2,#374151);transition:all .15s;}
.sm-check-pill:hover{border-color:rgba(0,179,179,.3);}
.sm-check-pill.active{border-color:rgba(0,179,179,.35);background:rgba(0,179,179,.07);color:#00B3B3;font-weight:600;}
.sm-check-pill .hidden{display:none;}
.nm-modal{background:var(--surface,#fdfcfb);border-radius:16px;width:min(700px, calc(100vw - 32px));max-height:calc(100vh - 48px);display:flex;flex-direction:column;overflow:hidden;box-shadow:0 24px 64px rgba(0,0,0,.22), 0 0 0 0.5px rgba(0,0,0,.08);}
.nm-header{background:#0f2d54;padding:14px 18px;display:flex;align-items:center;justify-content:space-between;gap:12px;flex-shrink:0;border-bottom:0.5px solid rgba(255,255,255,.06);}
.nm-header-left{display:flex;align-items:center;gap:11px;min-width:0;}
.nm-header-right{display:flex;align-items:center;gap:8px;flex-shrink:0;}
.nm-type-icon{width:34px;height:34px;border-radius:9px;flex-shrink:0;background:rgba(0,179,179,.1);border:0.5px solid rgba(0,179,179,.2);display:flex;align-items:center;justify-content:center;}
.nm-header-meta{min-width:0;}
.nm-header-title{font-size:.82rem;font-weight:700;color:#fff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:380px;}
.nm-header-sub{display:flex;align-items:center;gap:5px;margin-top:2px;}
.nm-type-badge{font-size:.6rem;font-family:monospace;letter-spacing:.08em;color:#00B3B3;text-transform:uppercase;}
.nm-status-badge{font-size:.6rem;font-family:monospace;padding:3px 8px;border-radius:99px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;background:rgba(245,158,11,.1);color:#f59e0b;border:0.5px solid rgba(245,158,11,.2);}
.nm-type-bar{display:flex;gap:0;padding:0 18px;background:var(--surface-2,#f5f4f0);border-bottom:0.5px solid var(--border,#e3dfd6);flex-shrink:0;}
.nm-type-opt{display:flex;align-items:center;gap:5px;padding:9px 13px;font-size:.72rem;font-weight:500;color:var(--text-3,#5a6472);cursor:pointer;background:none;border:none;border-bottom:2px solid transparent;margin-bottom:-0.5px;transition:all .15s;white-space:nowrap;}
.nm-type-opt:hover{color:var(--text-1,#07111f);}
.nm-type-opt.active{color:#009999;border-bottom-color:#009999;font-weight:600;}
.nm-tabs{display:flex;padding:0 18px;gap:0;border-bottom:0.5px solid var(--border,#e3dfd6);flex-shrink:0;background:var(--surface,#fdfcfb);}
.nm-tab{display:flex;align-items:center;gap:5px;padding:10px 14px;font-size:.75rem;font-weight:500;color:var(--text-3,#5a6472);cursor:pointer;background:none;border:none;border-bottom:2px solid transparent;margin-bottom:-0.5px;transition:all .15s;}
.nm-tab:hover{color:var(--text-1,#07111f);}
.nm-tab.active{color:#009999;border-bottom-color:#009999;font-weight:600;}
.nm-body{flex:1;overflow-y:auto;padding:18px 20px;display:flex;flex-direction:column;gap:12px;}
