@import url("https://fonts.googleapis.com/css2?family=Instrument+Serif:ital@0;1&family=DM+Sans:ital,opsz,wght@0,9..40,300;0,9..40,400;0,9..40,500;0,9..40,600;0,9..40,700&family=DM+Mono:wght@400;500&display=swap");
@keyframes popoverIn{ from { opacity:0; transform:translateY(6px) scale(.97) } to { opacity:1; transform:translateY(0) scale(1) } }
@keyframes popoverOut{ from { opacity:1; transform:scale(1) } to { opacity:0; transform:scale(.96) } }
@keyframes pulsering{ 0%,100% { opacity:.6; transform:scale(1) } 50% { opacity:0; transform:scale(1.8) } }
@keyframes slideUp{
  from { opacity: 0; transform: translateY(10px); }
  to   { opacity: 1; transform: translateY(0); }
}
:root{--pulse-available:#00b3b3;--pulse-oncall:#f59e0b;--pulse-leave:#ef4444;--pulse-ending:#8b5cf6;--pulse-inactive:#d1d5db;--surface-glass:rgba(255,255,255,0.72);--surface-glass-dark:rgba(7,17,31,0.82);--shadow-card:0 2px 8px rgba(0,0,0,.06), 0 0 0 1px rgba(0,0,0,.04);--shadow-float:0 8px 32px rgba(0,0,0,.12), 0 2px 8px rgba(0,0,0,.08);--shadow-popover:0 16px 48px rgba(0,0,0,.14), 0 4px 12px rgba(0,0,0,.08), 0 0 0 1px rgba(0,0,0,.06);--transition-fast:0.12s cubic-bezier(0.22,1,0.36,1);--transition-med:0.22s cubic-bezier(0.22,1,0.36,1);--transition-spring:0.35s cubic-bezier(0.34,1.56,0.64,1);}
#app .intel-popover-wrap{position:fixed;z-index:9800;pointer-events:none;transition:opacity var(--transition-fast);}
#app .intel-popover-wrap.entering{animation:popoverIn 0.18s cubic-bezier(0.22,1,0.36,1) forwards;}
#app .intel-popover-wrap.leaving{animation:popoverOut 0.12s ease forwards;}
#app .intel-pop{width:280px;background:var(--nm-surface);border:1px solid var(--nm-border);border-radius:14px;box-shadow:var(--shadow-popover);overflow:hidden;font-size:13px;pointer-events:none;}
#app .intel-pop-header{display:flex;align-items:center;gap:12px;padding:14px 16px 10px;border-bottom:1px solid var(--nm-border);}
#app .intel-pop-av{width:40px;height:40px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:14px;font-weight:700;flex-shrink:0;color:#fff;position:relative;}
#app .intel-pop-av::after{content:"";position:absolute;bottom:0;right:0;width:10px;height:10px;border-radius:50%;border:2px solid var(--nm-surface);background:var(--pulse-inactive);}
#app .intel-pop-av.pulse-available::after{background:var(--pulse-available);}
#app .intel-pop-av.pulse-oncall::after{background:var(--pulse-oncall);}
#app .intel-pop-av.pulse-leave::after{background:var(--pulse-leave);}
#app .intel-pop-av.pulse-ending::after{background:var(--pulse-ending);}
#app .intel-pop-name{font-weight:600;color:var(--nm-text1);line-height:1.3;}
#app .intel-pop-role{font-size:11px;color:var(--nm-text3);margin-top:2px;}
#app .intel-pop-status{display:inline-flex;align-items:center;gap:4px;font-size:11px;font-weight:600;padding:2px 7px;border-radius:4px;margin-top:4px;}
#app .intel-pop-body{padding:10px 16px 14px;display:flex;flex-direction:column;gap:6px;}
#app .intel-pop-row-icon{width:14px;flex-shrink:0;color:var(--nm-text3);margin-top:1px;}
#app .intel-pop-row-content{flex:1;min-width:0;}
#app .intel-pop-row-label{color:var(--nm-text3);font-size:11px;}
#app .intel-pop-row-val{color:var(--nm-text1);font-weight:500;}
#app .intel-pop-mini-bar{height:4px;background:var(--nm-surface3);border-radius:2px;overflow:hidden;margin-top:4px;}
#app .intel-pop-mini-fill{height:100%;border-radius:2px;}
#app .intel-pop-divider{height:1px;background:var(--nm-border);margin:2px -16px;}
#app .pulse-dot{width:8px;height:8px;border-radius:50%;flex-shrink:0;position:relative;}
#app .pulse-dot--available{background:var(--pulse-available);}
#app .pulse-dot--oncall{background:var(--pulse-oncall);}
#app .pulse-dot--leave{background:var(--pulse-leave);}
#app .pulse-dot--ending{background:var(--pulse-ending);}
#app .pulse-dot--inactive{background:var(--pulse-inactive);}
#app .pulse-dot--oncall::after{content:"";position:absolute;inset:-3px;border-radius:50%;border:2px solid var(--pulse-oncall);animation:pulsering 1.8s ease infinite;}
#app .staff-next-event{display:inline-flex;align-items:center;gap:4px;font-size:11px;padding:2px 7px;border-radius:4px;white-space:nowrap;font-weight:500;}
#app .staff-next-event--rotation{background:rgba(0,179,179,.08);color:var(--nm-teal);border:1px solid rgba(0,179,179,.18);}
#app .staff-next-event--oncall{background:rgba(245,158,11,.08);color:#d97706;border:1px solid rgba(245,158,11,.18);}
#app .staff-next-event--leave{background:rgba(239,68,68,.07);color:#dc2626;border:1px solid rgba(239,68,68,.15);}
#app .staff-next-event--ending{background:rgba(139,92,246,.07);color:#7c3aed;border:1px solid rgba(139,92,246,.15);}
#app .dept-pulse-bar{display:grid;grid-template-columns:repeat(4, 1fr);gap:10px;margin-bottom:18px;padding:16px 20px;background:var(--nm-surface);border:1px solid var(--nm-border);border-radius:12px;box-shadow:var(--shadow-card);}
#app .dpb-item{display:flex;flex-direction:column;align-items:center;text-align:center;gap:3px;position:relative;cursor:pointer;transition:opacity var(--transition-fast);}
#app .dpb-item:not(:last-child)::after{content:"";position:absolute;right:0;top:10%;bottom:10%;width:1px;background:var(--nm-border);}
#app .dpb-item:hover{opacity:.75;}
#app .dpb-num{font-family:"DM Mono", monospace;font-size:28px;font-weight:600;line-height:1;color:var(--nm-text1);}
#app .dpb-label{font-size:11px;font-weight:600;color:var(--nm-text3);text-transform:uppercase;letter-spacing:.05em;}
#app .dpb-sub{font-size:11px;color:var(--nm-text3);}
#app .dpb-num--teal{color:var(--nm-teal);}
