#app .dpb-num--red{color:#dc2626;}
#app .dpb-num--purple{color:#7c3aed;}
#app .unit-cockpit-grid{display:grid;grid-template-columns:repeat(auto-fill, minmax(320px, 1fr));gap:14px;}
#app .unit-cockpit-card:hover{box-shadow:var(--shadow-float);border-color:rgba(0,0,0,.12);transform:translateY(-1px);}
#app .unit-cockpit-card.ucc--full{border-top:3px solid #ef4444;}
#app .unit-cockpit-card.ucc--filling{border-top:3px solid #f59e0b;}
#app .unit-cockpit-card.ucc--open{border-top:3px solid var(--nm-teal);}
#app .unit-cockpit-card.ucc--empty{border-top:3px solid var(--nm-border);opacity:.8;}
#app .ucc-header{display:flex;align-items:flex-start;gap:12px;padding:16px 18px 12px;}
#app .ucc-icon{width:40px;height:40px;border-radius:10px;display:flex;align-items:center;justify-content:center;background:rgba(0,179,179,.07);border:1px solid rgba(0,179,179,.15);flex-shrink:0;font-size:16px;color:var(--nm-teal);}
#app .ucc-title-block{flex:1;min-width:0;}
#app .ucc-name{font-size:15px;font-weight:600;color:var(--nm-text1);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
#app .ucc-dept{font-size:12px;color:var(--nm-text3);margin-top:2px;}
#app .ucc-capacity-badge{font-family:"DM Mono", monospace;font-size:13px;font-weight:600;flex-shrink:0;padding:4px 10px;border-radius:20px;}
#app .ucc-capacity-badge.full{background:rgba(239,68,68,.08);color:#dc2626;border:1px solid rgba(239,68,68,.2);}
#app .ucc-capacity-badge.filling{background:rgba(245,158,11,.08);color:#d97706;border:1px solid rgba(245,158,11,.2);}
#app .ucc-capacity-badge.open{background:rgba(0,179,179,.08);color:var(--nm-teal);border:1px solid rgba(0,179,179,.2);}
#app .ucc-capacity-badge.empty{background:var(--nm-surface2);color:var(--nm-text3);border:1px solid var(--nm-border);}
#app .ucc-occ-track{padding:0 18px 14px;}
#app .ucc-occ-dots{display:flex;gap:6px;margin-bottom:8px;}
#app .ucc-occ-dot{flex:1;height:6px;border-radius:3px;background:var(--nm-surface3);transition:background var(--transition-fast);}
#app .ucc-occ-dot.filled{background:var(--nm-teal);}
#app .ucc-occ-dot.filled.warn{background:#f59e0b;}
#app .ucc-occ-dot.filled.full{background:#ef4444;}
#app .ucc-residents{padding:0 18px 10px;display:flex;flex-direction:column;gap:4px;}
#app .ucc-resident-row{display:flex;align-items:center;gap:8px;padding:5px 8px;border-radius:7px;background:var(--nm-surface2);font-size:12px;color:var(--nm-text2);}
#app .ucc-resident-av{width:22px;height:22px;border-radius:50%;background:rgba(0,179,179,.12);border:1px solid rgba(0,179,179,.25);color:var(--nm-teal);font-size:9px;font-weight:700;display:flex;align-items:center;justify-content:center;flex-shrink:0;}
#app .ucc-resident-name{flex:1;font-weight:500;}
#app .ucc-resident-days{font-family:"DM Mono", monospace;font-size:11px;color:var(--nm-text3);}
#app .ucc-empty-slot{display:flex;align-items:center;gap:8px;padding:5px 8px;border-radius:7px;border:1px dashed var(--nm-border);font-size:12px;color:var(--nm-text3);}
#app .ucc-next-opening{margin:4px 18px 14px;padding:7px 10px;border-radius:8px;background:rgba(0,179,179,.04);border:1px solid rgba(0,179,179,.12);display:flex;align-items:center;gap:6px;font-size:11px;color:var(--nm-teal);}
#app .ucc-timeline{border-top:1px solid var(--nm-border);padding:10px 18px;display:flex;gap:2px;align-items:flex-end;}
#app .ucc-tl-day{flex:1;border-radius:2px;cursor:default;min-height:4px;background:var(--nm-surface3);transition:height var(--transition-fast);}
