@keyframes spopRing{
        0%,100% { transform:scale(1); opacity:.8; }
        50%      { transform:scale(1.08); opacity:.4; }
      }
@keyframes pigPulse{
        0%,100% { box-shadow:0 0 0 0 rgba(124,58,237,.5); }
        50%      { box-shadow:0 0 0 5px rgba(124,58,237,0); }
      }
#staffPopover{position:fixed;z-index:9500;width:300px;background:var(--nm-surface);border:1px solid var(--nm-border2);border-radius:var(--r12);box-shadow:var(--shadow-pop);pointer-events:none;opacity:0;transform:translateY(6px) scale(.97);transition:opacity .18s var(--ease-out), transform .18s var(--ease-out);overflow:hidden;}
#staffPopover.visible{opacity:1;transform:translateY(0) scale(1);pointer-events:all;}
.spop-header{display:flex;align-items:center;gap:12px;padding:16px 16px 12px;background:var(--nm-navy);position:relative;overflow:hidden;}
.spop-header::before{content:"";position:absolute;inset:0;background:radial-gradient(ellipse at top right, rgba(0,179,179,.15) 0%, transparent 70%);pointer-events:none;}
.spop-avatar{width:44px;height:44px;border-radius:var(--r-pill);display:flex;align-items:center;justify-content:center;font-size:15px;font-weight:700;color:#fff;flex-shrink:0;position:relative;letter-spacing:-.02em;}
.spop-avatar::after{content:"";position:absolute;inset:-3px;border-radius:50%;border:2px solid var(--ps-active);opacity:.6;}
.spop-avatar.oncall::after{border-color:var(--ps-oncall);opacity:1;animation:spopRing 1.5s ease infinite;}
.spop-avatar.leave::after{border-color:var(--ps-leave);opacity:.8;}
.spop-avatar.inactive::after{border-color:var(--ps-inactive);opacity:.3;}
.spop-name{font-size:14px;font-weight:600;color:#fff;line-height:1.2;}
.spop-role{font-size:11px;color:rgba(255,255,255,.5);margin-top:2px;}
.spop-status{margin-left:auto;flex-shrink:0;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.07em;padding:3px 8px;border-radius:var(--r-pill);}
.spop-status.active{background:var(--nm-ok-bg);color:var(--nm-ok);}
.spop-status.oncall{background:rgba(124,58,237,.12);color:#7c3aed;}
.spop-status.leave{background:var(--nm-warn-bg);color:var(--nm-warn);}
.spop-status.inactive{background:rgba(0,0,0,.06);color:var(--nm-text3);}
.spop-body{padding:12px 16px;display:flex;flex-direction:column;gap:10px;}
.spop-section{display:flex;flex-direction:column;gap:5px;}
.spop-section-label{font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.07em;color:var(--nm-text3);display:flex;align-items:center;gap:5px;}
.spop-section-label svg{opacity:.6;}
.spop-row{display:flex;align-items:center;gap:8px;font-size:12px;color:var(--nm-text2);}
.spop-row-accent{color:var(--nm-text1);font-weight:500;}
.spop-badge{font-size:10px;font-weight:600;padding:2px 7px;border-radius:var(--r-pill);flex-shrink:0;}
.spop-badge.teal{background:var(--nm-ok-bg);color:var(--nm-ok);}
.spop-badge.purple{background:rgba(124,58,237,.08);color:#7c3aed;}
.spop-badge.amber{background:var(--nm-warn-bg);color:var(--nm-warn);}
.spop-badge.blue{background:var(--nm-info-bg);color:var(--nm-info);}
.spop-none{font-size:12px;color:var(--nm-text3);font-style:italic;}
.spop-divider{height:1px;background:var(--nm-border);margin:2px 0;}
.spop-actions{display:flex;gap:6px;padding:10px 16px 14px;border-top:1px solid var(--nm-border);}
.spop-action-btn{flex:1;padding:7px 10px;border-radius:var(--r8);border:1px solid var(--nm-border2);background:var(--nm-surface2);font-size:12px;font-weight:500;color:var(--nm-text1);cursor:pointer;text-align:center;transition:background .1s, border-color .1s;display:flex;align-items:center;justify-content:center;gap:5px;}
.spop-action-btn:hover{background:var(--nm-surface3);border-color:var(--nm-border2);}
.spop-action-btn.primary{background:var(--nm-teal);border-color:var(--nm-teal);color:#fff;}
.spop-action-btn.primary:hover{background:#009d9d;}
.pig-grid{display:grid;grid-template-columns:repeat(auto-fill, minmax(260px, 1fr));gap:14px;padding:20px 24px 24px;}
.pig-card{background:var(--nm-surface);border:1px solid var(--nm-border);border-radius:var(--r12);box-shadow:var(--shadow-1);cursor:pointer;transition:box-shadow .15s var(--ease-out), transform .15s var(--ease-out), border-color .15s;position:relative;overflow:hidden;display:flex;flex-direction:column;}
.pig-card:hover{box-shadow:var(--shadow-3);transform:translateY(-2px);border-color:var(--nm-border2);}
.pig-card.oncall{border-color:rgba(124,58,237,.25);}
.pig-card.oncall::before{content:"";position:absolute;top:0;left:0;right:0;height:2px;background:linear-gradient(90deg, #7c3aed, #a78bfa);}
.pig-card.leave{border-color:var(--nm-warn-border);opacity:.85;}
.pig-card.inactive{opacity:.55;}
.pig-body{display:flex;gap:14px;align-items:flex-start;padding:16px 16px 12px;}
.pig-avatar-wrap{position:relative;flex-shrink:0;}
.pig-avatar{width:48px;height:48px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:16px;font-weight:700;color:#fff;letter-spacing:-.02em;position:relative;z-index:1;}
.pig-avatar.attending{background:linear-gradient(135deg, #0e7490, #00b3b3);}
.pig-avatar.resident{background:linear-gradient(135deg, #1e40af, #3b82f6);}
.pig-avatar.leave{background:linear-gradient(135deg, #92400e, #d97706);}
.pig-avatar.inactive{background:var(--nm-surface4);color:var(--nm-text3);}
.pig-ring{position:absolute;top:-4px;left:-4px;width:56px;height:56px;transform:rotate(-90deg);pointer-events:none;}
.pig-ring-track{fill:none;stroke:var(--nm-surface3);stroke-width:2;}
.pig-ring-fill{fill:none;stroke-width:2.5;stroke-linecap:round;transition:stroke-dashoffset .6s var(--ease-out);}
.pig-ring-fill.active{stroke:var(--ps-active);}
.pig-ring-fill.oncall{stroke:var(--ps-oncall);}
.pig-ring-fill.leave{stroke:var(--ps-leave);}
.pig-ring-fill.inactive{stroke:var(--ps-inactive);stroke-dasharray:0 200;}
.pig-ring-fill.resident{stroke:var(--ps-resident);}
.pig-status-dot{position:absolute;bottom:1px;right:1px;z-index:2;width:11px;height:11px;border-radius:50%;border:2px solid var(--nm-surface);}
.pig-status-dot.active{background:var(--ps-active);}
.pig-status-dot.oncall{background:var(--ps-oncall);animation:pigPulse 1.8s infinite;}
.pig-status-dot.leave{background:var(--ps-leave);}
.pig-status-dot.inactive{background:var(--ps-inactive);}
.pig-info{flex:1;min-width:0;padding-top:2px;}
.pig-name{font-size:14px;font-weight:600;color:var(--nm-text1);line-height:1.2;letter-spacing:-.01em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.pig-role{font-size:11px;color:var(--nm-text3);margin-top:2px;}
.pig-spec{font-size:11px;color:var(--nm-text2);margin-top:1px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.pig-pill{display:inline-flex;align-items:center;gap:4px;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.05em;padding:2px 7px;border-radius:var(--r-pill);margin-top:6px;border:1px solid;}
.pig-pill.active{background:var(--nm-ok-bg);color:var(--nm-ok);border-color:var(--nm-ok-border);}
.pig-pill.oncall{background:rgba(124,58,237,.08);color:#7c3aed;border-color:rgba(124,58,237,.2);}
.pig-pill.leave{background:var(--nm-warn-bg);color:var(--nm-warn);border-color:var(--nm-warn-border);}
.pig-pill.inactive{background:rgba(0,0,0,.04);color:var(--nm-text3);border-color:var(--nm-border);}
.pig-footer{display:flex;align-items:center;gap:8px;padding:10px 16px;border-top:1px solid var(--nm-border);background:var(--nm-surface2);border-radius:0 0 var(--r12) var(--r12);min-height:36px;}
.pig-footer-item{display:flex;align-items:center;gap:4px;font-size:11px;color:var(--nm-text3);}
.pig-footer-item svg{color:var(--nm-text4);}
.pig-footer-item.active{color:var(--nm-text2);}
.pig-footer-item.highlight{color:var(--nm-teal);font-weight:600;}
.pig-footer-item.warn{color:var(--nm-warn);font-weight:600;}
.pig-footer-item.oncall-today{color:#7c3aed;font-weight:600;}
.pig-footer-dot{width:3px;height:3px;border-radius:50%;background:var(--nm-border2);flex-shrink:0;}
.pig-divider{grid-column:1/-1;display:flex;align-items:center;gap:12px;padding:8px 0 4px;}
.pig-divider-label{font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.1em;color:var(--nm-text3);white-space:nowrap;}
.pig-divider-line{flex:1;height:1px;background:var(--nm-border);}
.pig-divider-count{font-size:10px;color:var(--nm-text4);font-family:monospace;flex-shrink:0;}
.pig-empty{grid-column:1/-1;padding:48px;text-align:center;color:var(--nm-text3);}
@media (max-width:900px){.pig-grid{grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:10px;padding:14px;}}
@media (max-width:600px){.pig-grid{grid-template-columns:1fr 1fr;gap:8px;padding:10px;}
.pig-name{font-size:13px;}
.pig-footer{display:none;}}
.cov-cal{padding:20px 24px;display:flex;flex-direction:column;gap:16px;}
.cov-cal-nav{display:flex;align-items:center;gap:10px;}
.cov-cal-title{font-size:16px;font-weight:600;color:var(--nm-text1);letter-spacing:-.01em;}
.cov-cal-btn{width:30px;height:30px;border-radius:var(--r8);border:1px solid var(--nm-border2);background:var(--nm-surface);cursor:pointer;display:flex;align-items:center;justify-content:center;color:var(--nm-text2);transition:background .1s;}
.cov-cal-btn:hover{background:var(--nm-surface3);}
.cov-today-btn{font-size:11px;font-weight:600;padding:4px 10px;border-radius:var(--r-pill);background:var(--nm-ok-bg);color:var(--nm-ok);border:1px solid var(--nm-ok-border);cursor:pointer;}
.cov-grid{display:grid;grid-template-columns:repeat(7,1fr);gap:6px;}
