.cov-cell{border-radius:var(--r8);border:1px solid var(--nm-border);background:var(--nm-surface);min-height:72px;padding:6px;cursor:pointer;position:relative;transition:box-shadow .12s, border-color .12s;overflow:hidden;}
.cov-cell:hover{box-shadow:var(--shadow-2);border-color:var(--nm-border2);}
.cov-cell.today{border-color:var(--nm-teal) !important;box-shadow:0 0 0 1px var(--nm-teal);}
.cov-cell.other-month{opacity:.4;}
.cov-cell.has-gap{background:var(--cov-gap);border-color:var(--cov-gap-bd);}
.cov-cell.has-risk{background:var(--cov-partial);border-color:var(--cov-partial-bd);}
.cov-cell.full-cover{background:var(--cov-full);border-color:var(--cov-full-bd);}
.cov-cell-day{font-size:11px;font-weight:600;color:var(--nm-text2);line-height:1;}
.cov-cell.today .cov-cell-day{color:var(--nm-teal);font-weight:700;}
.cov-absence-strip{margin-top:4px;border-radius:3px;height:18px;display:flex;align-items:center;padding:0 5px;font-size:10px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;cursor:pointer;}
.cov-absence-strip.planned{background:rgba(0,179,179,.12);color:#00b3b3;}
.cov-absence-strip.sick{background:rgba(220,38,38,.1);color:#dc2626;}
.cov-absence-strip.conference{background:rgba(37,99,235,.08);color:#2563eb;}
.cov-absence-strip.personal{background:rgba(124,58,237,.08);color:#7c3aed;}
.cov-more{font-size:10px;color:var(--nm-text3);margin-top:2px;}
.cov-legend{display:flex;gap:12px;flex-wrap:wrap;}
.cov-legend-item{display:flex;align-items:center;gap:5px;font-size:11px;color:var(--nm-text2);}
.cov-legend-dot{width:10px;height:10px;border-radius:3px;flex-shrink:0;}
.tuo-grid{display:grid;grid-template-columns:repeat(auto-fill, minmax(320px,1fr));gap:16px;padding:20px 24px 24px;}
.tuo-card{background:var(--nm-surface);border:1px solid var(--nm-border);border-radius:var(--r12);box-shadow:var(--shadow-1);display:flex;flex-direction:column;overflow:hidden;cursor:pointer;transition:box-shadow .15s var(--ease-out), transform .15s var(--ease-out), border-color .15s;}
.tuo-card:hover{box-shadow:var(--shadow-3);transform:translateY(-2px);border-color:var(--nm-border2);}
