.tuo-card.inactive{opacity:.5;border-top:3px solid var(--nm-border2);}
.tuo-header{display:flex;align-items:flex-start;gap:14px;padding:16px 18px 12px;}
.tuo-ring-wrap{position:relative;flex-shrink:0;width:52px;height:52px;}
