.tuo-ring-bg{fill:none;stroke:var(--nm-surface3);stroke-width:4;}
.tuo-ring-fill{fill:none;stroke-width:4;stroke-linecap:round;transition:stroke-dashoffset .7s var(--ease-out);}
.tuo-ring-fill.full{stroke:var(--nm-teal);}
