.tuo-ring-fill.empty{stroke:var(--nm-danger);stroke-dasharray:0 200;}
.tuo-ring-num{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;font-size:16px;font-weight:700;color:var(--nm-text1);line-height:1;}
.tuo-ring-denom{font-size:9px;color:var(--nm-text3);font-weight:400;}
.tuo-title-block{flex:1;min-width:0;}
.tuo-name{font-size:15px;font-weight:600;color:var(--nm-text1);line-height:1.2;letter-spacing:-.01em;}
.tuo-code{font-size:10px;font-family:monospace;font-weight:600;color:var(--nm-text3);margin-top:3px;text-transform:uppercase;letter-spacing:.08em;}
.tuo-dept{font-size:11px;color:var(--nm-text2);margin-top:2px;}
.tuo-slots{display:flex;gap:5px;flex-wrap:wrap;padding:0 18px 14px;}
