.tuo-resident-row:hover{background:var(--nm-surface2);}
.tuo-res-av{width:28px;height:28px;border-radius:50%;background:linear-gradient(135deg, #1e40af, #3b82f6);display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:700;color:#fff;flex-shrink:0;}
