.tuo-res-days.ending{color:var(--nm-warn);font-weight:600;}
.tuo-empty-slot{padding:12px 18px;border-top:1px solid var(--nm-border);display:flex;align-items:center;gap:8px;font-size:12px;color:var(--nm-text3);}
