#app .ops-feed-section{flex:1;}
#app .ops-feed-header{display:flex;align-items:center;gap:10px;margin-bottom:10px;flex-wrap:wrap;}
#app .ops-feed-filters{display:flex;gap:3px;}
#app .ops-feed-filter{font-size:11px;font-weight:600;padding:3px 9px;border-radius:5px;cursor:pointer;background:transparent;border:1px solid transparent;color:var(--nm-text3);transition:all .12s;}
#app .ops-feed-filter:hover{background:var(--nm-surface2);color:var(--nm-text2);}
#app .ops-feed-filter.active{background:var(--nm-surface2);color:var(--nm-text1);border-color:var(--nm-border);}
#app .ops-feed{}
#app .ops-feed-item{display:flex;align-items:flex-start;gap:10px;padding:12px 0;border-bottom:1px solid var(--nm-border);}
#app .ops-feed-item:last-child{border-bottom:none;}
#app .ofi-bar{width:3px;border-radius:2px;align-self:stretch;flex-shrink:0;min-height:36px;}
#app .ofi-av{width:30px;height:30px;border-radius:50%;flex-shrink:0;background:var(--nm-surface2);border:1px solid var(--nm-border);color:var(--nm-text2);font-size:10px;font-weight:700;display:flex;align-items:center;justify-content:center;}
#app .ofi-body{flex:1;min-width:0;}
#app .ofi-header{display:flex;align-items:center;gap:7px;margin-bottom:3px;flex-wrap:wrap;}
#app .ofi-author{font-size:12px;font-weight:600;color:var(--nm-text1);}
#app .ofi-tag{font-size:9px;font-weight:800;text-transform:uppercase;letter-spacing:.06em;padding:2px 6px;border-radius:3px;}
#app .ofi-time{font-size:11px;color:var(--nm-text3);margin-left:auto;}
#app .ofi-title{font-size:13px;font-weight:600;color:var(--nm-text1);margin-bottom:2px;}
#app .ofi-text{font-size:13px;color:var(--nm-text2);line-height:1.5;}
#app .ofi-actions{display:flex;gap:5px;margin-top:6px;opacity:0;transition:opacity .12s;}
#app .ops-feed-item:hover .ofi-actions{opacity:1;}
#app .ofi-noted{display:flex;align-items:center;gap:3px;font-size:11px;padding:3px 8px;border-radius:5px;cursor:pointer;background:transparent;border:1px solid var(--nm-border);color:var(--nm-text3);transition:all .12s;}
#app .ofi-del{display:flex;align-items:center;gap:3px;font-size:11px;padding:3px 8px;border-radius:5px;cursor:pointer;background:transparent;border:1px solid var(--nm-border);color:var(--nm-text3);transition:all .12s;}
#app .ofi-noted:hover{border-color:var(--nm-teal);color:var(--nm-teal);}
#app .ofi-del:hover{border-color:rgba(239,68,68,.4);color:#ef4444;background:rgba(239,68,68,.04);}
#app .ops-feed-empty{display:flex;flex-direction:column;align-items:center;padding:60px 40px;gap:10px;color:var(--nm-text3);font-size:13px;text-align:center;}
#app .ops-feed-empty p{margin:0;}
#app .ops-view{flex:1 1 0;min-height:0;overflow:hidden;display:flex;flex-direction:column;}
#app .ops-layout{display:grid;grid-template-columns:320px 1fr;gap:0;flex:1 1 0;min-height:0;overflow:hidden;}
@media (max-width: 860px){#app .ops-layout{grid-template-columns:1fr;}}
@keyframes ops-glow{
  0%, 100% { box-shadow: 0 0 0 0 rgba(0,179,179,.4); }
  50%       { box-shadow: 0 0 0 6px rgba(0,179,179,.0); }
}
@keyframes ops-slide-down{
  from { opacity: 0; transform: translateY(-8px); }
  to   { opacity: 1; transform: translateY(0); }
}
@keyframes ops-glow-red{
  0%, 100% { box-shadow: 0 0 0 0 rgba(239,68,68,.4); }
  50%       { box-shadow: 0 0 0 5px rgba(239,68,68,.0); }
}
#app .ops-left{background:#0d1b2e;border-right:1px solid rgba(255,255,255,.06);display:flex;flex-direction:column;overflow-y:auto;padding:20px 18px 40px;min-height:0;}
#app .ops-left-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px;}
#app .ops-live-indicator{display:flex;align-items:center;gap:7px;font-size:10px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:rgba(255,255,255,.35);}
#app .ops-live-pulse{width:7px;height:7px;border-radius:50%;background:#00b3b3;box-shadow:0 0 0 0 rgba(0,179,179,.4);animation:ops-glow 2s ease-in-out infinite;}
#app .ops-briefing-btn{display:flex;align-items:center;gap:4px;font-size:10px;font-weight:600;padding:4px 10px;border-radius:6px;cursor:pointer;background:rgba(0,179,179,.12);border:1px solid rgba(0,179,179,.25);color:#00b3b3;transition:all .15s;}
#app .ops-briefing-btn:hover{background:rgba(0,179,179,.22);border-color:rgba(0,179,179,.5);}
#app .ops-briefing-form{background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.08);border-radius:12px;padding:14px;margin-bottom:14px;animation:ops-slide-down .2s ease;}
#app .obf-title{display:flex;align-items:center;gap:6px;font-size:11px;font-weight:600;color:rgba(255,255,255,.5);margin-bottom:12px;}
#app .obf-grid{display:flex;flex-direction:column;gap:8px;margin-bottom:12px;}
#app .obf-field{}
#app .obf-label{font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.08em;color:rgba(255,255,255,.3);margin-bottom:4px;}
#app .obf-inputs{display:flex;gap:5px;}
#app .obf-num{width:64px;font-size:13px;font-weight:600;padding:5px 8px;border-radius:6px;text-align:center;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.12);color:#fff;outline:none;transition:border-color .15s;}
#app .obf-num:focus{border-color:rgba(0,179,179,.5);}
#app .obf-sub{flex:1;font-size:12px;padding:5px 9px;border-radius:6px;background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.08);color:rgba(255,255,255,.5);outline:none;transition:border-color .15s;}
#app .obf-sub:focus{border-color:rgba(0,179,179,.3);color:rgba(255,255,255,.8);}
#app .obf-sub::placeholder{color:rgba(255,255,255,.2);}
#app .obf-num::placeholder{color:rgba(255,255,255,.2);}
#app .obf-footer{display:flex;align-items:center;justify-content:space-between;padding-top:10px;border-top:1px solid rgba(255,255,255,.07);}
#app .obf-note{font-size:10px;color:rgba(255,255,255,.2);}
#app .ops-tiles{display:grid;grid-template-columns:1fr 1fr;gap:8px;}
#app .ops-tile{border-radius:12px;padding:13px 14px;position:relative;overflow:hidden;border:1px solid transparent;transition:border-color .2s, background .2s;cursor:default;display:flex;align-items:stretch;gap:0;}
#app .ops-tile--lg{grid-column:span 2;}
#app .ops-tile--auto{}
#app .ops-tile--urgent{background:rgba(239,68,68,.08);border-color:rgba(239,68,68,.2);}
#app .ops-tile--warn{background:rgba(245,158,11,.07);border-color:rgba(245,158,11,.18);}
#app .ops-tile--ok{background:rgba(16,185,129,.07);border-color:rgba(16,185,129,.18);}
#app .ops-tile--dim{background:rgba(255,255,255,.03);border-color:rgba(255,255,255,.07);}
#app .ops-tile--skeleton{background:rgba(255,255,255,.03);border-color:rgba(255,255,255,.06);min-height:72px;}
#app .ot-accent{width:3px;border-radius:2px;flex-shrink:0;align-self:stretch;margin-right:11px;}
#app .ot-body{flex:1;min-width:0;}
#app .ot-icon{display:flex;align-items:center;flex-shrink:0;margin-left:8px;align-self:center;}
#app .ot-label{font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.08em;color:rgba(255,255,255,.35);margin-bottom:4px;}
#app .ot-val{font-family:"Instrument Serif", Georgia, serif;font-size:30px;font-style:italic;font-weight:400;line-height:1;color:rgba(255,255,255,.9);margin-bottom:3px;}
#app .ot-val--empty{color:rgba(255,255,255,.15);font-size:22px;}
#app .ot-sub{font-size:10px;color:rgba(255,255,255,.35);line-height:1.3;}
#app .ot-sub-urgent{color:rgba(239,68,68,.7);}
#app .ops-tiles-empty{display:flex;flex-direction:column;align-items:center;padding:32px 20px;gap:8px;text-align:center;color:rgba(255,255,255,.25);font-size:12px;}
#app .ops-tiles-empty p{margin:0;}
#app .ops-right{display:flex;flex-direction:column;overflow:hidden;min-height:0;background:var(--nm-surface);}
#app .ops-broadcasts{padding:14px 18px 0;flex-shrink:0;}
#app .ops-section-label{display:flex;align-items:center;gap:6px;font-size:9px;font-weight:800;letter-spacing:.1em;text-transform:uppercase;color:var(--nm-text3);margin-bottom:8px;}
#app .ops-live-dot{width:6px;height:6px;border-radius:50%;background:#ef4444;animation:ops-glow 1.4s ease-in-out infinite;box-shadow:0 0 0 0 rgba(239,68,68,.4);}
#app .ops-bc-card{display:flex;align-items:flex-start;gap:0;border-radius:9px;margin-bottom:7px;overflow:hidden;border:1px solid transparent;}
#app .ops-bc--red{background:rgba(239,68,68,.05);border-color:rgba(239,68,68,.18);}
#app .ops-bc--blue{background:var(--nm-surface2);border-color:var(--nm-border);}
#app .ops-bc-stripe{width:3px;flex-shrink:0;align-self:stretch;}
#app .ops-bc--red  .ops-bc-stripe{background:#ef4444;}
#app .ops-bc--blue .ops-bc-stripe{background:#3b82f6;}
#app .ops-bc-ico{width:32px;height:32px;display:flex;align-items:center;justify-content:center;flex-shrink:0;padding:9px;}
#app .ops-bc--red  .ops-bc-ico{color:#ef4444;}
#app .ops-bc--blue .ops-bc-ico{color:#3b82f6;}
#app .ops-bc-body{flex:1;min-width:0;padding:9px 6px 9px 0;}
#app .ops-bc-text{font-size:12px;font-weight:500;color:var(--nm-text1);line-height:1.4;margin-bottom:2px;}
#app .ops-bc-meta{font-size:10px;color:var(--nm-text3);}
#app .ops-bc-dismiss{font-size:14px;line-height:1;padding:8px 12px;align-self:stretch;cursor:pointer;background:transparent;border:none;color:var(--nm-text3);transition:color .12s;display:flex;align-items:flex-start;padding-top:10px;}
#app .ops-bc-dismiss:hover{color:var(--nm-text1);}
#app .ops-compose-zone{padding:10px 18px 12px;flex-shrink:0;border-bottom:1px solid var(--nm-border);}
#app .ops-compose-dormant{display:flex;align-items:center;gap:9px;background:var(--nm-surface2);border:1px solid var(--nm-border);border-radius:10px;padding:9px 12px;cursor:pointer;transition:border-color .15s, box-shadow .15s;}
#app .ops-compose-dormant:hover{border-color:var(--nm-teal);box-shadow:0 0 0 3px rgba(0,179,179,.06);}
#app .ocd-av{width:28px;height:28px;border-radius:50%;flex-shrink:0;background:rgba(0,179,179,.12);color:var(--nm-teal);font-size:9px;font-weight:800;display:flex;align-items:center;justify-content:center;}
#app .ocd-text{flex:1;font-size:12px;color:var(--nm-text3);}
#app .ocd-pills{display:flex;gap:3px;flex-shrink:0;}
#app .ocd-pill{font-size:9px;font-weight:700;padding:2px 7px;border-radius:3px;cursor:pointer;transition:filter .12s;letter-spacing:.02em;}
#app .ocd-pill--broadcast{background:rgba(239,68,68,.1);color:#dc2626;}
#app .ocd-pill--protocol{background:rgba(16,185,129,.1);color:#059669;}
#app .ocd-pill--note{background:rgba(148,163,184,.1);color:#64748b;}
#app .ocd-pill--kudos{background:rgba(14,165,233,.1);color:#0284c7;}
#app .ocd-pill:hover{filter:brightness(.88);}
#app .ops-compose-open{border:1px solid var(--nm-teal);border-radius:10px;overflow:hidden;box-shadow:0 0 0 3px rgba(0,179,179,.07);animation:ops-slide-down .18s ease;}
#app .oco-tabs{display:flex;align-items:center;background:var(--nm-surface2);border-bottom:1px solid var(--nm-border);padding:5px 8px;gap:2px;}
#app .oco-tab{font-size:10px;font-weight:700;padding:4px 10px;border-radius:5px;cursor:pointer;border:1px solid transparent;background:transparent;color:var(--nm-text3);transition:all .12s;}
#app .oco-tab--active.oco-tab--broadcast{background:rgba(239,68,68,.1);color:#dc2626;border-color:rgba(239,68,68,.2);}
#app .oco-tab--active.oco-tab--protocol{background:rgba(16,185,129,.1);color:#059669;border-color:rgba(16,185,129,.2);}
#app .oco-tab--active.oco-tab--announcement{background:var(--nm-surface);color:var(--nm-text1);border-color:var(--nm-border);}
#app .oco-tab--active.oco-tab--kudos{background:rgba(14,165,233,.1);color:#0284c7;border-color:rgba(14,165,233,.2);}
#app .oco-tab:not(.oco-tab--active):hover{background:var(--nm-surface);}
#app .oco-close{margin-left:auto;padding:4px 6px;border-radius:5px;cursor:pointer;background:transparent;border:none;color:var(--nm-text3);transition:color .12s;}
#app .oco-close:hover{color:var(--nm-text1);}
#app .oco-textarea{display:block;width:100%;resize:none;font-size:13px;line-height:1.6;padding:11px 14px;background:var(--nm-surface);border:none;outline:none;color:var(--nm-text1);font-family:inherit;}
#app .oco-footer{display:flex;align-items:center;justify-content:space-between;padding:8px 12px;background:var(--nm-surface2);border-top:1px solid var(--nm-border);}
#app .oco-expiry{display:flex;align-items:center;gap:5px;font-size:11px;color:var(--nm-text3);}
#app .oco-exp-sel{font-size:11px;background:transparent;border:1px solid var(--nm-border);border-radius:4px;padding:2px 6px;color:var(--nm-text2);cursor:pointer;}
#app .ops-feed-zone{flex:1 1 0;min-height:0;overflow:hidden;display:flex;flex-direction:column;padding:12px 18px 0;}
#app .ops-feed-header{display:flex;align-items:center;gap:8px;margin-bottom:8px;flex-shrink:0;}
#app .ops-feed-filters{display:flex;gap:2px;}
#app .ops-ff{font-size:10px;font-weight:600;padding:3px 9px;border-radius:5px;cursor:pointer;background:transparent;border:1px solid transparent;color:var(--nm-text3);transition:all .12s;}
#app .ops-ff:hover{background:var(--nm-surface2);color:var(--nm-text2);}
#app .ops-ff.active{background:var(--nm-surface2);color:var(--nm-text1);border-color:var(--nm-border);}
#app .ops-feed{flex:1 1 0;min-height:0;overflow-y:auto;padding-bottom:40px;}
#app .ops-fi{display:flex;align-items:flex-start;gap:8px;padding:10px 0;border-bottom:1px solid var(--nm-border);}
#app .ops-fi:last-child{border-bottom:none;}
#app .ops-fi-bar{width:3px;border-radius:2px;flex-shrink:0;align-self:stretch;min-height:30px;}
#app .ops-fi-av{width:28px;height:28px;border-radius:50%;flex-shrink:0;background:var(--nm-surface2);border:1px solid var(--nm-border);font-size:9px;font-weight:700;color:var(--nm-text2);display:flex;align-items:center;justify-content:center;}
#app .ops-fi-body{flex:1;min-width:0;}
#app .ops-fi-row{display:flex;align-items:center;gap:6px;margin-bottom:2px;flex-wrap:wrap;}
#app .ops-fi-author{font-size:12px;font-weight:600;color:var(--nm-text1);}
#app .ops-fi-tag{font-size:8.5px;font-weight:800;text-transform:uppercase;letter-spacing:.06em;padding:1px 6px;border-radius:3px;}
#app .ops-fi-time{font-size:10px;color:var(--nm-text3);margin-left:auto;}
#app .ops-fi-title{font-size:12px;font-weight:600;color:var(--nm-text1);margin-bottom:2px;}
#app .ops-fi-text{font-size:12px;color:var(--nm-text2);line-height:1.5;}
#app .ops-fi-actions{display:flex;gap:4px;margin-top:5px;opacity:0;transition:opacity .12s;}
#app .ops-fi:hover .ops-fi-actions{opacity:1;}
#app .ops-fi-btn{display:flex;align-items:center;gap:3px;font-size:10px;padding:2px 8px;border-radius:4px;cursor:pointer;background:transparent;border:1px solid var(--nm-border);color:var(--nm-text3);transition:all .12s;}
#app .ops-fi-btn:hover{border-color:var(--nm-teal);color:var(--nm-teal);}
#app .ops-fi-btn--del:hover{border-color:rgba(239,68,68,.4);color:#dc2626;background:rgba(239,68,68,.04);}
#app .ops-feed-empty{display:flex;flex-direction:column;align-items:center;padding:48px 20px;gap:8px;color:var(--nm-text3);font-size:12px;text-align:center;}
#app .ops-feed-empty p{margin:0;}
#app .timeline-chart{display:flex;align-items:flex-end;gap:3px;height:100px;padding:0 0 4px;overflow-x:auto;scrollbar-width:none;}
#app .timeline-chart::-webkit-scrollbar{display:none;}
#app .timeline-bar-col{display:flex;flex-direction:column;align-items:center;gap:3px;flex-shrink:0;min-width:28px;}
#app .timeline-bar-wrap{display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:88px;position:relative;}
#app .timeline-bar-fill{width:18px;border-radius:4px 4px 2px 2px;background:var(--nm-teal);opacity:.7;transition:opacity .15s, transform .15s;min-height:4px;}
#app .timeline-bar-col:hover .timeline-bar-fill{opacity:1;transform:scaleX(1.1);}
#app .timeline-bar-val{position:absolute;top:-16px;font-size:9px;font-weight:700;color:var(--nm-teal);opacity:0;transition:opacity .15s;}
#app .timeline-bar-col:hover .timeline-bar-val{opacity:1;}
#app .timeline-bar-label{font-size:9px;color:rgba(255,255,255,.3);white-space:nowrap;writing-mode:vertical-rl;transform:rotate(180deg);height:24px;text-align:right;}
#app .rha-chart-badge{font-size:9px;font-weight:700;padding:2px 7px;border-radius:3px;background:rgba(0,179,179,.12);color:var(--nm-teal);margin-left:8px;}
#app .rha-lines-table{width:100%;}
#app .rha-lt-header{display:grid;grid-template-columns:40px 1fr 160px 70px 70px 80px;gap:8px;padding:6px 12px;font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.07em;color:rgba(255,255,255,.25);border-bottom:1px solid rgba(255,255,255,.07);}
#app .rha-lt-row{display:grid;grid-template-columns:40px 1fr 160px 70px 70px 80px;gap:8px;padding:9px 12px;align-items:center;border-bottom:1px solid rgba(255,255,255,.05);font-size:12px;color:rgba(255,255,255,.7);transition:background .1s;}
#app .rha-lt-row:hover{background:rgba(255,255,255,.03);}
#app .rha-lt-name{font-weight:500;color:rgba(255,255,255,.88);}
#app .rha-lt-coord{font-size:11px;color:rgba(255,255,255,.4);}
#app .nrd-footer{display:flex;align-items:center;gap:8px;padding:10px 20px;border-top:1px solid rgba(255,255,255,.08);background:rgba(0,0,0,.15);flex-shrink:0;}
#app .nrd-footer-spacer{flex:1;}
#app .nrd-footer .btn{font-size:12px;padding:5px 14px;}
#app .nrd-footer .btn-success{background:var(--nm-teal);border-color:var(--nm-teal);color:#fff;}
#app .nrd-footer .btn-success:hover{filter:brightness(1.1);}
#app .abs-calendar-grid{display:grid;grid-template-columns:repeat(7, 1fr);gap:2px;}
#app .abs-cal-day{aspect-ratio:1;border-radius:6px;display:flex;align-items:center;justify-content:center;font-size:11px;position:relative;cursor:default;transition:transform .1s;}
#app .abs-cal-day:hover{transform:scale(1.15);z-index:2;}
#app .abs-cal-day--absent{background:rgba(239,68,68,.18);color:#fca5a5;}
#app .abs-cal-day--partial{background:rgba(245,158,11,.15);color:#fcd34d;}
#app .abs-coverage-strip{display:flex;gap:1px;margin-top:8px;height:6px;border-radius:3px;overflow:hidden;}
#app .abs-cov-seg{flex:1;transition:opacity .15s;}
#app .abs-cov-seg:hover{opacity:.7;}
#app .acs-full{background:rgba(16,185,129,.6);}
#app .acs-partial{background:rgba(245,158,11,.5);}
#app .acs-critical{background:rgba(239,68,68,.6);}
#app .acs-empty{background:rgba(255,255,255,.08);}
#app .rp-staff-card{display:flex;align-items:center;gap:10px;padding:10px 14px;border-radius:8px;background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.07);margin-bottom:6px;transition:background .12s;}
#app .rp-staff-card:hover{background:rgba(255,255,255,.07);}
#app .rp-staff-av{width:32px;height:32px;border-radius:50%;flex-shrink:0;background:rgba(0,179,179,.15);color:var(--nm-teal);font-size:11px;font-weight:700;display:flex;align-items:center;justify-content:center;}
#app .rp-staff-name{font-size:13px;font-weight:500;color:rgba(255,255,255,.85);}
#app .rp-staff-role{font-size:10px;color:rgba(255,255,255,.35);margin-top:1px;}
#app .inno-card-foot{padding:9px 14px 10px;border-top:1px solid var(--nm-border);display:flex;align-items:center;justify-content:space-between;background:var(--nm-surface2);}
#app .inno-card-pi{display:flex;align-items:center;gap:6px;font-size:11px;color:var(--nm-text2);}
#app .inno-card-pi-av{width:20px;height:20px;border-radius:50%;background:rgba(0,179,179,.1);color:var(--nm-teal);font-size:8px;font-weight:700;display:flex;align-items:center;justify-content:center;flex-shrink:0;}
#app .inno-card-actions{display:flex;gap:3px;opacity:0;transition:opacity .12s;}
#app .inno-card:hover .inno-card-actions{opacity:1;}
#app .stype-chip-badge{background:rgba(0,179,179,.1);color:var(--nm-teal);font-size:11px;font-weight:800;}
#app .stype-chip:hover .stype-chip-badge{background:rgba(0,179,179,.2);}
