.co-analytics-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:20px;}
.co-analytics-card{background:var(--nm-surface);border:1px solid var(--nm-border);border-radius:10px;padding:14px 16px;}
.co-analytics-title{font-size:10px;font-weight:800;text-transform:uppercase;letter-spacing:.08em;color:var(--nm-text3);margin-bottom:10px;}
.co-bar-row{display:flex;align-items:center;gap:8px;margin-bottom:6px;font-size:11px;}
.co-bar-label{width:120px;flex-shrink:0;color:var(--nm-text2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.co-bar-track{flex:1;height:6px;background:var(--nm-border);border-radius:3px;overflow:hidden;}
.co-bar-fill{height:100%;border-radius:3px;transition:width .3s;}
.co-bar-count{width:24px;text-align:right;color:var(--nm-text3);font-variant-numeric:tabular-nums;}
.co-dist-row{display:flex;align-items:center;gap:8px;padding:6px 0;border-bottom:1px solid var(--nm-border);font-size:11px;}
.co-dist-row:last-child{border-bottom:none;}
.co-dist-name{flex:1;font-weight:500;color:var(--nm-text1);}
.co-dist-nums{display:flex;gap:12px;}
.co-dist-num{text-align:right;font-variant-numeric:tabular-nums;color:var(--nm-text2);}
.co-dist-badge{font-size:9px;font-weight:700;padding:1px 5px;border-radius:3px;}
.co-dist-badge--high{background:rgba(239,68,68,.1);color:#dc2626;}
.co-dist-badge--low{background:rgba(16,185,129,.1);color:#059669;}
.oc-area-badge{display:inline-flex;align-items:center;font-size:9px;font-weight:700;letter-spacing:.04em;padding:2px 7px;border-radius:4px;border:1px solid;margin-top:4px;}
.rot-orb--float{background:rgba(139,92,246,.15);border-color:rgba(139,92,246,.3);color:#a78bfa;}
.rot-orb--float:hover{background:rgba(139,92,246,.25);}
#app .rot-compact .rot-orb{position:relative;cursor:pointer;}
#app .rot-orb-tooltip{display:none;position:absolute;bottom:calc(100% + 8px);left:50%;transform:translateX(-50%);min-width:180px;max-width:240px;background:#0f172a;border:1px solid rgba(255,255,255,.1);border-radius:10px;padding:10px 12px;box-shadow:0 8px 24px rgba(0,0,0,.35);z-index:9999;pointer-events:none;white-space:nowrap;}
#app .rot-orb-tooltip::after{content:"";position:absolute;top:100%;left:50%;transform:translateX(-50%);border:6px solid transparent;border-top-color:#0f172a;}
#app .rot-orb:hover .rot-orb-tooltip{display:block;}
#app .rot-tt-unit{font-size:11px;font-weight:700;color:rgba(255,255,255,.9);text-transform:uppercase;letter-spacing:.07em;margin-bottom:6px;}
#app .rot-tt-dates{display:flex;align-items:center;gap:5px;font-size:11px;color:rgba(255,255,255,.65);margin-bottom:3px;overflow:hidden;text-overflow:ellipsis;}
#app .rot-tt-dates svg{flex-shrink:0;opacity:.7;}
#app .rot-tt-tag{display:inline-flex;align-items:center;gap:4px;font-size:10px;font-weight:600;padding:2px 7px;border-radius:4px;border:1px solid;margin-top:6px;}
#app .rot-tt-tag--active{background:rgba(16,185,129,.15);color:#34d399;border-color:rgba(16,185,129,.25);}
#app .rot-tt-tag--scheduled{background:rgba(59,130,246,.15);color:#60a5fa;border-color:rgba(59,130,246,.25);}
#app .rot-tt-tag--done{background:rgba(255,255,255,.06);color:rgba(255,255,255,.4);border-color:rgba(255,255,255,.1);}
.nm-modal{background:var(--nm-surface);border-radius:14px;border:1px solid var(--nm-border);overflow:hidden;box-shadow:0 8px 40px rgba(0,0,0,.14);display:flex;flex-direction:column;max-height:90vh;}
.nm-modal-head{display:flex;align-items:center;justify-content:space-between;padding:14px 18px;border-bottom:1px solid var(--nm-border);background:var(--nm-surface2);flex-shrink:0;}
.nm-modal-title{display:flex;align-items:center;gap:8px;font-size:14px;font-weight:600;color:var(--nm-text1);}
.nm-modal-body{padding:18px 18px 10px;display:flex;flex-direction:column;gap:14px;overflow-y:auto;flex:1 1 0;min-height:0;-webkit-overflow-scrolling:touch;}
.nm-modal-foot{display:flex;justify-content:flex-end;gap:8px;padding:12px 18px 16px;border-top:1px solid var(--nm-border);background:var(--nm-surface2);flex-shrink:0;}
.bulk-oc-modal{display:grid;grid-template-columns:230px 1fr;width:min(820px, calc(100vw - 32px));max-height:calc(100vh - 48px);border-radius:14px;overflow:hidden;background:#fff;border:1px solid var(--nm-border);box-shadow:0 12px 48px rgba(0,0,0,.18);}
.boc-left{background:#07111f;display:flex;flex-direction:column;overflow:hidden;}
.boc-left-head{padding:16px 14px 12px;font-size:10px;font-weight:800;text-transform:uppercase;letter-spacing:.1em;color:rgba(255,255,255,.25);border-bottom:1px solid rgba(255,255,255,.06);flex-shrink:0;}
.boc-steps{flex-shrink:0;padding:6px 0;border-bottom:1px solid rgba(255,255,255,.06);}
.boc-step{display:flex;align-items:flex-start;gap:10px;padding:9px 14px;cursor:default;border-left:3px solid transparent;transition:background .12s;}
.boc-step.active{background:rgba(0,179,179,.08);border-left-color:#00b3b3;}
.boc-step.done{opacity:.55;cursor:pointer;}
.boc-step.done:hover{opacity:.75;}
.boc-step-num{width:20px;height:20px;border-radius:50%;background:rgba(255,255,255,.07);color:rgba(255,255,255,.35);font-size:9px;font-weight:800;display:flex;align-items:center;justify-content:center;flex-shrink:0;}
.boc-step.active .boc-step-num{background:#00b3b3;color:#fff;}
.boc-step.done   .boc-step-num{background:rgba(16,185,129,.3);color:#34d399;}
.boc-step-lbl{font-size:12px;font-weight:600;color:rgba(255,255,255,.55);}
.boc-step.active .boc-step-lbl{color:#fff;}
.boc-step-hint{font-size:10px;color:rgba(255,255,255,.25);margin-top:1px;}
.boc-queue{flex:1 1 0;overflow-y:auto;padding:10px 14px;scrollbar-width:none;}
.boc-queue::-webkit-scrollbar{display:none;}
.boc-queue-title{font-size:9px;font-weight:800;text-transform:uppercase;letter-spacing:.08em;color:rgba(255,255,255,.2);margin-bottom:8px;}
.boc-queue-empty{font-size:10px;color:rgba(255,255,255,.18);line-height:1.5;padding:4px 0;}
.boc-queue-item{display:flex;align-items:center;gap:7px;padding:6px 8px;border-radius:7px;background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.06);margin-bottom:4px;}
.boc-q-av{width:26px;height:26px;border-radius:50%;background:linear-gradient(135deg,#00b3b3,#4a9ee8);display:flex;align-items:center;justify-content:center;font-size:8px;font-weight:800;color:#fff;flex-shrink:0;}
.boc-q-body{flex:1;min-width:0;}
.boc-q-name{font-size:10px;font-weight:600;color:rgba(255,255,255,.75);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.boc-q-meta{font-size:9px;color:rgba(255,255,255,.28);}
.boc-q-count{font-size:9px;font-weight:800;padding:1px 6px;border-radius:4px;background:rgba(0,179,179,.15);color:#00b3b3;flex-shrink:0;}
.boc-q-warn{font-size:9px;font-weight:700;padding:1px 5px;border-radius:4px;background:rgba(239,68,68,.15);color:#fca5a5;flex-shrink:0;}
.boc-q-del{width:18px;height:18px;border-radius:4px;background:transparent;border:none;color:rgba(255,255,255,.2);cursor:pointer;font-size:13px;display:flex;align-items:center;justify-content:center;flex-shrink:0;transition:color .1s;}
.boc-q-del:hover{color:#fca5a5;}
.boc-left-foot{padding:10px 14px 14px;border-top:1px solid rgba(255,255,255,.06);display:flex;flex-direction:column;gap:5px;flex-shrink:0;}
.boc-btn-save{width:100%;padding:8px;border-radius:8px;border:none;background:rgba(255,255,255,.08);color:rgba(255,255,255,.25);font-size:12px;font-weight:700;cursor:not-allowed;transition:all .15s;}
.boc-btn-save.ready{background:#00b3b3;color:#fff;cursor:pointer;}
.boc-btn-save.ready:hover{background:#009999;}
.boc-btn-add{width:100%;padding:6px;border-radius:6px;background:transparent;border:1px solid rgba(255,255,255,.1);color:rgba(255,255,255,.35);font-size:11px;font-weight:600;cursor:pointer;transition:all .12s;}
.boc-btn-add:hover{border-color:rgba(255,255,255,.2);color:rgba(255,255,255,.6);}
.boc-right{background:var(--nm-surface2, #f8f7f5);display:flex;flex-direction:column;position:relative;overflow:hidden;}
.boc-close{position:absolute;top:12px;right:14px;width:28px;height:28px;border-radius:7px;background:var(--nm-surface, #fff);border:1px solid var(--nm-border);color:var(--nm-text3);cursor:pointer;display:flex;align-items:center;justify-content:center;transition:all .12s;z-index:2;}
.boc-close:hover{background:var(--nm-surface);color:var(--nm-text1);border-color:var(--nm-text3);}
.boc-panel{flex:1 1 0;overflow-y:auto;padding:18px 20px 0;display:flex;flex-direction:column;gap:12px;}
.boc-panel-title{font-size:14px;font-weight:600;color:var(--nm-text1);padding-right:40px;display:flex;align-items:center;gap:8px;flex-wrap:wrap;}
.boc-clone-bar{display:flex;align-items:center;gap:8px;padding:8px 12px;border-radius:8px;background:rgba(0,179,179,.05);border:1px solid rgba(0,179,179,.15);font-size:11px;color:var(--nm-teal, #00b3b3);}
.boc-cal-nav{display:flex;align-items:center;gap:8px;}
.boc-cal-btn{width:28px;height:28px;border-radius:7px;border:1px solid var(--nm-border);background:var(--nm-surface, #fff);color:var(--nm-text3);cursor:pointer;font-size:14px;display:flex;align-items:center;justify-content:center;transition:all .1s;}
.boc-cal-btn:hover{background:var(--nm-surface2);color:var(--nm-text1);}
.boc-cal-label{font-size:13px;font-weight:600;color:var(--nm-text1);}
.boc-cal-dow{display:grid;grid-template-columns:repeat(7, 1fr);gap:3px;margin-bottom:2px;}
.boc-cal-dow span{text-align:center;font-size:9px;font-weight:700;text-transform:uppercase;color:var(--nm-text3);padding:3px 0;}
.boc-cal-grid{display:grid;grid-template-columns:repeat(7, 1fr);gap:3px;}
.boc-cal-day{aspect-ratio:1;border-radius:7px;display:flex;align-items:center;justify-content:center;font-size:12px;cursor:pointer;background:var(--nm-surface, #fff);border:1px solid var(--nm-border);color:var(--nm-text2);transition:all .1s;position:relative;user-select:none;}
.boc-cal-day:hover:not(.boc-day--other){border-color:var(--nm-teal, #00b3b3);color:var(--nm-teal, #00b3b3);}
.boc-day--other{opacity:.25;pointer-events:none;}
.boc-day--today{font-weight:700;}
.boc-day--selected{background:var(--nm-teal, #00b3b3);border-color:var(--nm-teal, #00b3b3);color:#fff;font-weight:600;}
.boc-day--absent:not(.boc-day--selected){background:rgba(239,68,68,.06);border-color:rgba(239,68,68,.25);color:#dc2626;}
.boc-day--conflict{background:#ef4444;border-color:#ef4444;color:#fff;font-weight:600;}
.boc-day-warn{position:absolute;top:-4px;right:-4px;width:13px;height:13px;border-radius:50%;background:#fbbf24;color:#1a1a1a;font-size:8px;font-weight:900;display:flex;align-items:center;justify-content:center;border:1.5px solid #fff;}
.boc-cal-legend{display:flex;gap:12px;flex-wrap:wrap;}
.boc-leg{display:flex;align-items:center;gap:5px;font-size:10px;color:var(--nm-text3);}
.boc-leg-dot{width:10px;height:10px;border-radius:3px;flex-shrink:0;}
.boc-conflict-banner{display:flex;align-items:flex-start;gap:9px;padding:10px 12px;border-radius:8px;background:rgba(245,158,11,.07);border:1px solid rgba(245,158,11,.25);font-size:11px;color:#92400e;line-height:1.5;}
.boc-area-chip{font-size:10px;font-weight:700;padding:2px 8px;border-radius:5px;}
.boc-review-list{flex:1 1 0;overflow-y:auto;display:flex;flex-direction:column;gap:0;border:1px solid var(--nm-border);border-radius:9px;overflow:hidden;background:var(--nm-surface, #fff);}
.boc-review-block-head{display:flex;align-items:center;gap:8px;padding:8px 12px;background:var(--nm-surface2, #f8f7f5);border-bottom:1px solid var(--nm-border);font-size:12px;font-weight:600;color:var(--nm-text1);}
.boc-review-role{font-size:9px;font-weight:700;padding:2px 6px;border-radius:4px;background:rgba(0,179,179,.1);color:var(--nm-teal, #00b3b3);}
.boc-review-row{display:flex;align-items:center;gap:10px;padding:7px 12px;border-bottom:1px solid var(--nm-border, #f0ede8);font-size:11px;}
.boc-review-row:last-child{border-bottom:none;}
.boc-review-row--conflict{background:rgba(245,158,11,.04);}
.boc-review-date{font-weight:500;color:var(--nm-text1);min-width:110px;}
.boc-review-time{color:var(--nm-text3);min-width:80px;}
.boc-review-warn{font-size:9px;font-weight:700;color:#d97706;margin-left:auto;}
.boc-review-del{width:20px;height:20px;border-radius:4px;background:transparent;border:none;color:var(--nm-text3);cursor:pointer;font-size:14px;display:flex;align-items:center;justify-content:center;transition:color .1s;margin-left:auto;}
.boc-review-del:hover{color:#ef4444;}
.boc-footer{display:flex;align-items:center;justify-content:space-between;padding:12px 0 16px;border-top:1px solid var(--nm-border);margin-top:auto;flex-shrink:0;}
.db-gap-panel{margin-top:20px;border:1px solid rgba(245,158,11,.2);border-radius:12px;background:rgba(245,158,11,.03);overflow:hidden;}
.db-gap-head{display:flex;align-items:center;justify-content:space-between;padding:10px 16px;background:rgba(245,158,11,.06);border-bottom:1px solid rgba(245,158,11,.12);}
.db-gap-title{display:flex;align-items:center;gap:6px;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.07em;color:#92400e;}
.db-gap-title svg{color:#d97706;flex-shrink:0;}
.db-gap-grid{display:flex;flex-wrap:wrap;gap:8px;padding:12px 16px;}
.db-gap-item{display:flex;align-items:center;gap:8px;padding:8px 12px;border-radius:8px;background:var(--nm-surface);border:1px solid var(--nm-border);cursor:pointer;transition:border-color .12s, box-shadow .12s;min-width:160px;max-width:220px;flex:1;}
.db-gap-item:hover{border-color:var(--nm-teal);box-shadow:0 0 0 2px rgba(0,179,179,.06);}
.db-gap-av{width:32px;height:32px;border-radius:8px;background:rgba(245,158,11,.12);color:#92400e;font-size:13px;font-weight:700;display:flex;align-items:center;justify-content:center;flex-shrink:0;}
.db-gap-info{flex:1;min-width:0;}
.db-gap-name{font-size:12px;font-weight:600;color:var(--nm-text1);display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.db-gap-year{font-size:10px;color:var(--nm-text3);font-family:monospace;}
.db-gap-pills{display:flex;flex-wrap:wrap;gap:3px;margin-top:3px;}
.db-gap-pill{font-size:9px;font-weight:700;padding:1px 5px;border-radius:3px;background:rgba(245,158,11,.1);color:#d97706;border:1px solid rgba(245,158,11,.2);}
.db-oc-area-group{margin-bottom:5px;}
.db-oc-area-label{display:flex;align-items:center;gap:5px;font-size:9px;font-weight:800;text-transform:uppercase;letter-spacing:.07em;padding:2px 0 4px 8px;border-left:2px solid;}
.db-oc-area-dot{width:6px;height:6px;border-radius:50%;flex-shrink:0;}
.db-oc-area-slots{padding-left:8px;border-left:2px solid rgba(0,0,0,.06);margin-left:2px;display:flex;flex-direction:column;gap:2px;}
.db-oc-flags{display:flex;align-items:center;gap:4px;margin-left:auto;flex-shrink:0;}
.db-oc-flag{font-size:9px;font-weight:700;padding:2px 6px;border-radius:4px;white-space:nowrap;letter-spacing:.02em;}
.db-oc-flag--absence{background:rgba(245,158,11,.12);color:#d97706;border:1px solid rgba(245,158,11,.25);}
.db-oc-flag--fatigue{background:rgba(99,102,241,.1);color:#6366f1;border:1px solid rgba(99,102,241,.2);}
.db-oc-flag--nobackup{background:transparent;color:var(--nm-text3);border:1px solid var(--nm-border);}
.db-oc-flag--backup{background:rgba(0,179,179,.08);color:var(--nm-teal);border:1px solid rgba(0,179,179,.18);}
.db-oc-av--absence{background:rgba(245,158,11,.15) !important;border:2px solid rgba(245,158,11,.4) !important;color:#d97706 !important;}
.db-oc-slot-row--warn-absence{background:rgba(245,158,11,.04) !important;}
.dev-banner{flex-shrink:0;background:linear-gradient(90deg,#07111f 0%,#0f2d54 50%,#07111f 100%);border-bottom:1px solid rgba(0,179,179,.25);width:100%;}
.dev-banner-inner{display:flex;align-items:center;gap:10px;padding:7px 20px;overflow:hidden;}
.dev-banner-dot{width:6px;height:6px;border-radius:50%;background:#00b3b3;flex-shrink:0;box-shadow:0 0 6px rgba(0,179,179,.6);animation:devPulse 2.4s ease-in-out infinite;}
.dev-banner-label{font-family:"DM Mono",monospace;font-size:10px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:#00b3b3;background:rgba(0,179,179,.12);border:1px solid rgba(0,179,179,.3);border-radius:4px;padding:2px 7px;flex-shrink:0;}
.dev-banner-text{font-size:12px;color:rgba(255,255,255,.52);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;flex:1;}
.dev-banner-cta{font-size:11.5px;font-weight:500;color:rgba(0,179,179,.8);text-decoration:none;white-space:nowrap;flex-shrink:0;transition:color .14s;}
.dev-banner-cta:hover{color:#00b3b3;}
@media (max-width:600px){.dev-banner-text{display:none;}}
@media (prefers-reduced-motion:reduce){.dev-banner-dot{animation:none;}}
