html body #app .grounded-orb-badge { position:absolute !important; top:-5px !important; right:-5px !important; height:20px !important; min-width:20px !important; padding:0 6px !important; border-radius:999px !important; display:flex !important; align-items:center !important; justify-content:center !important; background:#db5b4f !important; color:#fff !important; font:700 10px/1 'DM Sans',sans-serif !important; border:2px solid #fff !important; box-shadow:0 4px 12px rgba(219,91,79,.28) !important; }

