/* ========================================================================
   V23 — RESEARCH LIBRARY / INSTITUTIONAL EDITORIAL INTELLIGENCE
   Different object types get different reading modes; CRUD becomes peripheral.
   ======================================================================== */
#app .news-v23{
  --rl-ink:#102b45;--rl-ink-2:#27445e;--rl-muted:#6f8497;--rl-faint:#9aa9b6;
  --rl-line:#dfe7e9;--rl-paper:#fff;--rl-wash:#f7faf9;--rl-teal:#0a8f91;
  --rl-teal-soft:#e7f6f4;--rl-navy:#0b2a46;--rl-warm:#f8f6f0;
  background:#fbfcfc!important;color:var(--rl-ink)!important;min-height:100%;
}
#app .news-v23-masthead{display:flex;align-items:flex-end;justify-content:space-between;gap:40px;padding:38px 52px 28px;background:#fff;border-bottom:1px solid var(--rl-line)}
#app .news-v23-ident{max-width:860px}
#app .news-v23-ident .news-editorial-kicker{font-size:11px;font-weight:800;letter-spacing:.18em;text-transform:uppercase;color:var(--rl-teal);margin-bottom:8px}
#app .news-v23-ident h2{font-family:"Instrument Serif",Georgia,serif;font-size:42px;line-height:1.02;font-weight:400;letter-spacing:-.035em;color:var(--rl-ink);margin:0 0 8px}
#app .news-v23-ident p{font-size:14px;line-height:1.55;color:var(--rl-muted);margin:0;max-width:720px}
#app .news-v23-mast-actions{display:flex;align-items:center;gap:28px;flex-shrink:0}
#app .news-v23-record-count{display:flex;align-items:baseline;gap:7px;color:var(--rl-ink)}
#app .news-v23-record-count strong{font-family:"Instrument Serif",Georgia,serif;font-size:34px;font-weight:400;line-height:1}
#app .news-v23-record-count span{text-transform:uppercase;font-size:9px;letter-spacing:.14em;font-weight:800;color:var(--rl-muted)}
#app .news-v23-new{appearance:none;border:0;background:transparent;color:var(--rl-ink);display:flex;align-items:center;gap:9px;font:700 13px/1 var(--font-ui);cursor:pointer;padding:5px 0}
#app .news-v23-new-orb{width:34px;height:34px;border-radius:50%;display:grid;place-items:center;background:var(--rl-ink);color:#fff;font-size:17px;transition:transform .18s,background .18s}
#app .news-v23-new:hover .news-v23-new-orb{transform:rotate(90deg);background:var(--rl-teal)}

#app .news-v23-index{min-height:48px;padding:0 52px;display:flex;align-items:center;gap:22px;background:#fff;border-bottom:1px solid var(--rl-line);font-size:12px;color:var(--rl-muted)}
#app .news-v23-index>span:not(:first-child){position:relative;padding-left:20px}
#app .news-v23-index>span:not(:first-child)::before{content:"";position:absolute;left:0;top:50%;width:1px;height:16px;background:var(--rl-line);transform:translateY(-50%)}
#app .news-v23-index strong{color:var(--rl-ink);font-weight:800}
#app .news-v23-index-label{text-transform:uppercase;letter-spacing:.14em;font-size:9px;font-weight:800;color:#8596a5}
#app .news-v23-index-public{color:#567b75!important}

#app .news-v23-tabs{display:flex;align-items:center;gap:32px;padding:0 52px;height:58px;background:#fff;border-bottom:1px solid var(--rl-line)}
#app .news-v23-tabs button{appearance:none;border:0;background:none;height:58px;padding:0;position:relative;font:700 13px/1 var(--font-ui);color:#6f8295;cursor:pointer}
#app .news-v23-tabs button span{font-size:10px;margin-left:4px;color:#9aa9b7}
#app .news-v23-tabs button::after{content:"";position:absolute;left:0;right:0;bottom:-1px;height:2px;background:transparent}
#app .news-v23-tabs button.is-active{color:var(--rl-ink)}
#app .news-v23-tabs button.is-active::after{background:var(--rl-teal)}

#app .news-v23-tools{display:grid;grid-template-columns:minmax(340px,1fr) 150px 150px auto;align-items:end;gap:24px;padding:18px 52px;background:#fff;border-bottom:1px solid var(--rl-line)}
#app .news-v23-search{display:flex;align-items:center;gap:10px;height:42px;border-bottom:1px solid #cfdadd;color:#8092a2;transition:border-color .18s}
#app .news-v23-search:focus-within{border-color:var(--rl-teal)}
#app .news-v23-search input{width:100%;height:100%;border:0!important;outline:0!important;box-shadow:none!important;background:transparent!important;font:500 14px/1 var(--font-ui);color:var(--rl-ink);padding:0!important}
#app .news-v23-search input::placeholder{color:#93a2b0}
#app .news-v23-select{display:flex;flex-direction:column;gap:2px;border-bottom:1px solid #cfdadd;padding-bottom:5px}
#app .news-v23-select>span{font-size:8px;text-transform:uppercase;letter-spacing:.14em;font-weight:800;color:#9aa8b5}
#app .news-v23-select select{border:0!important;outline:0!important;box-shadow:none!important;background:transparent!important;padding:4px 0 0!important;height:28px;font:600 12px/1 var(--font-ui);color:var(--rl-ink)}
#app .news-v23-shown{font-size:10px;font-weight:700;color:#98a7b4;padding-bottom:8px;white-space:nowrap}

#app .news-list--v23{padding:26px 52px 72px;background:#f8faf9}
#app .news-body--v23{max-width:1420px;margin:0 auto;display:grid;gap:0}
#app .news-body--all{grid-template-columns:repeat(12,minmax(0,1fr));gap:18px}
#app .news-body--all>.knowledge-card--publication{grid-column:1/-1}
#app .news-body--all>.knowledge-card--article{grid-column:span 6}
#app .news-body--all>.knowledge-card--highlight{grid-column:span 7}
#app .news-body--all>.knowledge-card--update{grid-column:span 5}
#app .news-body--article,#app .news-body--highlight{grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}
#app .news-body--update{max-width:980px;gap:0}
#app .news-body--publication{max-width:1320px;gap:0}

#app .knowledge-card--v23{position:relative;overflow:visible!important;background:#fff;color:var(--rl-ink);cursor:pointer;transition:background .16s,transform .16s,box-shadow .16s;border:0!important;box-shadow:none!important}
#app .knowledge-v23-topline{display:flex;align-items:center;justify-content:space-between;gap:16px}
#app .knowledge-v23-type{display:flex;align-items:center;gap:8px;text-transform:uppercase;letter-spacing:.15em;font-size:8.5px;font-weight:800;color:#547087}
#app .knowledge-v23-dot{width:5px;height:5px;border-radius:50%;background:#6d87a2}
#app .knowledge-card--article .knowledge-v23-dot{background:#06a19f}
#app .knowledge-card--highlight .knowledge-v23-dot{background:#d3a647}
#app .knowledge-card--update .knowledge-v23-dot{background:#557b9e}
#app .knowledge-v23-featured{color:#a27525;border-left:1px solid #e7d9b7;padding-left:8px}
#app .knowledge-v23-state{display:flex;align-items:center;gap:7px}
#app .knowledge-v23-status{font-size:9px;font-weight:800;text-transform:uppercase;letter-spacing:.1em;color:#7e8f9e}
#app .knowledge-v23-status.is-draft{color:#a07118}
#app .knowledge-v23-status.is-archived{color:#7d8790}
#app .knowledge-v23-visibility{appearance:none;border:0;background:none!important;padding:0;display:flex;align-items:center;gap:6px;font:600 10px/1 var(--font-ui);color:#6d8295;cursor:pointer;box-shadow:none!important}
#app .knowledge-v23-visibility:hover{color:var(--rl-teal)}
#app .knowledge-v23-info{width:15px;height:15px;border:1px solid #c9d6da;border-radius:50%;display:grid;place-items:center;font:700 9px/1 Georgia,serif;color:#7e919e;cursor:help}

/* Scholarly records become bibliography, not cards */
#app .news-body--publication>.knowledge-card--publication,
#app .news-body--all>.knowledge-card--publication{border-bottom:1px solid var(--rl-line)!important;padding:24px 8px 20px;background:transparent!important;border-radius:0!important}
#app .news-body--publication>.knowledge-card--publication:first-child{border-top:1px solid var(--rl-line)!important}
#app .knowledge-card--publication:hover{background:rgba(255,255,255,.7)!important;transform:none!important}
#app .knowledge-card--publication .knowledge-v23-topline{margin-bottom:13px}
#app .publication-v23{display:grid;grid-template-columns:92px minmax(0,1fr);gap:28px;align-items:start}
#app .publication-v23-year{font-family:"Instrument Serif",Georgia,serif;font-size:30px;color:#71869a;line-height:1;padding-top:3px}
#app .publication-v23-main{max-width:980px}
#app .publication-v23-main h3{font:700 16px/1.36 var(--font-ui);color:var(--rl-ink);margin:0 0 3px;letter-spacing:-.01em}
#app .publication-v23-journal{font-family:"Instrument Serif",Georgia,serif;font-style:italic;font-size:16px;color:#607b91;margin:2px 0 8px}
#app .publication-v23-authors{font-size:12px;line-height:1.55;color:#708398;margin-bottom:8px}
#app .publication-v23-doi{font:600 10.5px/1.4 "DM Mono",monospace;color:#176c7c;text-decoration:none}
#app .publication-v23-doi:hover{text-decoration:underline;text-underline-offset:3px}
#app .publication-v23-missing{font-size:10.5px;color:#9ba8b2}
#app .knowledge-card--publication .knowledge-v23-footer{padding-left:120px}

/* Articles: magazine previews */
#app .knowledge-card--article{padding:20px 20px 0;border-radius:24px!important;border:1px solid #e1e8e9!important;box-shadow:0 10px 30px rgba(22,46,65,.045)!important;overflow:hidden!important}
#app .knowledge-card--article:hover{transform:translateY(-2px);box-shadow:0 16px 38px rgba(22,46,65,.075)!important}
#app .knowledge-card--article .knowledge-v23-topline{margin-bottom:18px}
#app .article-v23{display:grid;grid-template-columns:1fr;gap:16px;min-height:175px}
#app .article-v23.has-image{grid-template-columns:minmax(0,1fr) 160px}
#app .article-v23-copy h3{font:700 17px/1.32 var(--font-ui);margin:0 0 8px;color:var(--rl-ink);letter-spacing:-.015em}
#app .article-v23-copy p{font-size:12.5px;line-height:1.6;color:#71849a;margin:0;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
#app .article-v23-media{margin:0;align-self:start;aspect-ratio:1/1;border-radius:18px;overflow:hidden;background:#edf2f2}
#app .article-v23-media img{width:100%;height:100%;object-fit:cover;display:block;transition:transform .35s ease}
#app .knowledge-card--article:hover .article-v23-media img{transform:scale(1.025)}
#app .knowledge-v23-open{display:inline-block;margin-top:14px;font-size:11px;font-weight:700;color:var(--rl-teal)}

/* Highlights: visual-first */
#app .knowledge-card--highlight{padding:0;border-radius:26px!important;overflow:hidden!important;background:#0d2e49!important;color:#fff;min-height:300px}
#app .knowledge-card--highlight .knowledge-v23-topline{position:absolute;z-index:2;top:18px;left:20px;right:20px;color:#fff}
#app .knowledge-card--highlight .knowledge-v23-type,#app .knowledge-card--highlight .knowledge-v23-visibility{color:rgba(255,255,255,.82)!important}
#app .highlight-v23{height:100%;min-height:300px;display:grid;grid-template-columns:1fr}
#app .highlight-v23.has-image{position:relative}
