#app .nrd--highlight .nrd-v23-pager{border-color:rgba(255,255,255,.10)}
#app .nrd--highlight .nrd-v23-pager button{color:#fff}

/* circular CRUD rail — no rectangular button farm */
#app .nrd-v23-rail{position:absolute;right:18px;top:92px;display:flex;flex-direction:column;gap:9px;z-index:6}
#app .nrd-v23-tool{position:relative;width:42px;height:42px;border-radius:50%!important;border:1px solid #dbe4e6!important;background:rgba(255,255,255,.93)!important;color:#61798d;display:grid;place-items:center;cursor:pointer;box-shadow:0 8px 22px rgba(18,45,65,.08)!important;transition:transform .15s,background .15s,color .15s}
#app .nrd-v23-tool:hover{transform:translateX(-2px);background:#102b45!important;color:#fff;border-color:#102b45!important}
