#app .nrd-v23-tool>span{position:absolute;right:50px;top:50%;transform:translateY(-50%) translateX(4px);opacity:0;pointer-events:none;background:#102b45;color:#fff;padding:6px 9px;border-radius:7px;font-size:9.5px;font-weight:700;white-space:nowrap;transition:.14s}
#app .nrd-v23-tool:hover>span{opacity:1;transform:translateY(-50%) translateX(0)}
