  #app .rv36-filter-count{width:100%;margin-left:0;text-align:right;padding-top:2px}
  #app .rv31-nav,#app .rv31-line-context,#app .rv32-context-bar{backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px)}
}


