/* --------------------------------------------------------------------------
   Research Library quick preview — centred, deliberate focus.
   The previous source-relative popover preserved spatial continuity, but on
   wide screens it could push the preview into peripheral vision.
   -------------------------------------------------------------------------- */
html body #app .news-v24-peek-layer{
  background:rgba(8,29,43,.14) !important;
  backdrop-filter:blur(2px) !important;
  -webkit-backdrop-filter:blur(2px) !important;
}
html body #app .news-v24-peek.news-v38-focus-peek{
  left:50% !important;
  top:50% !important;
  transform:translate(-50%,-50%) !important;
  width:min(560px,calc(100vw - 48px)) !important;
  max-height:min(72vh,640px) !important;
  border-radius:18px !important;
  border:1px solid rgba(24,61,81,.13) !important;
  box-shadow:0 34px 100px rgba(7,26,39,.24) !important;
  animation:newsV38PeekIn .18s cubic-bezier(.22,.61,.36,1) !important;
}
@keyframes newsV38PeekIn{
  from{opacity:0;transform:translate(-50%,calc(-50% + 8px)) scale(.985)}
  to{opacity:1;transform:translate(-50%,-50%) scale(1)}
}
