html body #app .askbar-turn--clarification .askbar-a-card{padding:0 !important;border:0 !important;background:transparent !important;box-shadow:none !important;border-radius:0 !important;}
html body #app .askbar-turn--fact .askbar-a-card::before,
html body #app .askbar-turn--clarification .askbar-a-card::before{display:none !important;}
html body #app .askbar-turn--fact .askbar-a-tx{max-width:640px !important;padding:1px 2px !important;font-size:14px !important;line-height:1.56 !important;color:#20384d !important;-webkit-text-fill-color:#20384d !important;overflow-wrap:break-word !important;}
html body #app .askbar-turn--fact .askbar-trust{max-width:640px !important;}
html body #app .askbar-turn--fact .askbar-followups{max-width:640px !important;}

/* Context changes are events, not assistant essays. */
html body #app .askbar-turn--context-event{margin:2px 0 14px !important;}
html body #app .askbar-turn--context-event .askbar-a-card{max-width:640px !important;padding:11px 13px !important;border:1px solid #dbe7e7 !important;border-radius:12px !important;background:#f5faf9 !important;box-shadow:none !important;}
html body #app .askbar-turn--context-event .askbar-a-card::before{display:none !important;}
html body #app .askbar-context-event{display:grid !important;grid-template-columns:auto 1fr !important;grid-template-areas:'eyebrow title' 'eyebrow meta' !important;column-gap:10px !important;align-items:center !important;}
html body #app .askbar-context-event>span{grid-area:eyebrow !important;padding:5px 7px !important;border-radius:7px !important;background:#e2f2f0 !important;color:#147b79 !important;font:700 9.5px/1.1 'DM Sans',sans-serif !important;white-space:nowrap !important;}
html body #app .askbar-context-event>strong{grid-area:title !important;color:#183b4e !important;font:700 12px/1.3 'DM Sans',sans-serif !important;}
html body #app .askbar-context-event>small{grid-area:meta !important;margin-top:2px !important;color:#748891 !important;font:500 10px/1.3 'DM Sans',sans-serif !important;}

/* Structured review should be a compact audit strip, never a second card. */
html body #app .gr45-review-control{margin:7px 0 4px !important;padding:7px 0 !important;border:0 !important;border-top:1px solid #e9eff0 !important;border-bottom:1px solid #e9eff0 !important;background:transparent !important;box-shadow:none !important;}
html body #app .gr45-review-control>div>span{font-size:9px !important;letter-spacing:.06em !important;color:#83929a !important;}
html body #app .gr45-review-control>div>strong{font-size:11px !important;color:#365669 !important;}
html body #app .gr45-review-control>div>small{font-size:9.5px !important;color:#8a989f !important;}
html body #app .gr45-review-control>button{padding:5px 8px !important;border-radius:8px !important;font-size:10px !important;background:#fff !important;box-shadow:none !important;}

/* Person cards stay useful without recreating the Staff module in chat. */
html body #app .askbar-profile{border-radius:14px !important;box-shadow:none !important;overflow:hidden !important;}
html body #app .askbar-profile-top{padding:12px 14px !important;}
html body #app .askbar-profile-glance{display:flex !important;align-items:center !important;gap:7px 12px !important;flex-wrap:wrap !important;padding:8px 14px !important;border-top:1px solid #e8eeee !important;background:#fbfdfd !important;}
html body #app .askbar-profile-glance span{color:#627783 !important;font:600 10px/1.35 'DM Sans',sans-serif !important;}
html body #app .askbar-profile-flags{padding:8px 14px 0 !important;}
html body #app .askbar-profile-sec{padding:11px 14px !important;}
html body #app .askbar-profile-link{padding:8px 10px !important;}
html body #app .askbar-profile-link-l{font-size:10.5px !important;}
html body #app .askbar-profile-complete{padding:9px 14px !important;}

/* The latest-answer affordance is an unobtrusive navigation cue. */
html body #app .gr45-latest{position:sticky !important;top:8px !important;z-index:8 !important;align-self:flex-end !important;margin:0 4px -2px auto !important;padding:6px 9px !important;border:1px solid #ccdada !important;border-radius:999px !important;background:rgba(255,255,255,.94) !important;color:#476a70 !important;font:700 10px/1 'DM Sans',sans-serif !important;box-shadow:0 4px 14px rgba(10,36,48,.08) !important;}
html body #app .gr45-latest:hover{background:#f4f9f8 !important;color:#0c7d7e !important;}

/* Evidence stays readable but visually subordinate to the answer. */
html body #app .askbar-trust{margin-top:8px !important;padding-top:7px !important;}
html body #app .askbar-trust-state{font-size:9.5px !important;}
html body #app .askbar-trust-src{font-size:9.5px !important;}
html body #app .askbar-followups{margin-top:7px !important;}

@media(max-width:760px){
  html body #app .grounded-head-copy{flex:1 1 auto !important;}
  html body #app .askbar-head-s{max-width:110px !important;}
  html body #app .grounded-head-tools .askbar-newchat span,
  html body #app .grounded-head-tools .askbar-history-btn span:not(.askbar-tool-count),
  html body #app .grounded-head-tools .askbar-teach-btn span{display:none !important;}
  html body #app .askbar-context-event{grid-template-columns:1fr !important;grid-template-areas:'eyebrow' 'title' 'meta' !important;row-gap:4px !important;}
  html body #app .askbar-context-event>span{justify-self:start !important;}
}

/* ========================================================================== 
   V46.14 · INTERACTION REVEAL / FOCUS CONTINUITY
   New content must appear where the user's interaction leads. These margins
   keep programmatic reveal targets clear of sticky bars without adding motion
   or visual noise to the calm neumDesk interface.
   ========================================================================== */
#app .askbar-q-bub[data-grounded-question],
#app .askbar-a-bub[data-grounded-turn]{scroll-margin-top:14px;}
#app .research-hub .rv31-page,
#app .research-hub .rv32-page,
#app .research-hub .rv33-intelligence{scroll-margin-top:56px;}
#app .nrd-drawer:focus:not(:focus-visible),
#app .profile-drawer:focus:not(:focus-visible),
#app .rot-detail-sheet:focus:not(:focus-visible){outline:none;}

