}
html body #app .leave14-hero-meta{display:flex !important;gap:8px !important;flex-wrap:wrap !important;margin-top:18px !important;}
html body #app .leave14-hero-meta span{
  display:flex !important;gap:7px !important;align-items:center !important;
  padding:7px 9px !important;border-radius:8px !important;
  border:1px solid rgba(255,255,255,.14) !important;background:rgba(255,255,255,.055) !important;
  color:rgba(239,248,249,.76) !important;font-size:11px !important;
}
html body #app .leave14-hero-meta b{font-weight:700 !important;color:#fff !important;}
html body #app .leave14-hero-meta .is-attention{border-color:rgba(250,190,76,.42) !important;background:rgba(250,190,76,.08) !important;color:#ffe1a1 !important;}
html body #app .leave14-primary{
