  background:#13b9ba !important;color:#062d3a !important;
  padding:10px 13px !important;font:700 12px/1 var(--font-ui,"DM Sans",sans-serif) !important;
  cursor:pointer !important;white-space:nowrap !important;
}
html body #app .leave14-primary:hover{background:#35c7c6 !important;}

html body #app .leave14-state-rail{
  margin:0 20px !important;display:grid !important;grid-template-columns:repeat(4,minmax(0,1fr)) !important;
  background:#fff !important;border:1px solid #dfe7e7 !important;border-top:0 !important;
  border-radius:0 0 14px 14px !important;overflow:hidden !important;
}
html body #app .leave14-state{padding:13px 16px 14px !important;border-right:1px solid #e8eeee !important;min-width:0 !important;}
html body #app .leave14-state:last-child{border-right:0 !important;}
html body #app .leave14-state span{display:block !important;color:#70838b !important;font:700 9.5px/1.2 var(--font-ui,"DM Sans",sans-serif) !important;letter-spacing:.09em !important;text-transform:uppercase !important;}
html body #app .leave14-state strong{display:block !important;margin-top:5px !important;color:#123949 !important;font:500 25px/1 var(--font-display,"Instrument Serif",Georgia,serif) !important;}
html body #app .leave14-state small{display:block !important;margin-top:5px !important;color:#7d8d92 !important;font-size:10.5px !important;line-height:1.3 !important;white-space:normal !important;}
html body #app .leave14-state--attention{background:#fffaf0 !important;}
html body #app .leave14-state--attention strong{color:#b36b00 !important;}

html body #app .leave14-workspace{
  margin:16px 20px 28px !important;border:1px solid #dfe7e7 !important;border-radius:14px !important;
  box-shadow:none !important;background:#fff !important;overflow:hidden !important;
}
html body #app .leave14-toolbar{
  display:flex !important;align-items:center !important;justify-content:space-between !important;gap:14px !important;
