html body #app .leave14-toolbar-label{display:flex !important;align-items:baseline !important;gap:9px !important;min-width:0 !important;}
html body #app .leave14-toolbar-label span{color:#274b59 !important;font:700 11px/1.2 var(--font-ui,"DM Sans",sans-serif) !important;letter-spacing:.06em !important;text-transform:uppercase !important;}
html body #app .leave14-toolbar-label small{color:#829096 !important;font-size:10.5px !important;}
html body #app .leave14-toolbar .view-mode-toggle{display:flex !important;gap:3px !important;padding:3px !important;border:1px solid #dbe4e4 !important;background:#f3f7f7 !important;border-radius:9px !important;}
html body #app .leave14-toolbar .vmt-btn{
  display:inline-flex !important;align-items:center !important;gap:5px !important;padding:6px 8px !important;border:0 !important;border-radius:7px !important;
  background:transparent !important;color:#677b84 !important;font:700 10.5px/1 var(--font-ui,"DM Sans",sans-serif) !important;cursor:pointer !important;
