}

/* ======================================================================
   V46.14 · STAFF PHASE 1 — DIRECTORY / OPERATIONAL TABLE
   Scoped to .staff46-* so the existing registration lifecycle and profile
   surfaces remain untouched until their dedicated phases.
   ====================================================================== */
.staff46-page{padding:0 28px 34px;display:flex;flex-direction:column;gap:14px;min-width:0;}
.staff46-context-strip{display:flex;align-items:center;gap:8px;min-height:36px;padding:7px 10px;border:1px solid var(--border);border-radius:9px;background:var(--surface);font-size:12px;color:var(--text-2);}
.staff46-context-k{font-size:10px;font-weight:700;letter-spacing:.09em;text-transform:uppercase;color:var(--text-3);margin-right:2px;}
.staff46-context-strip button{border:1px solid var(--border);background:var(--surface-2);color:var(--text-2);border-radius:999px;padding:5px 9px;font:inherit;cursor:pointer;}
.staff46-context-strip button:hover{border-color:var(--teal);color:var(--teal);}
.staff46-context-strip .staff46-context-clear{margin-left:auto;border-color:transparent;background:transparent;color:var(--text-3);}

.staff46-hero{display:grid;grid-template-columns:minmax(0,1fr) auto;grid-template-areas:"copy actions" "pulse pulse";gap:22px;padding:26px 28px 0;border-radius:18px 18px 0 0;background:linear-gradient(122deg,#0c3552 0%,#0c3b56 62%,#0b5b63 100%);color:#fff;overflow:hidden;position:relative;}
.staff46-hero:after{content:"";position:absolute;right:-90px;top:-130px;width:360px;height:360px;border:1px solid rgba(255,255,255,.07);border-radius:50%;pointer-events:none;}
.staff46-hero-copy{grid-area:copy;position:relative;z-index:1;}
.staff46-eyebrow{display:block;margin-bottom:8px;font-size:11px;font-weight:700;letter-spacing:.13em;text-transform:uppercase;color:#73d9dc;}
.staff46-hero h2{margin:0;font-size:34px;line-height:1.05;letter-spacing:-.045em;font-weight:650;color:#fff;}
.staff46-hero p{margin:8px 0 0;max-width:630px;font-size:13.5px;line-height:1.5;color:rgba(255,255,255,.74);}
.staff46-hero-actions{grid-area:actions;display:flex;align-items:flex-start;gap:9px;position:relative;z-index:1;}
.staff46-btn{height:42px;border-radius:9px;padding:0 14px;border:1px solid rgba(255,255,255,.16);display:inline-flex;align-items:center;gap:8px;font-size:12.5px;font-weight:650;cursor:pointer;white-space:nowrap;}
.staff46-btn--secondary{background:rgba(7,35,54,.26);color:#fff;}
.staff46-btn--secondary:hover{background:rgba(255,255,255,.1);}
.staff46-btn--primary{background:#13b8bc;color:#062d3d;border-color:#13b8bc;}
.staff46-btn--primary:hover{filter:brightness(1.05);}
.staff46-pulse{grid-area:pulse;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));margin:4px -28px 0;border-top:1px solid rgba(255,255,255,.12);position:relative;z-index:1;}
.staff46-pulse button{display:grid;grid-template-columns:auto 1fr;grid-template-rows:auto auto;column-gap:11px;text-align:left;padding:14px 22px;border:0;border-right:1px solid rgba(255,255,255,.11);background:rgba(3,28,44,.18);color:#fff;cursor:pointer;min-width:0;}
.staff46-pulse button:last-child{border-right:0;}
.staff46-pulse button:hover{background:rgba(255,255,255,.06);}
.staff46-pulse strong{grid-row:1/3;align-self:center;font-size:24px;font-family:var(--font-data);font-weight:500;color:#ecffff;}
.staff46-pulse span{font-size:11px;font-weight:700;letter-spacing:.035em;color:rgba(255,255,255,.9);}
.staff46-pulse small{font-size:10px;color:rgba(255,255,255,.52);}
.staff46-pulse .needs-attention strong{color:#f6c66b;}

.staff46-toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 12px;border:1px solid var(--border);border-top:0;background:var(--surface);}
.staff46-view-switch{display:inline-flex;align-items:center;gap:3px;padding:3px;border:1px solid var(--border);border-radius:9px;background:var(--surface-2);}
.staff46-view-switch button{height:32px;border:0;border-radius:6px;padding:0 10px;background:transparent;color:var(--text-3);display:inline-flex;align-items:center;gap:7px;font-size:12px;font-weight:600;cursor:pointer;}
.staff46-view-switch button:hover{color:var(--text-1);}
.staff46-view-switch button.active{background:var(--surface);color:var(--teal);box-shadow:0 1px 3px rgba(15,34,50,.1);}
.staff46-toolbar-actions{display:flex;align-items:center;gap:8px;}
.staff46-export-menu{position:relative;}
.staff46-export-menu summary{list-style:none;height:34px;display:inline-flex;align-items:center;gap:7px;padding:0 10px;border:1px solid var(--border);border-radius:8px;background:var(--surface);color:var(--text-2);font-size:12px;font-weight:600;cursor:pointer;}
.staff46-export-menu summary::-webkit-details-marker{display:none;}
.staff46-export-menu[open] summary{border-color:var(--teal);color:var(--teal);}
.staff46-export-menu>div{position:absolute;right:0;top:39px;z-index:40;width:150px;padding:5px;border:1px solid var(--border);border-radius:9px;background:var(--surface);box-shadow:0 12px 26px rgba(15,34,50,.14);}
.staff46-export-menu>div button{width:100%;padding:8px 9px;border:0;border-radius:6px;background:transparent;text-align:left;color:var(--text-2);font-size:12px;cursor:pointer;}
.staff46-export-menu>div button:hover{background:var(--surface-2);color:var(--text-1);}

.staff46-filters{display:grid;grid-template-columns:minmax(280px,1fr) minmax(150px,.32fr) minmax(170px,.35fr) minmax(150px,.3fr) auto auto;gap:8px;align-items:center;padding:11px 12px;border:1px solid var(--border);border-radius:11px;background:var(--surface);}
.staff46-search{height:40px;display:flex;align-items:center;gap:9px;padding:0 12px;border:1px solid var(--border);border-radius:8px;background:var(--surface);color:var(--text-3);}
.staff46-search:focus-within{border-color:var(--teal);box-shadow:0 0 0 2px rgba(0,169,172,.08);}
.staff46-search input{min-width:0;width:100%;border:0;outline:0;background:transparent;color:var(--text-1);font-size:13px;}
.staff46-filters select{height:40px;border:1px solid var(--border);border-radius:8px;background:var(--surface);color:var(--text-2);padding:0 30px 0 10px;font-size:12.5px;}
.staff46-clear{height:36px;border:0;background:transparent;color:var(--text-3);font-size:12px;font-weight:600;cursor:pointer;}
.staff46-clear:hover{color:var(--danger);}
.staff46-result-count{font-size:11px;color:var(--text-3);white-space:nowrap;}

.staff46-table-wrap{border:1px solid var(--border);border-radius:12px;background:var(--surface);overflow:visible;}
.staff46-table{width:100%;border-collapse:separate;border-spacing:0;table-layout:fixed;}
.staff46-table thead th{height:42px;padding:0 16px;border-bottom:1px solid var(--border);background:#f8faf9;color:var(--text-3);font-size:10.5px;font-weight:750;text-transform:uppercase;letter-spacing:.07em;text-align:left;}
.staff46-table thead th:nth-child(1){width:31%;}.staff46-table thead th:nth-child(2){width:20%;}.staff46-table thead th:nth-child(3){width:31%;}.staff46-table thead th:nth-child(4){width:13%;}.staff46-table thead th:nth-child(5){width:5%;}
.staff46-table tbody tr{cursor:pointer;outline:0;transition:background .13s ease;}
.staff46-table tbody tr:hover,.staff46-table tbody tr:focus{background:#f7fbfb;}
.staff46-table tbody td{padding:11px 16px;border-bottom:1px solid #e8efed;vertical-align:middle;color:var(--text-2);font-size:12.5px;}
.staff46-table tbody tr:last-child td{border-bottom:0;}
.staff46-person{display:flex;align-items:center;gap:11px;min-width:0;}
.staff46-person>div:last-child{min-width:0;}
.staff46-person strong{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--text-1);font-size:13.5px;font-weight:650;}
.staff46-person small,.staff46-role-stack small{display:block;margin-top:2px;color:var(--text-3);font-size:11px;line-height:1.3;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.staff46-role-stack strong{display:block;color:var(--text-1);font-size:12.5px;font-weight:650;}
.staff46-context-list{display:flex;flex-direction:column;gap:5px;}
.staff46-context-item{display:grid;grid-template-columns:6px minmax(0,1fr);gap:8px;align-items:start;}
.staff46-context-item>span{width:6px;height:6px;margin-top:5px;border-radius:50%;background:#9aa9b4;}
.staff46-context-item.is-oncall>span{background:#e8a126;}.staff46-context-item.is-leave>span{background:#d97706;}.staff46-context-item.is-rotation>span{background:#168aa0;}.staff46-context-item.is-next>span,.staff46-context-item.is-ending>span{background:#72869a;}
