}
.nd-view{
  width:100%;
}
.nd-section-head>div:first-child{
  min-width:0;
}
.nd-section-head h3{
  text-wrap:balance;
}
.nd-record-row>div:first-child{
  min-width:0;
}
.nd-record-row strong,
.nd-record-row small,
.nd-record-meta{
  overflow-wrap:anywhere;
}
.nd-empty-state{
